/** Pure helpers that turn a BacktestResult into the sentences and verdicts on the Model page. Owner: WP-18. */
import type { BacktestResult, PlayerCalibration, ReliabilityBin } from '@fmm/engine';

export const MIN_BIN_N = 10;
const HEADLINE_TARGET = 0.75;
/** Target coverage of the 80% range is 0.80; outside this band the range is off. */
export const NARROW_BELOW = 0.72;
export const WIDE_ABOVE = 0.88;

/** Bin whose midpoint is nearest 75% with at least MIN_BIN_N matchups. Null if no bin qualifies. */
export function headlineBin(bins: ReliabilityBin[]): ReliabilityBin | null {
  let best: ReliabilityBin | null = null;
  for (const b of bins) {
    if (b.n < MIN_BIN_N || !Number.isFinite(b.observed)) continue;
    if (!best || Math.abs((b.lo + b.hi) / 2 - HEADLINE_TARGET) < Math.abs((best.lo + best.hi) / 2 - HEADLINE_TARGET)) best = b;
  }
  return best;
}

/** 0.2051 vs 0.25 -> 18. Negative when the forecasts were worse than a coin flip. */
export function percentBetterThanCoin(brier: number, baseline: number): number {
  if (!Number.isFinite(brier) || !Number.isFinite(baseline) || baseline <= 0) return NaN;
  return Math.round((1 - brier / baseline) * 100);
}

export type Verdict = 'About right' | 'Too narrow' | 'Too wide' | 'No data';

/** Plain-English read of the 80% range. */
export function rangeVerdict(c: Pick<PlayerCalibration, 'n' | 'coverage80'>): Verdict {
  if (c.n === 0 || !Number.isFinite(c.coverage80)) return 'No data';
  if (c.coverage80 < NARROW_BELOW) return 'Too narrow';
  if (c.coverage80 > WIDE_ABOVE) return 'Too wide';
  return 'About right';
}

export const VERDICT_HELP: Record<Verdict, string> = {
  'About right': 'Results land inside our 80% range about 80% of the time.',
  'Too narrow': 'Results land outside our 80% range too often. Our range is too tight.',
  'Too wide': 'Results land inside our 80% range too often. Our range is too loose.',
  'No data': 'Not enough player results yet.',
};

export const POSITION_ORDER = ['ALL', 'QB', 'RB', 'WR', 'TE', 'K', 'DEF'] as const;

export function orderedPlayers(result: BacktestResult): PlayerCalibration[] {
  const rank = new Map<string, number>(POSITION_ORDER.map((p, i) => [p, i]));
  return [...result.players].sort((a, b) => (rank.get(a.position) ?? 99) - (rank.get(b.position) ?? 99));
}

export function pct(x: number, digits = 0): string {
  return Number.isFinite(x) ? `${(x * 100).toFixed(digits)}%` : '–';
}

export function signed(x: number, digits = 1): string {
  if (!Number.isFinite(x)) return '–';
  const s = Math.abs(x).toFixed(digits);
  return x > 0 ? `+${s}` : x < 0 ? `−${s}` : s;
}

export function count(n: number): string {
  return n.toLocaleString('en-US');
}
