/**
 * Featured: the matchup of the week, the biggest swing so far, and the longest shot on the board.
 * Owner: WP-13 (Haiku squad #3). Reuses viewer/team helpers from LeaguePage.
 */
import type { League, MatchupPrice } from '@fmm/core';
import { useApp, type ProbPoint } from '../state/store';
import { href } from '../lib/router';
import { pctPair } from '../lib/format';
import { TugBar } from '../components/TugBar';
import { SourceBadge, LiveBadge } from '../components/SourceBadge';
import { ProbabilityLine } from '../components/ProbabilityLine';
import { viewerRoster, teamOf } from './LeaguePage';
import './featured.css';

interface Swing { matchupId: number; teamA: number; teamB: number; points: ProbPoint[]; lo: number; hi: number; range: number }
interface Shot { price: MatchupPrice; side: 'A' | 'B'; cents: number; payout: number }

/** Matchup of the week: of the two highest combined projected totals, the one closest to a coin flip. */
function pickWeek(prices: MatchupPrice[]): MatchupPrice | undefined {
  const top = [...prices].sort((x, y) => (y.meanA + y.meanB) - (x.meanA + x.meanB)).slice(0, 2);
  return top.reduce<MatchupPrice | undefined>((best, p) => (!best || Math.abs(p.pWinA - 0.5) < Math.abs(best.pWinA - 0.5) ? p : best), undefined);
}

/** Biggest move in win chance so far, from matchups with at least three history points. */
function pickSwing(prices: MatchupPrice[], history: Record<number, ProbPoint[]>): Swing | null {
  let best: Swing | null = null;
  for (const p of prices) {
    const h = history[p.matchupId] ?? [];
    if (h.length < 3) continue;
    let lo = h[0].pA, hi = h[0].pA;
    for (const pt of h) { if (pt.pA < lo) lo = pt.pA; if (pt.pA > hi) hi = pt.pA; }
    const range = hi - lo;
    // Under one point of movement is noise, not a swing.
    if (range < 0.01) continue;
    if (!best || range > best.range) best = { matchupId: p.matchupId, teamA: p.teamA, teamB: p.teamB, points: h, lo, hi, range };
  }
  return best;
}

/** Longest shot: the underdog with the lowest win chance across all matchups. */
function pickShot(prices: MatchupPrice[]): Shot | null {
  let best: Shot | null = null;
  let bestP = Infinity;
  for (const p of prices) {
    const side: 'A' | 'B' = p.pWinA >= 0.5 ? 'B' : 'A';
    const [a, b] = pctPair(p.pWinA);
    const cents = side === 'A' ? a : b;
    const prob = cents / 100;
    if (prob < bestP) {
      bestP = prob;
      best = { price: p, side, cents, payout: Math.round(100 / cents) };
    }
  }
  return best;
}

export function FeaturedPage() {
  const s = useApp();
  const { league, prices, ctx, history } = s;

  if (!league) {
    return (
      <div className="empty">
        <h1 className="ft-title">Featured</h1>
        {s.status === 'error'
          ? <p className="error" role="alert">{s.error ?? "Couldn't load a league."}</p>
          : <p className="muted">No league loaded yet. Connect a Sleeper league to see the best games here.</p>}
        <a className="btn primary" href={href({ name: 'connect' })}>Connect a league</a>
      </div>
    );
  }

  const liveNow = !!ctx?.games.some((g) => g.status === 'in_progress');
  const header = (
    <header className="ft-head">
      <div className="ft-head-text">
        <h1 className="ft-title">Featured</h1>
        <p className="small muted">{league.name}, week {league.week}</p>
      </div>
      <div className="ft-head-badges">
        {liveNow && <LiveBadge text="Live" />}
        <SourceBadge />
      </div>
    </header>
  );

  if (!prices) {
    return (
      <div className="ft-page" aria-busy="true">
        {header}
        <div className="skeleton ft-skel" />
        <div className="skeleton ft-skel" />
      </div>
    );
  }

  const myRoster = viewerRoster(s);
  const week = pickWeek(prices);
  const swing = pickSwing(prices, history);
  const shot = pickShot(prices);

  return (
    <div className="ft-page">
      {header}
      {s.status === 'error' && <p className="error small" role="alert">{s.error ?? "Couldn't refresh this league."}</p>}

      {prices.length === 0 && <p className="muted">No matchups are priced yet. Check back once the week is set.</p>}

      {week && <WeekBlock league={league} price={week} myRoster={myRoster} />}

      <section className="ft-section" aria-labelledby="ft-swing">
        <h2 id="ft-swing" className="h2">Biggest swing</h2>
        {swing ? (
          <SwingBlock league={league} swing={swing} myRoster={myRoster} />
        ) : (
          <p className="muted">No swings yet: check back once games kick off.</p>
        )}
      </section>

      {shot && <ShotBlock league={league} shot={shot} myRoster={myRoster} />}

      <section className="ft-section ft-coming" aria-label="What is coming">
        <p className="muted">Creator leagues and expert leagues are coming: public leagues anyone can call.</p>
      </section>
    </div>
  );
}

function nameOf(league: League, rosterId: number): string {
  return teamOf(league, rosterId)?.name ?? `Team ${rosterId}`;
}

function WeekBlock({ league, price, myRoster }: { league: League; price: MatchupPrice; myRoster: number | null }) {
  const mine = myRoster != null && (myRoster === price.teamA || myRoster === price.teamB);
  const viewerIsB = mine && myRoster === price.teamB;
  const colorA = mine ? (viewerIsB ? 'rival' : 'you') : '';
  const colorB = mine ? (viewerIsB ? 'you' : 'rival') : '';
  const [a, b] = pctPair(price.pWinA);
  const matchupId = price.matchupId;
  return (
    <section className="ft-section" aria-labelledby="ft-week">
      <h2 id="ft-week" className="h2">Matchup of the week</h2>
      <a className="ft-score" href={href({ name: 'matchup', matchupId })}>
        <div className="ft-score-names">
          <span className={`ft-name ft-name-a ${colorA}`}>{nameOf(league, price.teamA)}</span>
          <span className={`ft-name ft-name-b ${colorB}`}>{nameOf(league, price.teamB)}</span>
        </div>
        <div className="ft-score-pcts">
          <span className={`num ft-big ${colorA}`}>{a}%</span>
          <span className={`num ft-big ft-big-b ${colorB}`}>{b}%</span>
        </div>
        <TugBar pA={price.pWinA} height={12} neutral={!mine} flip={viewerIsB} />
        <p className="small muted ft-meta">Projected {price.meanA.toFixed(1)} to {price.meanB.toFixed(1)}</p>
      </a>
    </section>
  );
}

function SwingBlock({ league, swing, myRoster }: { league: League; swing: Swing; myRoster: number | null }) {
  const a = nameOf(league, swing.teamA);
  const b = nameOf(league, swing.teamB);
  const mine = myRoster != null && (myRoster === swing.teamA || myRoster === swing.teamB);
  return (
    <a className="ft-card" href={href({ name: 'matchup', matchupId: swing.matchupId })}>
      <p className="ft-card-title">{a} vs {b}</p>
      <p className="small muted">
        Win chance for {a} ran from {Math.round(swing.lo * 100)}% to {Math.round(swing.hi * 100)}%.
        {mine ? ' You are in this one.' : ''}
      </p>
      <ProbabilityLine points={swing.points} height={140} />
    </a>
  );
}

function ShotBlock({ league, shot, myRoster }: { league: League; shot: Shot; myRoster: number | null }) {
  const p = shot.price;
  const dogId = shot.side === 'A' ? p.teamA : p.teamB;
  const favId = shot.side === 'A' ? p.teamB : p.teamA;
  const dog = nameOf(league, dogId);
  const fav = nameOf(league, favId);
  const mine = myRoster != null && (myRoster === p.teamA || myRoster === p.teamB);
  return (
    <section className="ft-section" aria-labelledby="ft-shot">
      <h2 id="ft-shot" className="h2">Longest shot</h2>
      <a className="ft-card" href={href({ name: 'matchup', matchupId: p.matchupId })}>
        <p className="ft-shot-copy">
          {dog} is {shot.cents}% to win. A call at {shot.cents}¢ pays {shot.payout} to 1.
        </p>
        <p className="small muted">Against {fav}.{mine ? ' You are in this one.' : ''}</p>
      </a>
    </section>
  );
}
