/** Scoreboard: the two team win chances, points under each, the tug bar, and the "most likely" line. Owner: WP-12. */
import { TugBar } from '../../components/TugBar';
import { pctPair, pts } from '../../lib/format';
import { likelyLine, other, shortName, teamName, teamTotals, toneOf, type Slot, type View } from './model';

export function Scoreboard({ v }: { v: View }) {
  const price = v.price;
  const left = v.you;
  const right = other(left);
  const pLeft = price ? (left === 'A' ? price.pWinA : price.pWinB) : null;
  return (
    <div className="mx-sb">
      <div className="mx-sb-row">
        <SideBlock v={v} slot={left} big />
        <SideBlock v={v} slot={right} />
      </div>
      {pLeft == null ? <div className="skeleton" style={{ height: 10 }} /> : <TugBar pA={pLeft} />}
    </div>
  );
}

function pointsLine(v: View, slot: Slot): string {
  if (v.final) return `${pts(slot === 'A' ? v.final.pointsA : v.final.pointsB)} pts, final`;
  if (!v.ctx) return 'Projected —';
  const t = teamTotals(v, slot);
  if (v.live) return `${pts(t.actual)} pts, ${t.left} ${t.left === 1 ? 'player' : 'players'} left`;
  const price = v.price;
  if (price) return `Projected ${pts(slot === 'A' ? price.meanA : price.meanB)}`;
  return `Projected ${pts(t.proj)}`;
}

function SideBlock({ v, slot, big = false }: { v: View; slot: Slot; big?: boolean }) {
  const tone = toneOf(v, slot);
  const team = v.teams[slot];
  const name = teamName(team, slot);
  const label = v.viewer === slot ? `You, ${name}` : name;
  const share = v.price ? pctPair(v.price.pWinA)[slot === 'A' ? 0 : 1] : null;
  return (
    <div className={`mx-side${big ? '' : ' mx-side-right'}`}>
      <span className="muted">{label}</span>
      <span className={`num ${big ? 'mx-big' : 'mx-small'}`} style={{ color: tone.color }}>
        {share == null ? '—' : `${share}%`}
      </span>
      <span className="mx-sb-pts tnum">{pointsLine(v, slot)}</span>
    </div>
  );
}

/** One plain sentence from the model's margin distribution. */
export function Likely({ v }: { v: View }) {
  if (!v.price) return <div className="skeleton" style={{ height: 22, width: '70%' }} />;
  return <p className="mx-likely-text">{likelyLine(v.price, shortName(v.teams.A, 'A'), shortName(v.teams.B, 'B'))}</p>;
}
