/**
 * Home: the reason to open the app. Hero = your matchup (or the closest game if you have no team), the rest of the
 * league below, a sample-Sunday replay on the built-in league, and a path to connect a Sleeper league.
 * Owner: WP-11 (wave 2 builder).
 */
import { priceCents, type League, type Matchup, type MatchupPrice } from '@fmm/core';
import {
  useApp, myMatchup, setDemoT, playDemo, stopDemo, loadDemo, useSampleLeague, type ProbPoint,
} from '../state/store';
import { href } from '../lib/router';
import { pctPair, pts, clock } from '../lib/format';
import { SourceBadge, LiveBadge } from '../components/SourceBadge';
import { TugBar } from '../components/TugBar';
import './home.css';

/** Sample Sunday runs 1:00 PM to 11:30 PM (t = 0..1). */
const SUNDAY_START_MIN = 13 * 60;
const SUNDAY_END_MIN = 23 * 60 + 30;

/** Demo progress t in [0,1] -> "1:52 PM" (no timezone maths: it is display text only). */
function sundayClock(t: number): string {
  const total = Math.round(SUNDAY_START_MIN + Math.min(1, Math.max(0, t)) * (SUNDAY_END_MIN - SUNDAY_START_MIN));
  const h24 = Math.floor(total / 60) % 24;
  const m = total % 60;
  const h12 = ((h24 + 11) % 12) + 1;
  return `${h12}:${String(m).padStart(2, '0')} ${h24 >= 12 ? 'PM' : 'AM'}`;
}

function teamLabel(league: League, rosterId: number): string {
  const t = league.teams.find((x) => x.rosterId === rosterId);
  return t?.managerName || t?.name || `Team ${rosterId}`;
}
function teamTitle(league: League, rosterId: number): string {
  return league.teams.find((t) => t.rosterId === rosterId)?.name ?? `Team ${rosterId}`;
}

function statusText(status: string): string {
  const s = status.replace(/_/g, ' ').trim();
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : '';
}

/** "Up from 27% at 1:52 PM" when the viewer's side has risen off its low during the replay or live week. */
function upFromText(points: ProbPoint[], viewerIsA: boolean, isDemo: boolean): string | null {
  const usable = points.filter((p) => !isDemo || (p.x >= 0 && p.x <= 1));
  if (usable.length < 3) return null;
  const sideP = (p: ProbPoint) => (viewerIsA ? p.pA : 1 - p.pA);
  const low = usable.reduce((m, p) => (sideP(p) < sideP(m) ? p : m), usable[0]);
  const last = usable[usable.length - 1];
  if (sideP(last) - sideP(low) < 0.01) return null;
  const when = isDemo ? sundayClock(low.x) : clock(low.x);
  return `Up from ${priceCents(sideP(low))}% at ${when}`;
}

function SkeletonHome() {
  return (
    <div className="home-skeleton" aria-busy="true" aria-label="Loading the league">
      <div className="skeleton home-skel-line" />
      <div className="skeleton home-skel-hero" />
      <div className="skeleton home-skel-bar" />
      <div className="skeleton home-skel-line short" />
      <div className="rows">
        {[0, 1, 2].map((i) => (
          <div key={i} className="row skeleton-row">
            <div className="skeleton home-skel-row" />
          </div>
        ))}
      </div>
    </div>
  );
}

export function HomePage() {
  const s = useApp();

  if (s.status === 'error') {
    return (
      <div className="empty" role="alert">
        <h2 className="h2">Your league didn't load</h2>
        <p className="muted">{s.error ?? 'Something went wrong.'} The sample league still works.</p>
        <button className="btn primary" type="button" onClick={() => void loadDemo()}>Load the sample league</button>
      </div>
    );
  }

  const league = s.league;
  if (!league || s.status === 'loading' || !s.prices) return <SkeletonHome />;

  const prices = s.prices;
  const priceById = new Map<number, MatchupPrice>(prices.map((p) => [p.matchupId, p]));
  const games = s.ctx?.games ?? [];
  const liveCount = games.filter((g) => g.status === 'in_progress').length;
  const isDemo = league.platform === 'demo';
  const live = s.demoT !== null || liveCount > 0;

  // Hero: your matchup, else the closest game this week.
  const mine = myMatchup();
  const closest = (): Matchup | undefined => {
    let best: { m: Matchup; gap: number } | undefined;
    for (const m of league.matchups) {
      const p = priceById.get(m.matchupId);
      if (!p) continue;
      const gap = Math.abs(p.pWinA - 0.5);
      if (!best || gap < best.gap) best = { m, gap };
    }
    return best?.m;
  };
  const heroM = mine ?? closest();
  const heroPrice = heroM ? priceById.get(heroM.matchupId) : undefined;

  const rest = league.matchups.filter((m) => m.matchupId !== heroM?.matchupId && priceById.has(m.matchupId));

  const timeLabel = s.demoT === null ? 'Pregame' : `Sunday ${sundayClock(s.demoT)}`;

  return (
    <div className="home">
      <header className="home-head">
        <p className="home-context">{league.name}, week {league.week}</p>
        <div className="home-badges">
          {liveCount > 0 && <LiveBadge text={`Live, ${liveCount} ${liveCount === 1 ? 'game' : 'games'} in progress`} />}
          <SourceBadge />
        </div>
      </header>

      {heroM && heroPrice ? (
        <Hero league={league} matchup={heroM} price={heroPrice} viewerMatched={!!mine} live={live} isDemo={isDemo}
          history={s.history[heroM.matchupId] ?? []} />
      ) : (
        <div className="empty">
          <h2 className="h2">No matchups this week</h2>
          <p className="muted">This league has no head-to-head games to price yet.</p>
        </div>
      )}

      {league.isSample && (
        <section className="home-section demo" aria-labelledby="demo-h">
          <div className="section-head">
            <h2 id="demo-h" className="h2">Watch a sample Sunday</h2>
            <span className="demo-clock tnum small" aria-live="polite">{timeLabel}</span>
          </div>
          <div className="demo-controls">
            <button className="btn" type="button" onClick={() => {
              if (s.demoPlaying) { stopDemo(); return; }
              if (s.demoT !== null && s.demoT >= 1) void setDemoT(0);
              playDemo();
            }}>
              {s.demoPlaying ? 'Pause' : 'Play'}
            </button>
            <input
              className="demo-slider"
              type="range"
              min={0}
              max={100}
              step={1}
              value={s.demoT === null ? 0 : Math.round(s.demoT * 100)}
              aria-label="Sample Sunday progress"
              aria-valuetext={timeLabel}
              onChange={(e) => { stopDemo(); void setDemoT(Number(e.target.value) / 100); }}
            />
            <button className="btn" type="button" disabled={s.demoT === null}
              onClick={() => { stopDemo(); void setDemoT(null); }}>
              Reset to pregame
            </button>
          </div>
        </section>
      )}

      {rest.length > 0 && (
        <section className="home-section" aria-labelledby="rest-h">
          <div className="section-head">
            <h2 id="rest-h" className="h2">Rest of the league</h2>
            <span className="small muted tnum">{rest.length} {rest.length === 1 ? 'game' : 'games'}</span>
          </div>
          <div className="rows">
            {rest.map((m) => (
              <MatchupRow key={m.matchupId} league={league} matchup={m} price={priceById.get(m.matchupId)!} />
            ))}
          </div>
        </section>
      )}

      {league.isSample ? (
        <section className="home-section connect" aria-labelledby="connect-h">
          <h2 id="connect-h" className="h2">Your league in 30 seconds</h2>
          <p className="muted">Type your Sleeper username. Read-only, no password.</p>
          <div className="home-actions">
            <a className="btn primary" href={href({ name: 'connect' })}>Connect my Sleeper league</a>
          </div>
        </section>
      ) : (
        <section className="home-section connect" aria-labelledby="connect-h">
          <h2 id="connect-h" className="h2">Your league</h2>
          <p className="muted">{league.name} is loaded from Sleeper. Coins stay on this device.</p>
          <div className="home-actions">
            <a className="btn" href={href({ name: 'connect' })}>Switch league</a>
            <button className="btn" type="button" onClick={() => void useSampleLeague()}>Use the sample league</button>
          </div>
        </section>
      )}
    </div>
  );
}

function Hero({ league, matchup, price, viewerMatched, live, isDemo, history }: {
  league: League; matchup: Matchup; price: MatchupPrice; viewerMatched: boolean; live: boolean; isDemo: boolean; history: ProbPoint[];
}) {
  // When you have a team, the viewer's side is cyan whichever slot they occupy. Otherwise side A is shown as cyan.
  const viewerIsA = viewerMatched ? matchup.teamA === league.myRosterId : true;
  const viewerRoster = viewerIsA ? matchup.teamA : matchup.teamB;
  const rivalRoster = viewerIsA ? matchup.teamB : matchup.teamA;
  const viewerP = viewerIsA ? price.pWinA : price.pWinB;
  const viewerMean = viewerIsA ? price.meanA : price.meanB;
  const rivalMean = viewerIsA ? price.meanB : price.meanA;
  const [viewerPct, rivalPct] = pctPair(viewerP);

  const topLabel = viewerMatched ? `You vs ${teamLabel(league, rivalRoster)}` : 'Closest game this week';
  const viewerName = viewerMatched ? 'You' : teamLabel(league, viewerRoster);
  const rivalName = teamLabel(league, rivalRoster);
  const numbers = live
    ? `${pts(viewerMean)} to ${pts(rivalMean)} live`
    : `Projected ${pts(viewerMean)} to ${pts(rivalMean)}`;
  const up = live ? upFromText(history, viewerIsA, isDemo) : null;

  return (
    <a className="hero" href={href({ name: 'matchup', matchupId: matchup.matchupId })}
      aria-label={`${topLabel}: ${viewerName} ${viewerPct}%, ${rivalName} ${rivalPct}%. Open the matchup.`}>
      <span className="small muted hero-top">{topLabel}</span>
      <div className="hero-sides">
        <div className="hero-you">
          {!viewerMatched && <span className="small muted">{viewerName}</span>}
          <span className="num you hero-num">{viewerPct}%</span>
        </div>
        <div className="hero-rival">
          <span className="small muted">{rivalName}</span>
          <span className="num rival hero-rival-num">{rivalPct}%</span>
        </div>
      </div>
      <TugBar pA={viewerP} height={10} />
      <div className="hero-foot">
        <span className="small tnum muted">{numbers}</span>
        {up && <span className="small live">{up}</span>}
      </div>
    </a>
  );
}

function MatchupRow({ league, matchup, price }: { league: League; matchup: Matchup; price: MatchupPrice }) {
  const nameA = teamTitle(league, matchup.teamA);
  const nameB = teamTitle(league, matchup.teamB);
  const [a, b] = pctPair(price.pWinA);
  const aClass = price.pWinA > 0.5 ? 'fav' : price.pWinA < 0.5 ? 'dog' : 'fav';
  const bClass = price.pWinA < 0.5 ? 'fav' : price.pWinA > 0.5 ? 'dog' : 'fav';
  return (
    <a className="row match-row" href={href({ name: 'matchup', matchupId: matchup.matchupId })}
      aria-label={`${nameA} ${a}%, ${nameB} ${b}%. Open the matchup.`}>
      <div className="match-body">
        <div className="match-names">
          <span>{nameA}</span>
          <span>{nameB}</span>
        </div>
        <div className="match-line">
          <span className={`num match-pct ${aClass}`}>{a}</span>
          <TugBar neutral height={4} pA={price.pWinA} />
          <span className={`num match-pct ${bClass}`}>{b}</span>
        </div>
      </div>
    </a>
  );
}
