/** Tells the user where the number comes from. Required next to every price (placeholder model in Phase 0). Owner: Commander. */
import { useApp } from '../state/store';
export function SourceBadge() {
  const s = useApp();
  if (!s.league) return null;
  if (s.league.isSample) return <span className="badge" title="Fictional league and sample projections, so you can try everything without connecting.">Sample league, sample projections</span>;
  const label = s.source === 'sleeper-weekly' ? 'Sleeper weekly projections (unofficial feed)' : 'Rough projections (rank-based)';
  return <span className="badge" title="Phase 0 prototype model. Not a licensed projection feed.">{label}</span>;
}
export function LiveBadge({ text }: { text: string }) {
  return <span className="badge live"><span className="dot" />{text}</span>;
}
