/**
 * Pure helpers for the Matchup page: which side is which, points, lineups, driver status, and the plain-English
 * lines. No React here. Owner: WP-12.
 */
import type { Driver, FantasyTeam, League, Matchup, MatchupPrice, WeekContext } from '@fmm/core';
import { scoreStatLine } from '@fmm/engine';
import { clock, pts } from '../../lib/format';

/** A = team A (YES), B = team B (NO). */
export type Slot = 'A' | 'B';

export interface View {
  league: League;
  ctx?: WeekContext;
  matchup: Matchup;
  price?: MatchupPrice;
  teams: Record<Slot, FantasyTeam | undefined>;
  /** Which side the viewer is, or null when they are not in this game. */
  viewer: Slot | null;
  /** The slot drawn in cyan (the viewer's side; team A when the viewer is not in the game). */
  you: Slot;
  /** True when any game is in progress. */
  live: boolean;
  liveGames: number;
  final?: { pointsA: number; pointsB: number };
}

export function buildView(
  league: League,
  ctx: WeekContext | undefined,
  matchup: Matchup,
  price: MatchupPrice | undefined,
  final: { pointsA: number; pointsB: number } | undefined,
): View {
  const mine = league.myRosterId;
  const viewer: Slot | null =
    mine == null ? null : mine === matchup.teamA ? 'A' : mine === matchup.teamB ? 'B' : null;
  const teams = league.teams ?? [];
  const liveGames = (ctx?.games ?? []).filter((g) => g.status === 'in_progress').length;
  return {
    league,
    ctx,
    matchup,
    price,
    teams: {
      A: teams.find((t) => t.rosterId === matchup.teamA),
      B: teams.find((t) => t.rosterId === matchup.teamB),
    },
    viewer,
    you: viewer === 'B' ? 'B' : 'A',
    live: liveGames > 0,
    liveGames,
    final,
  };
}

export interface Tone { color: string; wash: string; cls: 'you' | 'rival' }

/** Cyan for the viewer's side (team A when the viewer is not in the game), pink for the other side. */
export function toneOf(v: View, slot: Slot): Tone {
  return slot === v.you
    ? { color: 'var(--color-you)', wash: 'var(--color-you-wash)', cls: 'you' }
    : { color: 'var(--color-rival)', wash: 'var(--color-rival-wash)', cls: 'rival' };
}

export function other(slot: Slot): Slot { return slot === 'A' ? 'B' : 'A'; }

/** Manager first (the short name used on buttons), else the team name. */
export function shortName(team: FantasyTeam | undefined, slot: Slot): string {
  if (!team) return slot === 'A' ? 'Team A' : 'Team B';
  const manager = team.managerName?.trim();
  // The viewer's own roster is stored as manager "You"; read the owner from "Shain's Squad" instead.
  if (manager && manager.toLowerCase() !== 'you') return manager;
  const owner = team.name?.split("'s ")[0]?.trim();
  return owner || team.name || 'Team';
}

export function teamName(team: FantasyTeam | undefined, slot: Slot): string {
  if (!team) return slot === 'A' ? 'Team A' : 'Team B';
  return team.name?.trim() || team.managerName || 'Team';
}

export function isStarter(pid: string): boolean { return pid !== '' && pid !== '0'; }

/** Share of this player's game still to play: 0 = nothing left (or no game this week), 1 = not started. */
export function playerFraction(ctx: WeekContext, pid: string): number {
  const live = ctx.live?.[pid];
  if (live) return live.fractionRemaining ?? 1;
  const proj = ctx.projections[pid];
  if (!proj) return 0;
  const game = proj.gameId ? ctx.games.find((g) => g.gameId === proj.gameId) : undefined;
  if (!game) return 1;
  if (game.status === 'complete') return 0;
  if (game.status === 'in_progress') return game.fractionRemaining ?? 0.5;
  return 1;
}

/** True once the player's game has kicked off (live stats exist and some of the game is done). */
export function hasStarted(ctx: WeekContext, pid: string): boolean {
  const l = ctx.live?.[pid];
  return !!l && (l.fractionRemaining ?? 1) < 1;
}

export function projPts(v: View, pid: string): number {
  const p = v.ctx?.projections[pid];
  return p ? scoreStatLine(p.mean, v.league.scoring, p.position) : 0;
}

export function livePts(v: View, pid: string): number {
  const actual = v.ctx?.live?.[pid]?.actual;
  if (!actual) return 0;
  return scoreStatLine(actual, v.league.scoring, v.ctx?.projections[pid]?.position ?? 'UNK');
}

export interface TeamTotals { proj: number; actual: number; left: number }

export function teamTotals(v: View, slot: Slot): TeamTotals {
  const out: TeamTotals = { proj: 0, actual: 0, left: 0 };
  const team = v.teams[slot];
  const ctx = v.ctx;
  if (!team || !ctx) return out;
  for (const pid of team.starters ?? []) {
    if (!isStarter(pid)) continue;
    out.proj += projPts(v, pid);
    out.actual += livePts(v, pid);
    if (playerFraction(ctx, pid) > 0) out.left += 1;
  }
  return out;
}

/** "yours" for the viewer's own players, else "Dave's". */
export function ownerText(v: View, side: Slot): string {
  if (v.viewer === side) return 'yours';
  return `${shortName(v.teams[side], side)}'s`;
}

export function driverStatus(v: View, d: Driver): string {
  switch (d.status) {
    case 'final': {
      const p = v.ctx?.live?.[d.playerId] ? livePts(v, d.playerId) : d.meanPts;
      return `Final, ${pts(p)} pts`;
    }
    case 'live': {
      const p = v.ctx?.live?.[d.playerId] ? livePts(v, d.playerId) : d.meanPts;
      return `Playing, ${pts(p)} pts so far`;
    }
    case 'out':
      return 'Out';
    default: {
      const gid = v.ctx?.projections[d.playerId]?.gameId;
      const game = gid ? v.ctx?.games.find((g) => g.gameId === gid) : undefined;
      return game?.kickoff ? `Kicks off ${clock(game.kickoff)}` : 'Not started';
    }
  }
}

/** Margin in points, A minus B, phrased as "Shain by 7" (or "level"). */
function marginPhrase(m: number, na: string, nb: string): string {
  const r = Math.round(m);
  if (r === 0) return 'level';
  return r > 0 ? `${na} by ${r}` : `${nb} by ${-r}`;
}

export function likelyLine(price: MatchupPrice, na: string, nb: string): string {
  const med = Math.round(price.margin.p50);
  const head = med === 0 ? 'Most likely a close game.' : `Most likely ${med > 0 ? na : nb} by ${Math.abs(med)}.`;
  const range = `In 8 of every 10 simulated weeks, it ends somewhere between ${marginPhrase(price.margin.p10, na, nb)} and ${marginPhrase(price.margin.p90, na, nb)}.`;
  return `${head} ${range}`;
}
