/**
 * WP-5 — Market book: one LMSR market per matchup (or per snapshot series), with positions and the ledger.
 * League Mode: free coins, no fees, house is the only counterparty, settles on the platform's official result.
 *
 * Owner: WP-5. Imports allowed: '@fmm/core', './lmsr', './ledger'.
 *
 * Money flow (all integer cc via chargeCc/payCc from @fmm/core):
 *  - open(): no money moves. The market records b, the seeded state, and maxLossCc = chargeCc(maxLoss).
 *  - buy: user pays chargeCc(costToBuy) -> 'mm:<marketId>'. Position += shares.
 *  - sell: user receives payCc(-costToBuy(negative shares)) from 'mm:<marketId>'. Cannot sell more than held.
 *    If the mm account lacks funds for a sell, 'house:treasury' tops it up in the SAME entry.
 *  - settle(winner): for each position, payout = shares * PAYOUT_CC_PER_SHARE (or TIE_PAYOUT_CC_PER_SHARE each
 *    side on 'TIE'), floored to integer cc, from 'mm:<marketId>'; shortfall comes from 'house:treasury';
 *    leftover in mm after payouts sweeps to 'house:treasury'. mm ends at exactly 0.
 *  - Every money movement is ONE ledger.post with idempotencyKey:
 *      buy/sell: `trade:${marketId}:${clientOrderId}`; settle: `settle:${marketId}`; grant: `grant:${userId}:${reason}`.
 *  - Shares are whole numbers (integers >= 1). Reject fractional shares.
 *
 * Decisions beyond the stub:
 *  - A buy always charges at least 1 cc. Below that, chargeCc would round a tiny LMSR cost to 0 and give shares away.
 *  - Fill.priceAfter and Fill.avgPrice refer to the traded side (YES price for YES shares, NO price for NO shares).
 *  - A sell reduces costBasisCc to floor(costBasisCc * heldAfter / heldBefore), where held counts YES plus NO shares.
 *  - Each trade memo is JSON with the full fill. Replays read it back from the ledger, so they survive toJSON/fromJSON.
 */
import { CC_PER_COIN, PAYOUT_CC_PER_SHARE, TIE_PAYOUT_CC_PER_SHARE, chargeCc, payCc, type Side } from '@fmm/core';
import { applyTrade, bForLossBudget, costToBuy, initAtPrice, maxLoss, priceOf, priceYes, type LmsrState } from './lmsr';
import { LedgerError, type JournalEntry, type Ledger, type LedgerLine } from './ledger';

export type MarketStatus = 'open' | 'halted' | 'closed' | 'settled';
export type Outcome = 'YES' | 'NO' | 'TIE' | 'VOID';

export interface MarketInfo {
  marketId: string;
  /** Human label, e.g. "Shain's Squad beats Dave's Dynasty". YES = team A wins. */
  title: string;
  status: MarketStatus;
  state: LmsrState;
  openedAt: string;
  /** Model fair probability for YES at open. */
  fairAtOpen: number;
  maxLossCc: number;
  outcome?: Outcome;
}

export interface Position { userId: string; marketId: string; yes: number; no: number; costBasisCc: number }

export interface TradeRequest {
  marketId: string;
  userId: string;
  side: Side;
  /** Whole shares, > 0. */
  shares: number;
  /** Client-generated unique id; reusing it replays the original fill. */
  clientOrderId: string;
  ts: string;
}

export interface Fill {
  marketId: string; userId: string; side: Side; shares: number;
  /** Positive for buys (paid), negative for sells (received). */
  amountCc: number;
  avgPrice: number;
  priceAfter: number;
  replayed: boolean;
}

export class MarketError extends Error { constructor(public code: 'NO_MARKET' | 'NOT_OPEN' | 'BAD_SHARES' | 'INSUFFICIENT_SHARES' | 'INSUFFICIENT_FUNDS' | 'ALREADY_SETTLED', msg: string) { super(msg); this.name = 'MarketError'; } }

const TREASURY = 'house:treasury';
const GRANTS = 'house:grants';
const userAcct = (userId: string): string => `user:${userId}`;
const mmAcct = (marketId: string): string => `mm:${marketId}`;
const tradeKey = (marketId: string, clientOrderId: string): string => `trade:${marketId}:${clientOrderId}`;

/** Shape of the JSON memo written with every trade. Replays are rebuilt from it. */
interface TradeMemo {
  kind: 'buy' | 'sell';
  marketId: string;
  userId: string;
  side: Side;
  shares: number;
  amountCc: number;
  avgPrice: number;
  priceAfter: number;
}

function assertWholeShares(shares: number): void {
  if (!Number.isSafeInteger(shares) || shares <= 0) {
    throw new MarketError('BAD_SHARES', `shares must be a whole number >= 1, got ${shares}`);
  }
}

function assertSide(side: Side): void {
  if (side !== 'YES' && side !== 'NO') throw new Error(`side must be YES or NO, got ${String(side)}`);
}

/** Buyer's charge in cc: LMSR cost rounded up, never less than 1 cc. */
function buyChargeCc(state: LmsrState, side: Side, shares: number): number {
  return Math.max(1, chargeCc(costToBuy(state, side, shares)));
}

/** Settlement payout in cc for one position, floored to whole cc. */
function payoutFor(pos: Position, outcome: Outcome): number {
  switch (outcome) {
    case 'YES': return Math.floor(pos.yes * PAYOUT_CC_PER_SHARE);
    case 'NO': return Math.floor(pos.no * PAYOUT_CC_PER_SHARE);
    case 'TIE': return Math.floor((pos.yes + pos.no) * TIE_PAYOUT_CC_PER_SHARE);
    case 'VOID': return pos.costBasisCc;
  }
}

function copyMarket(m: MarketInfo): MarketInfo {
  return { ...m, state: { ...m.state } };
}

function parseTradeMemo(memo: string): Partial<TradeMemo> {
  try {
    const parsed: unknown = JSON.parse(memo);
    return parsed && typeof parsed === 'object' ? (parsed as Partial<TradeMemo>) : {};
  } catch {
    return {};
  }
}

/** Rebuild the original fill from its ledger entry. Throws if the key was reused for a different order. */
function replayFill(prior: JournalEntry, kind: 'buy' | 'sell', req: TradeRequest): Fill {
  const memo = parseTradeMemo(prior.memo);
  if (
    memo.kind !== kind ||
    memo.marketId !== req.marketId ||
    memo.userId !== req.userId ||
    memo.side !== req.side ||
    memo.shares !== req.shares ||
    typeof memo.amountCc !== 'number' ||
    typeof memo.avgPrice !== 'number' ||
    typeof memo.priceAfter !== 'number'
  ) {
    throw new LedgerError('IDEMPOTENCY_CONFLICT', `clientOrderId ${req.clientOrderId} was already used for a different order`);
  }
  return {
    marketId: req.marketId,
    userId: req.userId,
    side: req.side,
    shares: req.shares,
    amountCc: memo.amountCc,
    avgPrice: memo.avgPrice,
    priceAfter: memo.priceAfter,
    replayed: true,
  };
}

export class MarketBook {
  private readonly markets = new Map<string, MarketInfo>();
  /** marketId -> userId -> position. */
  private readonly positionsByMarket = new Map<string, Map<string, Position>>();

  constructor(public readonly ledger: Ledger) {}

  /** Give a user free coins from 'house:grants' (idempotent per reason). */
  grant(userId: string, cc: number, reason: string, ts: string): void {
    if (!Number.isSafeInteger(cc) || cc <= 0) throw new RangeError(`grant must be a positive integer of cc, got ${cc}`);
    this.ledger.post({
      idempotencyKey: `grant:${userId}:${reason}`,
      lines: [
        { account: userAcct(userId), amountCc: cc },
        { account: GRANTS, amountCc: -cc },
      ],
      memo: JSON.stringify({ kind: 'grant', userId, reason, cc }),
      ts,
    });
  }

  /** Open a market seeded at fairP with b sized by bForLossBudget(fairP, lossBudgetCoins). Re-opening an existing id throws. */
  open(marketId: string, title: string, fairP: number, lossBudgetCoins: number, ts: string): MarketInfo {
    if (this.markets.has(marketId)) throw new Error(`market ${marketId} already exists`);
    const b = bForLossBudget(fairP, lossBudgetCoins);
    const state = initAtPrice(fairP, b);
    const info: MarketInfo = {
      marketId,
      title,
      status: 'open',
      state,
      openedAt: ts,
      fairAtOpen: priceYes(state),
      maxLossCc: chargeCc(maxLoss(state)),
    };
    this.markets.set(marketId, info);
    this.positionsByMarket.set(marketId, new Map());
    return copyMarket(info);
  }

  get(marketId: string): MarketInfo | undefined {
    const m = this.markets.get(marketId);
    return m ? copyMarket(m) : undefined;
  }

  list(): MarketInfo[] {
    return [...this.markets.values()].map(copyMarket);
  }

  /** Current YES price. */
  price(marketId: string): number {
    return priceYes(this.mustGet(marketId).state);
  }

  /** Preview a buy without changing state: { costCc, avgPrice, priceAfter }. */
  quote(marketId: string, side: Side, shares: number): { costCc: number; avgPrice: number; priceAfter: number } {
    const m = this.mustGet(marketId);
    assertSide(side);
    assertWholeShares(shares);
    const costCc = buyChargeCc(m.state, side, shares);
    return {
      costCc,
      avgPrice: costCc / CC_PER_COIN / shares,
      priceAfter: priceOf(applyTrade(m.state, side, shares), side),
    };
  }

  buy(req: TradeRequest): Fill {
    return this.trade('buy', req);
  }

  sell(req: TradeRequest): Fill {
    return this.trade('sell', req);
  }

  halt(marketId: string): void {
    const m = this.mustGet(marketId);
    if (m.status === 'settled') throw new MarketError('ALREADY_SETTLED', `market ${marketId} is settled`);
    if (m.status === 'closed') throw new MarketError('NOT_OPEN', `market ${marketId} is closed and cannot be halted`);
    m.status = 'halted';
  }

  resume(marketId: string): void {
    const m = this.mustGet(marketId);
    if (m.status === 'settled') throw new MarketError('ALREADY_SETTLED', `market ${marketId} is settled`);
    if (m.status === 'closed') throw new MarketError('NOT_OPEN', `market ${marketId} is closed and cannot be resumed`);
    m.status = 'open';
  }

  /** Close to new trades (final lineup lock). */
  close(marketId: string): void {
    const m = this.mustGet(marketId);
    if (m.status === 'settled') throw new MarketError('ALREADY_SETTLED', `market ${marketId} is settled`);
    m.status = 'closed';
  }

  /** Pay out and mark settled. Idempotent: settling twice with the same outcome is a no-op; different outcome throws. VOID refunds costBasisCc. */
  settle(marketId: string, outcome: Outcome, ts: string): void {
    const m = this.mustGet(marketId);
    if (outcome !== 'YES' && outcome !== 'NO' && outcome !== 'TIE' && outcome !== 'VOID') {
      throw new Error(`unknown outcome ${String(outcome)}`);
    }
    if (m.status === 'settled') {
      if (m.outcome === outcome) return;
      throw new MarketError('ALREADY_SETTLED', `market ${marketId} already settled as ${m.outcome}, cannot settle as ${outcome}`);
    }

    const mm = mmAcct(marketId);
    const mmBal = this.ledger.balance(mm);
    const payouts: LedgerLine[] = [];
    let total = 0;
    for (const pos of this.positionsByMarket.get(marketId)?.values() ?? []) {
      const pay = payoutFor(pos, outcome);
      if (pay > 0) {
        payouts.push({ account: userAcct(pos.userId), amountCc: pay });
        total += pay;
      }
    }
    // Sweep the whole mm balance out, pay winners, and let the treasury absorb the difference (shortfall or leftover).
    const lines: LedgerLine[] = [...payouts, { account: mm, amountCc: -mmBal }, { account: TREASURY, amountCc: mmBal - total }];
    this.post(`settle:${marketId}`, lines, undefined, { kind: 'settle', marketId, outcome, payoutCc: total }, ts);

    m.status = 'settled';
    m.outcome = outcome;
  }

  position(userId: string, marketId: string): Position {
    const pos = this.positionsByMarket.get(marketId)?.get(userId);
    return pos ? { ...pos } : { userId, marketId, yes: 0, no: 0, costBasisCc: 0 };
  }

  positions(userId: string): Position[] {
    const out: Position[] = [];
    for (const byUser of this.positionsByMarket.values()) {
      const pos = byUser.get(userId);
      if (pos) out.push({ ...pos });
    }
    return out;
  }

  /** Mark-to-market value of a position at current price, in cc (floor). */
  markValueCc(userId: string, marketId: string): number {
    const m = this.mustGet(marketId);
    const pos = this.position(userId, marketId);
    if (m.status === 'settled' && m.outcome) return payoutFor(pos, m.outcome);
    return payCc(pos.yes * priceOf(m.state, 'YES') + pos.no * priceOf(m.state, 'NO'));
  }

  /**
   * League Mode only: move the market to a new model price without moving money. Shifts qYes by `shift`
   * (= b * (logit(newFair) - logit(oldFair))), which keeps any skew from user flow. Any extra liability this
   * creates for the house is covered from 'house:treasury' at settlement. Ignored unless open or halted.
   */
  recentre(marketId: string, shift: number): void {
    const m = this.mustGet(marketId);
    if (m.status !== 'open' && m.status !== 'halted') return;
    if (!Number.isFinite(shift) || shift === 0) return;
    m.state = { ...m.state, qYes: m.state.qYes + shift };
  }

  /** Serialize markets + positions (ledger serialized separately). */
  toJSON(): unknown {
    const positions: Position[] = [];
    for (const byUser of this.positionsByMarket.values()) {
      for (const pos of byUser.values()) positions.push({ ...pos });
    }
    return { version: 1, markets: this.list(), positions };
  }

  static fromJSON(data: unknown, ledger: Ledger): MarketBook {
    const d = data as { markets?: unknown; positions?: unknown } | null;
    if (!d || !Array.isArray(d.markets) || !Array.isArray(d.positions)) {
      throw new Error('MarketBook.fromJSON: malformed data');
    }
    const book = new MarketBook(ledger);
    for (const raw of d.markets as MarketInfo[]) {
      const { marketId, state, status } = raw;
      if (!marketId || !(Number.isFinite(state?.b) && state.b > 0) || !Number.isFinite(state.qYes) || !Number.isFinite(state.qNo)) {
        throw new Error(`MarketBook.fromJSON: bad market ${String(marketId)}`);
      }
      if (!['open', 'halted', 'closed', 'settled'].includes(status)) throw new Error(`MarketBook.fromJSON: bad status for ${marketId}`);
      if (status === 'settled' && !raw.outcome) throw new Error(`MarketBook.fromJSON: settled market ${marketId} has no outcome`);
      book.markets.set(marketId, copyMarket(raw));
      book.positionsByMarket.set(marketId, new Map());
    }
    for (const raw of d.positions as Position[]) {
      const byUser = book.positionsByMarket.get(raw.marketId);
      if (!byUser) throw new Error(`MarketBook.fromJSON: position for unknown market ${raw.marketId}`);
      byUser.set(raw.userId, { ...raw });
    }
    return book;
  }

  private mustGet(marketId: string): MarketInfo {
    const m = this.markets.get(marketId);
    if (!m) throw new MarketError('NO_MARKET', `no market ${marketId}`);
    return m;
  }

  private ensurePosition(userId: string, marketId: string): Position {
    const byUser = this.positionsByMarket.get(marketId);
    if (!byUser) throw new MarketError('NO_MARKET', `no market ${marketId}`);
    let pos = byUser.get(userId);
    if (!pos) {
      pos = { userId, marketId, yes: 0, no: 0, costBasisCc: 0 };
      byUser.set(userId, pos);
    }
    return pos;
  }

  private post(key: string, lines: LedgerLine[], nonNegative: string[] | undefined, memo: object, ts: string): void {
    try {
      this.ledger.post({ idempotencyKey: key, lines, memo: JSON.stringify(memo), ts, nonNegative });
    } catch (err) {
      if (err instanceof LedgerError && err.code === 'INSUFFICIENT_FUNDS') {
        throw new MarketError('INSUFFICIENT_FUNDS', err.message);
      }
      throw err;
    }
  }

  private trade(kind: 'buy' | 'sell', req: TradeRequest): Fill {
    const key = tradeKey(req.marketId, req.clientOrderId);
    const prior = this.ledger.find(key);
    if (prior) return replayFill(prior, kind, req);

    const m = this.mustGet(req.marketId);
    assertSide(req.side);
    assertWholeShares(req.shares);
    if (m.status !== 'open') throw new MarketError('NOT_OPEN', `market ${req.marketId} is ${m.status}`);
    return kind === 'buy' ? this.doBuy(m, req, key) : this.doSell(m, req, key);
  }

  private doBuy(m: MarketInfo, req: TradeRequest, key: string): Fill {
    const amountCc = buyChargeCc(m.state, req.side, req.shares);
    const user = userAcct(req.userId);
    if (this.ledger.balance(user) < amountCc) {
      throw new MarketError('INSUFFICIENT_FUNDS', `user ${req.userId} needs ${amountCc} cc, has ${this.ledger.balance(user)}`);
    }
    const next = applyTrade(m.state, req.side, req.shares);
    const fill: Fill = {
      marketId: req.marketId,
      userId: req.userId,
      side: req.side,
      shares: req.shares,
      amountCc,
      avgPrice: amountCc / CC_PER_COIN / req.shares,
      priceAfter: priceOf(next, req.side),
      replayed: false,
    };
    const memo: TradeMemo = {
      kind: 'buy',
      marketId: req.marketId,
      userId: req.userId,
      side: req.side,
      shares: req.shares,
      amountCc,
      avgPrice: fill.avgPrice,
      priceAfter: fill.priceAfter,
    };
    this.post(
      key,
      [
        { account: user, amountCc: -amountCc },
        { account: mmAcct(req.marketId), amountCc },
      ],
      [user],
      memo,
      req.ts,
    );

    m.state = next;
    const pos = this.ensurePosition(req.userId, req.marketId);
    pos.costBasisCc += amountCc;
    if (req.side === 'YES') pos.yes += req.shares;
    else pos.no += req.shares;
    return fill;
  }

  private doSell(m: MarketInfo, req: TradeRequest, key: string): Fill {
    const held = this.position(req.userId, req.marketId);
    const heldSide = req.side === 'YES' ? held.yes : held.no;
    if (req.shares > heldSide) {
      throw new MarketError('INSUFFICIENT_SHARES', `user ${req.userId} holds ${heldSide} ${req.side}, cannot sell ${req.shares}`);
    }

    const proceeds = -costToBuy(m.state, req.side, -req.shares);
    const amountCc = Math.max(0, payCc(proceeds));
    const mm = mmAcct(req.marketId);
    const mmBal = this.ledger.balance(mm);
    const topup = Math.max(0, amountCc - mmBal);
    const lines: LedgerLine[] = [
      { account: userAcct(req.userId), amountCc },
      { account: mm, amountCc: topup - amountCc },
    ];
    if (topup > 0) lines.push({ account: TREASURY, amountCc: -topup });

    const next = applyTrade(m.state, req.side, -req.shares);
    const fill: Fill = {
      marketId: req.marketId,
      userId: req.userId,
      side: req.side,
      shares: req.shares,
      amountCc: -amountCc,
      avgPrice: amountCc / CC_PER_COIN / req.shares,
      priceAfter: priceOf(next, req.side),
      replayed: false,
    };
    const memo: TradeMemo = {
      kind: 'sell',
      marketId: req.marketId,
      userId: req.userId,
      side: req.side,
      shares: req.shares,
      amountCc: -amountCc,
      avgPrice: fill.avgPrice,
      priceAfter: fill.priceAfter,
    };
    this.post(key, lines, [mm], memo, req.ts);

    m.state = next;
    const pos = this.ensurePosition(req.userId, req.marketId);
    const heldBefore = pos.yes + pos.no;
    const heldAfter = heldBefore - req.shares;
    if (req.side === 'YES') pos.yes -= req.shares;
    else pos.no -= req.shares;
    pos.costBasisCc = Math.floor((pos.costBasisCc * heldAfter) / heldBefore);
    return fill;
  }
}
