/**
 * Share card: draws a 1080x1350 PNG on a canvas, previews it as an <img>, and offers Download and (when the
 * browser can share files) native Share. Owner: WP-14.
 */
import { useEffect, useRef, useState } from 'react';

export interface ShareCardProps {
  /** Line under the big percentage, e.g. "Called it." or "Backing Shain's Squad at 62%". */
  headline: string;
  /** Big number, drawn as "27%". */
  pct: number;
  /** Small line at the bottom of the text block, e.g. "Shain's Squad over Dave's Dynasty, week 8". */
  subline: string;
  /** Settled and won (shows a "Won" tag). Open calls pass false and show "Open call". */
  won: boolean;
}

const W = 1080;
const H = 1350;
const PAD = 88;
const CYAN = '#00e5ff';
const PINK = '#ff2d87';
const WHITE = '#f4f4f4';
const MUTED = '#9a9a9a';
const RULE = '#2a2a2a';
const DISPLAY = 'Archivo, "Arial Narrow", Arial, sans-serif';
const TEXT = 'Archivo, system-ui, Arial, sans-serif';
const FILE_NAME = 'called-it.png';

function setStretch(ctx: CanvasRenderingContext2D, value: 'normal' | 'extra-condensed') {
  // Archivo's wdth axis 62 is CSS "extra-condensed" (62.5%). Browsers without fontStretch fall back to plain bold.
  if ('fontStretch' in ctx) ctx.fontStretch = value;
}
function displayFont(ctx: CanvasRenderingContext2D, px: number) {
  ctx.font = `900 ${px}px ${DISPLAY}`;
  setStretch(ctx, 'extra-condensed');
}
function textFont(ctx: CanvasRenderingContext2D, weight: number, px: number) {
  ctx.font = `${weight} ${px}px ${TEXT}`;
  setStretch(ctx, 'normal');
}

/** Greedy word wrap; the last allowed line gets an ellipsis if text is left over. */
function wrap(ctx: CanvasRenderingContext2D, text: string, maxWidth: number, maxLines: number): string[] {
  const words = text.split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let line = '';
  for (const word of words) {
    const test = line ? `${line} ${word}` : word;
    if (!line || ctx.measureText(test).width <= maxWidth) {
      line = test;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line) lines.push(line);
  if (lines.length <= maxLines) return lines;
  const kept = lines.slice(0, maxLines);
  let last = kept[maxLines - 1];
  while (last.length > 1 && ctx.measureText(`${last}…`).width > maxWidth) last = last.slice(0, -1).trimEnd();
  kept[maxLines - 1] = `${last}…`;
  return kept;
}

function drawCard(ctx: CanvasRenderingContext2D, p: ShareCardProps) {
  const maxW = W - PAD * 2;
  ctx.textBaseline = 'alphabetic';
  ctx.textAlign = 'left';
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, W, H);

  // Layout: text block is centred in the area above the footer rule.
  const pctPx = 300;
  const headPx = 116;
  const subPx = 44;
  const pctCap = 216;
  const headGap = 120;
  const headStep = 118;
  const subGap = 90;
  const subStep = 58;

  displayFont(ctx, headPx);
  const headLines = wrap(ctx, p.headline, maxW, 3);
  textFont(ctx, 400, subPx);
  const subLines = wrap(ctx, p.subline, maxW, 2);

  const offset = pctCap + headGap + (headLines.length - 1) * headStep + subGap + (subLines.length - 1) * subStep;
  const top = 640 - offset / 2;
  const pctBase = top + pctCap;

  // Status tag.
  textFont(ctx, 600, 44);
  ctx.fillStyle = CYAN;
  ctx.fillText(p.won ? 'Won' : 'Open call', PAD, 150);

  // Big percentage, always the viewer's colour (cyan).
  displayFont(ctx, pctPx);
  ctx.fillStyle = CYAN;
  ctx.fillText(`${p.pct}%`, PAD - 6, pctBase);

  // Headline.
  displayFont(ctx, headPx);
  ctx.fillStyle = WHITE;
  headLines.forEach((line, i) => ctx.fillText(line, PAD, pctBase + headGap + i * headStep));

  // Subline.
  const subBase0 = pctBase + headGap + (headLines.length - 1) * headStep + subGap;
  textFont(ctx, 400, subPx);
  ctx.fillStyle = MUTED;
  subLines.forEach((line, i) => ctx.fillText(line, PAD, subBase0 + i * subStep));

  // Footer: rule, wordmark, and the free-coins note.
  ctx.fillStyle = RULE;
  ctx.fillRect(PAD, 1150, maxW, 2);
  displayFont(ctx, 72);
  ctx.fillStyle = WHITE;
  ctx.fillText('MATCHUP', PAD, 1250);
  const matchupW = ctx.measureText('MATCHUP ').width;
  ctx.fillStyle = PINK;
  ctx.fillText('MARKET', PAD + matchupW, 1250);
  textFont(ctx, 400, 30);
  ctx.fillStyle = MUTED;
  ctx.textAlign = 'right';
  ctx.fillText('League Mode, free coins', W - PAD, 1250);
  ctx.textAlign = 'left';
}

async function loadFonts() {
  try {
    await Promise.all([document.fonts.load('900 300px Archivo'), document.fonts.load('400 44px Archivo')]);
  } catch {
    /* fall back to the system sans */
  }
}

function toPngBlob(canvas: HTMLCanvasElement): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('toBlob failed'))), 'image/png');
  });
}

function canShareFiles(): boolean {
  try {
    if (typeof navigator === 'undefined' || typeof navigator.share !== 'function' || typeof navigator.canShare !== 'function') return false;
    return navigator.canShare({ files: [new File([new Uint8Array(8)], FILE_NAME, { type: 'image/png' })] });
  } catch {
    return false;
  }
}

export function ShareCard({ headline, pct, subline, won }: ShareCardProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const urlRef = useRef<string | null>(null);
  const blobRef = useRef<Blob | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const [status, setStatus] = useState('');
  const canShare = canShareFiles();

  useEffect(() => {
    let cancelled = false;
    const canvas = canvasRef.current;
    if (!canvas) return;
    (async () => {
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error('no 2d context');
      await loadFonts();
      if (cancelled) return;
      drawCard(ctx, { headline, pct, subline, won });
      const blob = await toPngBlob(canvas);
      if (cancelled) return;
      const url = URL.createObjectURL(blob);
      const old = urlRef.current;
      urlRef.current = url;
      blobRef.current = blob;
      setFailed(false);
      setPreview(url);
      if (old) URL.revokeObjectURL(old);
    })().catch(() => {
      if (!cancelled) setFailed(true);
    });
    return () => {
      cancelled = true;
    };
  }, [headline, pct, subline, won]);

  useEffect(() => () => {
    if (urlRef.current) URL.revokeObjectURL(urlRef.current);
  }, []);

  function download() {
    const url = urlRef.current;
    if (!url) return;
    const a = document.createElement('a');
    a.href = url;
    a.download = FILE_NAME;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setStatus('Card saved to your downloads.');
  }

  async function share() {
    const blob = blobRef.current;
    if (!blob) return;
    const file = new File([blob], FILE_NAME, { type: 'image/png' });
    try {
      if (!navigator.canShare?.({ files: [file] })) {
        setStatus("This browser can't share images. Download the card instead.");
        return;
      }
      await navigator.share({ files: [file], title: headline, text: subline });
      setStatus('');
    } catch (e) {
      if ((e as Error).name !== 'AbortError') setStatus("Couldn't open sharing. Download the card instead.");
    }
  }

  return (
    <div className="share-card">
      <canvas ref={canvasRef} width={W} height={H} hidden aria-hidden="true" />
      {preview ? (
        <img className="share-preview" src={preview} width={W} height={H} alt={`Share card: ${headline}. ${subline}`} />
      ) : failed ? (
        <p className="error small" role="alert">Couldn't draw the card. Close it and try again.</p>
      ) : (
        <div className="skeleton share-preview" aria-hidden="true" />
      )}
      <div className="share-actions">
        <button type="button" className="btn primary" onClick={download} disabled={!preview}>Download card</button>
        {canShare && (
          <button type="button" className="btn" onClick={() => void share()} disabled={!preview}>Share card</button>
        )}
      </div>
      <p className="small muted" aria-live="polite">{status}</p>
    </div>
  );
}
