/**
 * WP-6 — Append-only, double-entry ledger in integer CENTICOINS with idempotency keys.
 * Every entry's lines sum to exactly 0. A retry with the same idempotency key can never double-post.
 *
 * Account naming: 'user:<userId>', 'mm:<marketId>' (market maker / escrow for one market),
 * 'house:treasury' (funds market subsidies and starting balances), 'house:grants' (source of free coins).
 *
 * Owner: WP-6. Imports allowed: '@fmm/core'.
 */

import { hashHex } from '@fmm/core';

export interface LedgerLine { account: string; amountCc: number }

export interface JournalEntry {
  seq: number;
  idempotencyKey: string;
  /** Stable hash of (lines, memo) used to detect key reuse with a different body. */
  bodyHash: string;
  lines: LedgerLine[];
  memo: string;
  /** ISO timestamp supplied by caller (ledger never reads the clock). */
  ts: string;
}

export interface PostRequest {
  idempotencyKey: string;
  lines: LedgerLine[];
  memo: string;
  ts: string;
  /** Accounts that must not end below 0 after this entry (e.g. the buyer). */
  nonNegative?: string[];
}

export class LedgerError extends Error { constructor(public code: 'UNBALANCED' | 'NOT_INTEGER' | 'EMPTY' | 'IDEMPOTENCY_CONFLICT' | 'INSUFFICIENT_FUNDS', msg: string) { super(msg); this.name = 'LedgerError'; } }

export interface PostResult { entry: JournalEntry; replayed: boolean }

/**
 * Canonical body: lines sorted by account then amount, plus memo. ts is excluded so a retry with a new
 * timestamp still replays. Key order is fixed by construction, so the string is deterministic.
 */
function canonicalBody(lines: readonly LedgerLine[], memo: string): string {
  const sorted = lines
    .map((l) => ({ account: l.account, amountCc: l.amountCc }))
    .sort((a, b) => {
      if (a.account !== b.account) return a.account < b.account ? -1 : 1;
      return a.amountCc < b.amountCc ? -1 : a.amountCc > b.amountCc ? 1 : 0;
    });
  return JSON.stringify({ lines: sorted, memo });
}

/** Rejects empty, non-integer, or unbalanced line sets. Sum is exact (BigInt), so it cannot overflow. */
function validateLines(lines: readonly LedgerLine[]): void {
  if (!Array.isArray(lines) || lines.length === 0) throw new LedgerError('EMPTY', 'entry has no lines');
  for (const l of lines) {
    if (typeof l.account !== 'string' || l.account.length === 0) throw new Error('ledger: account must be a non-empty string');
    if (!Number.isSafeInteger(l.amountCc)) {
      throw new LedgerError('NOT_INTEGER', `amountCc must be a safe integer, got ${String(l.amountCc)} for ${l.account}`);
    }
  }
  let sum = BigInt(0);
  for (const l of lines) sum += BigInt(l.amountCc);
  if (sum !== BigInt(0)) throw new LedgerError('UNBALANCED', `lines sum to ${sum.toString()} cc, expected 0`);
}

/** Copies lines and freezes the entry so the journal cannot be mutated through a returned reference. */
function freezeEntry(e: JournalEntry): JournalEntry {
  const lines = e.lines.map((l) => Object.freeze({ account: l.account, amountCc: l.amountCc }) as LedgerLine);
  return Object.freeze({ ...e, lines: Object.freeze(lines) as LedgerLine[] }) as JournalEntry;
}

export class Ledger {
  private readonly _entries: JournalEntry[] = [];
  private readonly _balances = new Map<string, number>();
  private readonly _byKey = new Map<string, JournalEntry>();

  /**
   * Validate and append. Rules, in order:
   *  1. lines non-empty, every amountCc a safe integer (Number.isSafeInteger), lines may merge same account.
   *  2. sum === 0 else UNBALANCED.
   *  3. If idempotencyKey already used: same bodyHash -> return {entry: original, replayed: true} (no change);
   *     different body -> IDEMPOTENCY_CONFLICT.
   *  4. nonNegative accounts: projected balance >= 0 else INSUFFICIENT_FUNDS (nothing is written).
   *  5. Append with seq = previous + 1 (starting at 1).
   */
  post(req: PostRequest): PostResult {
    if (typeof req.idempotencyKey !== 'string' || req.idempotencyKey.length === 0) {
      throw new Error('ledger: idempotencyKey must be a non-empty string');
    }
    validateLines(req.lines);

    const existing = this._byKey.get(req.idempotencyKey);
    if (existing) {
      if (canonicalBody(existing.lines, existing.memo) === canonicalBody(req.lines, req.memo)) {
        return { entry: existing, replayed: true };
      }
      throw new LedgerError('IDEMPOTENCY_CONFLICT', `idempotencyKey ${req.idempotencyKey} reused with a different body`);
    }

    const projected = this.project(req.lines);
    for (const acct of req.nonNegative ?? []) {
      const bal = projected.get(acct) ?? this.balance(acct);
      if (bal < 0) throw new LedgerError('INSUFFICIENT_FUNDS', `${acct} would end at ${bal} cc`);
    }

    const entry = freezeEntry({
      seq: this._entries.length + 1,
      idempotencyKey: req.idempotencyKey,
      bodyHash: hashHex(canonicalBody(req.lines, req.memo)),
      lines: req.lines,
      memo: req.memo,
      ts: req.ts,
    });
    this.commit(entry, projected);
    return { entry, replayed: false };
  }

  /** Current balance (cc). Unknown account -> 0. */
  balance(account: string): number {
    return this._balances.get(account) ?? 0;
  }

  /** All balances, accounts with non-zero history included. */
  balances(): Record<string, number> {
    return Object.fromEntries(this._balances);
  }

  /** Sum of all balances; must always be 0. */
  trialBalance(): number {
    let sum = BigInt(0);
    for (const v of this._balances.values()) sum += BigInt(v);
    return Number(sum);
  }

  entries(): readonly JournalEntry[] {
    return this._entries.slice();
  }

  /** Lookup by idempotency key. */
  find(idempotencyKey: string): JournalEntry | undefined {
    return this._byKey.get(idempotencyKey);
  }

  /** Serialize to plain JSON (for localStorage / Postgres export). */
  toJSON(): { entries: JournalEntry[] } {
    return { entries: this._entries.slice() };
  }

  /** Rebuild by replaying entries; verifies seq continuity and balance, throws on corruption. */
  static fromJSON(data: { entries: JournalEntry[] }): Ledger {
    if (!data || !Array.isArray(data.entries)) throw new Error('fromJSON: entries array required');
    const ledger = new Ledger();
    data.entries.forEach((raw, i) => {
      const e = raw as JournalEntry;
      if (typeof e !== 'object' || e === null) throw new Error(`fromJSON: entry at index ${i} is not an object`);
      if (e.seq !== i + 1) throw new Error(`fromJSON: seq gap at index ${i}: expected ${i + 1}, got ${String(e.seq)}`);
      if (typeof e.idempotencyKey !== 'string' || e.idempotencyKey.length === 0) {
        throw new Error(`fromJSON: bad idempotencyKey at seq ${e.seq}`);
      }
      if (typeof e.memo !== 'string' || typeof e.ts !== 'string') throw new Error(`fromJSON: bad memo/ts at seq ${e.seq}`);
      validateLines(e.lines);
      if (e.bodyHash !== hashHex(canonicalBody(e.lines, e.memo))) {
        throw new Error(`fromJSON: bodyHash mismatch at seq ${e.seq} (tampered)`);
      }
      if (ledger._byKey.has(e.idempotencyKey)) throw new Error(`fromJSON: duplicate idempotencyKey at seq ${e.seq}`);
      ledger.commit(freezeEntry(e), ledger.project(e.lines));
    });
    return ledger;
  }

  /** Projected balances for the touched accounts after applying lines. Throws on overflow before anything is written. */
  private project(lines: readonly LedgerLine[]): Map<string, number> {
    const projected = new Map<string, number>();
    for (const l of lines) {
      const cur = projected.get(l.account) ?? this.balance(l.account);
      const next = cur + l.amountCc;
      if (!Number.isSafeInteger(next)) throw new Error(`ledger: balance overflow on ${l.account}`);
      projected.set(l.account, next);
    }
    return projected;
  }

  private commit(entry: JournalEntry, projected: Map<string, number>): void {
    this._entries.push(entry);
    this._byKey.set(entry.idempotencyKey, entry);
    for (const [acct, bal] of projected) this._balances.set(acct, bal);
  }
}
