/**
 * Portfolio: coins, profit, calibration, open calls, settled calls, and share cards. Owner: WP-14.
 * Positions span every league on this device; rows are grouped by league only when there is more than one.
 */
import { useState } from 'react';
import { CC_PER_COIN, PAYOUT_CC_PER_SHARE, STARTING_COINS, priceCents, type League, type Side } from '@fmm/core';
import { calibrationScore, type Forecast } from '@fmm/engine';
import type { MarketInfo, Position } from '@fmm/market';
import { balanceCc, getBook, loadDemo, marketIdFor, myStats, USER_ID, useApp } from '../state/store';
import { href } from '../lib/router';
import { cents, coins } from '../lib/format';
import { SourceBadge } from '../components/SourceBadge';
import { ShareCard } from './portfolio/ShareCard';
import './portfolio.css';

const MIN_CALLS = 10;
/** Market ids look like "sleeper:<leagueId>:w<week>:m<matchupId>". */
const MARKET_ID = /^(.+):w(\d+):m(\d+)$/;

type Result = 'won' | 'lost' | 'tie' | 'refunded';

interface Call {
  marketId: string;
  openedAt: string;
  title: string;
  teamA: string;
  teamB: string;
  leagueKey: string;
  week: number | null;
  matchupId: number | null;
  /** True when the market belongs to the league loaded right now, so the matchup page can show it. */
  linkable: boolean;
  pos: Position;
  /** The one side held, or null when both YES and NO are held. */
  side: Side | null;
  /** Average price paid for `side`, 0..1. Null when both sides are held. */
  avgP: number | null;
  costCc: number;
  /** Mark value while open; payout once settled. */
  worthCc: number;
  settled: boolean;
  result?: Result;
}

function parseMarketId(marketId: string): { leagueKey: string; week: number | null; matchupId: number | null } {
  const m = MARKET_ID.exec(marketId);
  if (!m) return { leagueKey: marketId, week: null, matchupId: null };
  return { leagueKey: m[1], week: Number(m[2]), matchupId: Number(m[3]) };
}

/** "Shain's Squad beats Dave's Dynasty" -> ["Shain's Squad", "Dave's Dynasty"]. YES = team A. */
function splitTitle(title: string): [string, string] {
  const parts = title.split(' beats ');
  if (parts.length === 2) return [parts[0].trim(), parts[1].trim()];
  return [title, 'the other team'];
}

function buildCalls(league: League | undefined): Call[] {
  const book = getBook();
  const calls: Call[] = [];
  for (const pos of book.positions(USER_ID)) {
    if (pos.yes === 0 && pos.no === 0) continue;
    const info: MarketInfo | undefined = book.get(pos.marketId);
    if (!info) continue;
    const { leagueKey, week, matchupId } = parseMarketId(pos.marketId);
    const [teamA, teamB] = splitTitle(info.title);
    const side: Side | null = pos.yes > 0 && pos.no > 0 ? null : pos.yes > 0 ? 'YES' : 'NO';
    const held = side === 'YES' ? pos.yes : side === 'NO' ? pos.no : 0;
    const avgP = side ? Math.min(1, Math.max(0, pos.costBasisCc / (held * PAYOUT_CC_PER_SHARE))) : null;
    const settled = info.status === 'settled';
    const worthCc = book.markValueCc(USER_ID, pos.marketId);
    let result: Result | undefined;
    if (settled) {
      if (info.outcome === 'TIE') result = 'tie';
      else if (info.outcome === 'VOID') result = 'refunded';
      else if (side) result = side === info.outcome ? 'won' : 'lost';
      else result = worthCc > pos.costBasisCc ? 'won' : 'lost';
    }
    calls.push({
      marketId: pos.marketId,
      openedAt: info.openedAt,
      title: info.title,
      teamA,
      teamB,
      leagueKey,
      week,
      matchupId,
      linkable: !!league && matchupId != null && marketIdFor(league, matchupId) === pos.marketId,
      pos,
      side,
      avgP,
      costCc: pos.costBasisCc,
      worthCc,
      settled,
      result,
    });
  }
  calls.sort((a, b) => b.openedAt.localeCompare(a.openedAt));
  return calls;
}

/** Calibration input: settled single-side calls. p = price paid for the side held; outcome 1 won, 0.5 tie, 0 lost. */
function forecastsOf(calls: Call[]): Forecast[] {
  const fs: Forecast[] = [];
  for (const c of calls) {
    if (!c.settled || c.avgP == null || !c.result || c.result === 'refunded') continue;
    const outcome: 0 | 0.5 | 1 = c.result === 'won' ? 1 : c.result === 'tie' ? 0.5 : 0;
    fs.push({ p: c.avgP, outcome });
  }
  return fs;
}

/** Whole-coin signed text. Under one coin reads as "Even" in the delta form. */
function signed(cc: number): { num: string; tone: 'you' | 'rival' | 'muted' } {
  const whole = Math.trunc(cc / CC_PER_COIN);
  if (whole === 0) return { num: '0', tone: 'muted' };
  const n = Math.abs(whole).toLocaleString('en-US');
  return whole > 0 ? { num: `+${n}`, tone: 'you' } : { num: `−${n}`, tone: 'rival' };
}

function leagueLabel(key: string, league: League | undefined): string {
  if (league && key === `${league.platform}:${league.leagueId}`) return league.name;
  const [platform, id] = key.split(':');
  if (platform === 'demo') return 'Sample league';
  if (platform === 'sleeper' && id) return `Sleeper league ${id}`;
  return 'Another league';
}

function groupByLeague(calls: Call[]): { key: string; calls: Call[] }[] {
  const groups = new Map<string, Call[]>();
  for (const c of calls) {
    const list = groups.get(c.leagueKey);
    if (list) list.push(c);
    else groups.set(c.leagueKey, [c]);
  }
  return [...groups.entries()].map(([key, list]) => ({ key, calls: list }));
}

const RESULT_LABEL: Record<Result, string> = { won: 'Won', lost: 'Lost', tie: 'Tie', refunded: 'Refunded' };

function holdingText(c: Call): string {
  const week = c.week != null ? `Week ${c.week}. ` : '';
  if (c.side && c.avgP != null) {
    const name = c.side === 'YES' ? c.teamA : c.teamB;
    const shares = c.side === 'YES' ? c.pos.yes : c.pos.no;
    return `${week}Backing ${name}, ${shares} ${shares === 1 ? 'share' : 'shares'} at ${cents(c.avgP)} avg`;
  }
  return `${week}Both sides: ${c.pos.yes} for ${c.teamA}, ${c.pos.no} for ${c.teamB}`;
}

function CallItem({ c, openCard, onToggle }: { c: Call; openCard: string | null; onToggle: (key: string) => void }) {
  const hasSide = !!c.side && c.avgP != null;
  const weekSuffix = c.week != null ? `, week ${c.week}` : '';

  // Settled wins get "Make a card"; open calls get "Share my call". Both need a single side with a known price.
  const cardKey = c.settled ? `won:${c.marketId}` : `open:${c.marketId}`;
  const canCard = hasSide && (!c.settled || c.result === 'won');
  let card: { headline: string; pct: number; subline: string; won: boolean } | null = null;
  if (canCard && c.side && c.avgP != null) {
    const pct = priceCents(c.avgP);
    if (c.settled) {
      const winner = c.side === 'YES' ? c.teamA : c.teamB;
      const loser = c.side === 'YES' ? c.teamB : c.teamA;
      card = { headline: 'Called it.', pct, subline: `${winner} over ${loser}${weekSuffix}`, won: true };
    } else {
      const name = c.side === 'YES' ? c.teamA : c.teamB;
      card = { headline: `Backing ${name} at ${pct}%`, pct, subline: `${c.teamA} vs ${c.teamB}${weekSuffix}`, won: false };
    }
  }
  const open = openCard === cardKey;
  const delta = signed(c.worthCc - c.costCc);

  return (
    <li className="pf-call">
      <div className="pf-call-main">
        <div className="pf-call-text">
          <p className="pf-call-title">{c.title}</p>
          <p className="small muted pf-call-meta">{holdingText(c)}</p>
        </div>
        {c.settled ? (
          <div className="pf-call-side">
            <span className={`pf-call-value ${c.result === 'won' ? 'you' : 'muted'}`}>{RESULT_LABEL[c.result ?? 'lost']}</span>
            <span className="small muted">
              {c.result === 'refunded' ? 'Refunded' : 'Payout'} {coins(c.worthCc)} coins
            </span>
          </div>
        ) : (
          <div className="pf-call-side">
            <span className="small muted">Worth now</span>
            <span className="num pf-worth">{coins(c.worthCc)}</span>
            <span className={`small ${delta.tone}`}>{delta.num === '0' ? 'Even' : `${delta.num} coins`}</span>
          </div>
        )}
      </div>
      {(c.linkable || card) && (
        <div className="pf-call-actions">
          {c.linkable && c.matchupId != null && (
            <a className="pf-link" href={href({ name: 'matchup', matchupId: c.matchupId })}>Open matchup</a>
          )}
          {card && (
            <button type="button" className="btn" aria-expanded={open} onClick={() => onToggle(cardKey)}>
              {open ? 'Hide card' : c.settled ? 'Make a card' : 'Share my call'}
            </button>
          )}
        </div>
      )}
      {card && open && <ShareCard headline={card.headline} pct={card.pct} subline={card.subline} won={card.won} />}
    </li>
  );
}

function CallList({ label, calls, league, openCard, onToggle }: {
  label: string;
  calls: Call[];
  league: League | undefined;
  openCard: string | null;
  onToggle: (key: string) => void;
}) {
  const groups = groupByLeague(calls);
  const multi = groups.length > 1;
  return (
    <section className="pf-section" aria-label={label}>
      <h2 className="h2">{label}</h2>
      {groups.map((g) => (
        <div key={g.key} className="pf-section">
          {multi && <h3 className="small muted pf-group">{leagueLabel(g.key, league)}</h3>}
          <ul className="pf-list">
            {g.calls.map((c) => (
              <CallItem key={c.marketId} c={c} openCard={openCard} onToggle={onToggle} />
            ))}
          </ul>
        </div>
      ))}
    </section>
  );
}

export function PortfolioPage() {
  const s = useApp();
  const [openCard, setOpenCard] = useState<string | null>(null);
  const league = s.league;
  const calls = buildCalls(league);
  const openCalls = calls.filter((c) => !c.settled);
  const settledCalls = calls.filter((c) => c.settled);
  const stats = myStats();
  const profit = signed(stats.profitCc);
  const forecasts = forecastsOf(calls);
  const score = calibrationScore(forecasts, MIN_CALLS);
  const toggle = (key: string) => setOpenCard((cur) => (cur === key ? null : key));
  // Skeletons only while no league is loaded yet; once a league exists, zero calls means the empty state.
  const loading = calls.length === 0 && !league && (s.status === 'idle' || s.status === 'loading');

  return (
    <div className="pf">
      <header className="pf-head">
        <h1 className="pf-title">Portfolio</h1>
        <p className="small muted">
          Calls across every league on this device. <SourceBadge />
        </p>
      </header>

      {s.status === 'error' && (
        <div className="panel pf-error" role="alert">
          <p className="error">{s.error ?? "Couldn't load the league."}</p>
          <button type="button" className="btn" onClick={() => void loadDemo()}>Try the sample league again</button>
        </div>
      )}

      <section className="pf-stats" aria-label="Your numbers">
        <div className="pf-stat pf-stat--balance">
          <span className="small muted">League Mode coins</span>
          <span className="num pf-big">{coins(balanceCc())}</span>
        </div>
        <div className="pf-stat">
          <span className="small muted">Profit vs {STARTING_COINS.toLocaleString('en-US')} starting</span>
          <span className={`num pf-mid ${profit.tone}`}>{profit.num}</span>
        </div>
        <div className="pf-stat">
          <span className="small muted">Calls made</span>
          <span className="num pf-mid">{stats.calls}</span>
        </div>
        <div className="pf-stat">
          <span className="small muted">Correct</span>
          <span className="num pf-mid">{stats.correct}</span>
        </div>
      </section>

      <section className="panel pf-cal" aria-labelledby="pf-cal-h">
        <h2 className="h2" id="pf-cal-h">Calibration</h2>
        {score == null ? (
          <p className="pf-cal-note">
            {forecasts.length} of {MIN_CALLS} calls scored. Your calibration score unlocks at {MIN_CALLS}.
          </p>
        ) : (
          <>
            <p className="pf-cal-score">
              <span className="num pf-cal-num">{score}</span>
              <span className="muted">/100</span>
            </p>
            <p className="small muted pf-cal-note">100 means your prices matched what happened.</p>
          </>
        )}
      </section>

      {loading && (
        <div className="pf-section" aria-busy="true" aria-label="Loading your calls">
          <div className="skeleton pf-skel" />
          <div className="skeleton pf-skel" />
        </div>
      )}

      {!loading && calls.length === 0 && (
        <div className="empty">
          <p className="pf-empty-text">No calls yet. Pick a side in any matchup.</p>
          <a className="btn primary" href={href({ name: 'home' })}>Go to Home</a>
        </div>
      )}

      {openCalls.length > 0 && (
        <CallList label="Open calls" calls={openCalls} league={league} openCard={openCard} onToggle={toggle} />
      )}
      {settledCalls.length > 0 && (
        <CallList label="Settled calls" calls={settledCalls} league={league} openCard={openCard} onToggle={toggle} />
      )}
    </div>
  );
}
