/**
 * WP-7 — Normalize raw Sleeper responses into @fmm/core types, and load a whole league for a week.
 *
 * Owner: WP-7. Imports allowed: '@fmm/core', './raw', './client'. (The scoring normalization lives in
 * @fmm/engine's normalizeScoring — import it from '@fmm/engine'.)
 */
import type { League, FantasyTeam, Matchup } from '@fmm/core';
import { normalizeScoring } from '@fmm/engine';
import type { SleeperLeague, SleeperRoster, SleeperLeagueUser, SleeperMatchupRow } from './raw';
import type { SleeperClient } from './client';

/**
 * Teams from rosters + users. name = user.metadata.team_name || user.display_name || `Team ${roster_id}`;
 * managerName = user.display_name || 'Unclaimed'; starters = matchup row starters for the week if provided
 * (they reflect the current lineup), else roster.starters; players = matchup row players ?? roster.players ?? [];
 * record from roster.settings. Sorted by rosterId.
 */
export function normalizeTeams(rosters: SleeperRoster[], users: SleeperLeagueUser[], matchupRows?: SleeperMatchupRow[]): FantasyTeam[] {
  const userById = new Map<string, SleeperLeagueUser>();
  for (const u of users) userById.set(u.user_id, u);
  const rowByRoster = new Map<number, SleeperMatchupRow>();
  for (const r of matchupRows ?? []) rowByRoster.set(r.roster_id, r);

  return rosters
    .map((roster): FantasyTeam => {
      const user = roster.owner_id != null ? userById.get(roster.owner_id) : undefined;
      const row = rowByRoster.get(roster.roster_id);
      const teamName = nonEmpty(user?.metadata?.team_name) ?? nonEmpty(user?.display_name) ?? `Team ${roster.roster_id}`;
      return {
        rosterId: roster.roster_id,
        ownerId: roster.owner_id ?? null,
        name: teamName,
        managerName: nonEmpty(user?.display_name) ?? 'Unclaimed',
        avatar: user?.avatar ?? null,
        starters: [...(row?.starters ?? roster.starters ?? [])],
        players: [...(row?.players ?? roster.players ?? [])],
        record: {
          wins: roster.settings?.wins ?? 0,
          losses: roster.settings?.losses ?? 0,
          ties: roster.settings?.ties ?? 0,
        },
      };
    })
    .sort((a, b) => a.rosterId - b.rosterId);
}

/**
 * Pair matchup rows by matchup_id. Rows with matchup_id null (bye) are skipped. A matchup_id with exactly two
 * rows -> one Matchup with teamA = lower roster_id. Any other count (1 or 3+) is skipped (log nothing, never throw).
 * pointsA/pointsB from row.custom_points ?? row.points. Sorted by matchupId.
 */
export function pairMatchups(rows: SleeperMatchupRow[], week: number): Matchup[] {
  const groups = new Map<number, SleeperMatchupRow[]>();
  for (const row of rows) {
    if (row.matchup_id == null) continue;
    const group = groups.get(row.matchup_id);
    if (group) group.push(row);
    else groups.set(row.matchup_id, [row]);
  }

  const matchups: Matchup[] = [];
  for (const [matchupId, group] of groups) {
    if (group.length !== 2) continue;
    const [first, second] = group[0].roster_id <= group[1].roster_id ? group : [group[1], group[0]];
    matchups.push({
      matchupId,
      week,
      teamA: first.roster_id,
      teamB: second.roster_id,
      pointsA: first.custom_points ?? first.points,
      pointsB: second.custom_points ?? second.points,
    });
  }
  return matchups.sort((a, b) => a.matchupId - b.matchupId);
}

/** Build a League. myUserId (Sleeper user_id) sets myRosterId when that user owns a roster. */
export function normalizeLeague(
  raw: { league: SleeperLeague; rosters: SleeperRoster[]; users: SleeperLeagueUser[]; matchups: SleeperMatchupRow[] },
  week: number,
  myUserId?: string | null,
): League {
  const mine = myUserId ? raw.rosters.find((r) => r.owner_id === myUserId) : undefined;
  return {
    platform: 'sleeper',
    leagueId: raw.league.league_id,
    name: raw.league.name,
    season: raw.league.season,
    week,
    scoring: normalizeScoring(raw.league.scoring_settings),
    rosterPositions: [...raw.league.roster_positions],
    teams: normalizeTeams(raw.rosters, raw.users, raw.matchups),
    matchups: pairMatchups(raw.matchups, week),
    myRosterId: mine ? mine.roster_id : null,
    isSample: false,
  };
}

/** Fetch league, rosters, users and the week's matchups in parallel and normalize. week defaults to state.display_week. */
export async function loadLeague(client: SleeperClient, leagueId: string, week?: number, myUserId?: string | null): Promise<League> {
  const resolvedWeek = week ?? (await client.getState()).display_week;
  const [league, rosters, users, matchups] = await Promise.all([
    client.getLeague(leagueId),
    client.getRosters(leagueId),
    client.getLeagueUsers(leagueId),
    client.getMatchups(leagueId, resolvedWeek),
  ]);
  return normalizeLeague({ league, rosters, users, matchups }, resolvedWeek, myUserId);
}

/** Username -> { user, leagues } for the given season (default: state.league_season). Only sport 'nfl'. */
export async function findLeagues(client: SleeperClient, username: string, season?: string): Promise<{ userId: string; displayName: string; leagues: { leagueId: string; name: string; totalRosters: number; status: string; season: string }[] }> {
  const [user, resolvedSeason] = await Promise.all([
    client.getUser(username),
    season ?? client.getState().then((s) => s.league_season),
  ]);
  const leagues = await client.getLeagues(user.user_id, resolvedSeason);
  return {
    userId: user.user_id,
    displayName: user.display_name,
    leagues: leagues
      .filter((l) => l.sport === 'nfl')
      .map((l) => ({
        leagueId: l.league_id,
        name: l.name,
        totalRosters: l.total_rosters,
        status: l.status,
        season: l.season,
      })),
  };
}

function nonEmpty(value: string | null | undefined): string | undefined {
  if (typeof value !== 'string') return undefined;
  const trimmed = value.trim();
  return trimmed === '' ? undefined : trimmed;
}
