/** Both starting lineups side by side (stacked on phones). Projected points before kickoff, live points after. Owner: WP-12. */
import { pts } from '../../lib/format';
import {
  hasStarted, isStarter, livePts, projPts, teamName, toneOf, type Slot, type View,
} from './model';

export function Lineups({ v }: { v: View }) {
  return (
    <div>
      <h2 className="h2">Lineups</h2>
      <div className="mx-lineups-grid">
        <Lineup v={v} slot="A" />
        <Lineup v={v} slot="B" />
      </div>
    </div>
  );
}

function Lineup({ v, slot }: { v: View; slot: Slot }) {
  const team = v.teams[slot];
  const tone = toneOf(v, slot);
  return (
    <section aria-label={`${teamName(team, slot)} starters`}>
      <h3 className="small mx-lineup-name" style={{ color: tone.color }}>{teamName(team, slot)}</h3>
      <ul className="mx-lineup">
        {(team?.starters ?? []).map((pid, i) => <PlayerRow key={`${slot}-${i}`} v={v} pid={pid} />)}
      </ul>
    </section>
  );
}

function PlayerRow({ v, pid }: { v: View; pid: string }) {
  if (!isStarter(pid)) {
    return (
      <li className="row mx-pl">
        <span className="muted">Empty</span>
      </li>
    );
  }
  const proj = v.ctx?.projections[pid];
  let value: string;
  if (!proj) value = 'No projection';
  else if (v.ctx && hasStarted(v.ctx, pid)) value = `${pts(livePts(v, pid))} pts`;
  else value = `Proj ${pts(projPts(v, pid))}`;
  return (
    <li className="row mx-pl">
      <span className="mx-pl-name">
        {proj?.name ?? 'Unknown player'}
        {proj?.position ? <span className="muted"> {proj.position}</span> : null}
      </span>
      <span className={`small tnum mx-pl-pts${proj ? '' : ' muted'}`}>{value}</span>
    </li>
  );
}
