/**
 * Shared League Mode client (Neon Function API). Honor system, free coins: each device keeps its own coins; league
 * mates share results and calls. Identity = playerId + random token per league, stored on this device only.
 * Owner: Commander.
 */
import type { TradeLogRow } from './store';

export const API_BASE = (import.meta.env.VITE_API_BASE as string | undefined) ?? 'https://br-patient-sea-b4l8hmoq-api.compute.c-6.us-east-2.aws.neon.tech';

export interface Identity { playerId: string; token: string; name: string }
export interface BoardPlayer { playerId: string; name: string; rosterId: number | null; profitCc: number; calls: number; correct: number; updatedAt: string }
export interface ActivityRow { name: string; week: number; matchupId: number; title: string; side: 'YES' | 'NO'; action: 'buy' | 'sell'; shares: number; avgPrice: number; at: string }

const key = (leagueKey: string) => `fmm.social.${leagueKey}`;
export function identityFor(leagueKey: string): Identity | null {
  try { const raw = localStorage.getItem(key(leagueKey)); return raw ? JSON.parse(raw) : null; } catch { return null; }
}
function remember(leagueKey: string, id: Identity) { try { localStorage.setItem(key(leagueKey), JSON.stringify(id)); } catch { /* ignore */ } }
export function forget(leagueKey: string) { try { localStorage.removeItem(key(leagueKey)); } catch { /* ignore */ } }

async function call<T>(path: string, init?: RequestInit): Promise<{ status: number; body: T }> {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 12_000);
  try {
    const r = await fetch(`${API_BASE}${path}`, { ...init, signal: ctrl.signal, credentials: 'omit' });
    const body = (await r.json().catch(() => ({}))) as T;
    return { status: r.status, body };
  } finally { clearTimeout(t); }
}

/** Join (or re-join from this device). Returns the identity or a user-facing error string. */
export async function join(leagueKey: string, name: string, rosterId: number | null): Promise<Identity | string> {
  const prev = identityFor(leagueKey);
  try {
    const { status, body } = await call<{ playerId?: string; token?: string; name?: string; error?: { message: string } }>('/join', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ league: leagueKey, name, rosterId, playerId: prev?.playerId, token: prev?.token }),
    });
    if (status === 200 && body.playerId && body.token) {
      const id = { playerId: body.playerId, token: body.token, name: body.name ?? name };
      remember(leagueKey, id);
      return id;
    }
    return body.error?.message ?? "Couldn't join right now. Try again.";
  } catch {
    return "Couldn't reach the league board. Check your connection.";
  }
}

export async function report(id: Identity, stats: { profitCc: number; calls: number; correct: number }, trades: TradeLogRow[]): Promise<'ok' | 'unauthorized'> {
  const { status } = await call('/report', {
    method: 'POST',
    headers: { 'content-type': 'application/json', authorization: `Bearer ${id.playerId}.${id.token}` },
    body: JSON.stringify({
      stats,
      trades: trades.map((t) => ({ id: t.id, week: t.week, matchupId: t.matchupId, title: t.title, side: t.side, action: t.action, shares: t.shares, amountCc: Math.abs(t.amountCc), avgPrice: t.avgPrice, at: t.at })),
    }),
  });
  if (status === 401) return 'unauthorized';
  if (status !== 200) throw new Error(`report ${status}`);
  return 'ok';
}

export async function fetchLeague(leagueKey: string): Promise<{ players: BoardPlayer[]; activity: ActivityRow[] }> {
  const { status, body } = await call<{ players?: BoardPlayer[]; activity?: ActivityRow[] }>(`/league?key=${encodeURIComponent(leagueKey)}`);
  if (status !== 200) throw new Error(`league ${status}`);
  return { players: body.players ?? [], activity: body.activity ?? [] };
}
