/** Display helpers. Owner: Commander. */
import { ccToCoins, priceCents } from '@fmm/core';

/** 0.6234 -> "62%" (clamped 1..99 so a live market never reads 0% or 100% until final). */
export function pct(p: number, final = false): string {
  if (final) return `${Math.round(p * 100)}%`;
  return `${priceCents(p)}%`;
}
/** Two complementary percentages that always sum to 100. */
export function pctPair(pA: number): [number, number] {
  const a = priceCents(pA);
  return [a, 100 - a];
}
/** 0.62 -> "62¢". */
export function cents(p: number): string { return `${priceCents(p)}¢`; }
/** 12345 cc -> "123 coins" (whole coins, rounded down for balances). */
export function coins(cc: number, opts: { signed?: boolean } = {}): string {
  const c = Math.floor(ccToCoins(Math.abs(cc)));
  const s = c.toLocaleString('en-US');
  if (opts.signed) return `${cc < 0 ? '−' : cc > 0 ? '+' : ''}${s}`;
  return `${cc < 0 ? '−' : ''}${s}`;
}
export function pts(x: number): string { return x.toFixed(1); }
/** "±14 pts" */
export function swing(x: number): string { return `±${Math.round(x)} pts`; }
/** Local clock time "1:52 PM". */
export function clock(iso: string | number | Date): string {
  const d = new Date(iso);
  return d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
}
