/**
 * WP-8 — Projection sources and the WeekContext builder.
 *
 * Phase 0 has NO licensed projection feed. Two stand-ins:
 *  1. 'sleeper-weekly': Sleeper's UNDOCUMENTED weekly projections (rows carry company "rotowire"). Experimental,
 *     personal/prototype use only — not licensed for commercial use. Gives per-stat means + opponent + game_id.
 *  2. 'heuristic': position + rank tier table, used when (1) is unavailable or a player is missing from it.
 * The UI must label which source priced a matchup.
 *
 * Owner: WP-8. Imports allowed: '@fmm/core', './raw'.
 */
import { POSITIONS, cleanStatLine } from '@fmm/core';
import type { PlayerProjection, NflGame, WeekContext, Position, StatLine, PlayerLive } from '@fmm/core';
import type { SleeperProjectionRow, SleeperScheduleRow, SleeperPlayer } from './raw';

const MODEL_VERSION = 'fmm-sim-0.1';

const POSITION_SET: ReadonlySet<string> = new Set(POSITIONS);

function isPosition(value: unknown): value is Position {
  return typeof value === 'string' && POSITION_SET.has(value);
}

/**
 * Rows -> projections keyed by player_id. Skip rows whose player.position is not one of POSITIONS, or with no
 * stats. mean = cleanStatLine(row.stats) from @fmm/core. name = `${first_name} ${last_name}` (DEF: "Cincinnati Bengals"
 * style already in first/last). team = row.team ?? row.player.team. injuryStatus = row.player.injury_status.
 * source 'sleeper-weekly'.
 */
export function projectionsFromSleeper(rows: SleeperProjectionRow[]): Record<string, PlayerProjection> {
  const out: Record<string, PlayerProjection> = {};
  for (const row of rows) {
    const player = row.player;
    if (!player || !isPosition(player.position)) continue;
    if (!row.player_id) continue;
    const mean: StatLine = cleanStatLine(row.stats ?? {});
    if (Object.keys(mean).length === 0) continue;
    // First row for a player wins; duplicates from the endpoint are not expected but must not corrupt output.
    if (out[row.player_id]) continue;
    const name = `${player.first_name ?? ''} ${player.last_name ?? ''}`.trim();
    out[row.player_id] = {
      playerId: row.player_id,
      name: name || row.player_id,
      position: player.position,
      team: row.team ?? player.team ?? '',
      opponent: row.opponent ?? null,
      gameId: row.game_id ?? null,
      injuryStatus: player.injury_status ?? null,
      mean,
      source: 'sleeper-weekly',
    };
  }
  return out;
}

/**
 * Schedule rows for one week -> NflGame[]. status map: 'complete' -> 'complete', 'in_game'|'in_progress' ->
 * 'in_progress', anything else -> 'scheduled'. kickoff from date (YYYY-MM-DD, keep as given, no time).
 * impliedTotal/spread left undefined (no betting feed in Phase 0).
 */
export function scheduleFromSleeper(rows: SleeperScheduleRow[], week: number): NflGame[] {
  const games: NflGame[] = [];
  for (const row of rows) {
    if (row.week !== week) continue;
    const status: NflGame['status'] =
      row.status === 'complete' ? 'complete' : row.status === 'in_game' || row.status === 'in_progress' ? 'in_progress' : 'scheduled';
    games.push({
      gameId: row.game_id,
      week,
      home: row.home,
      away: row.away,
      kickoff: row.date,
      status,
    });
  }
  return games;
}

/**
 * Tier table: expected full-game stat line by position and positional rank tier.
 * Tiers by positional rank (1-based, from search_rank ordering within position):
 *   QB: 1-6 elite, 7-14 starter, 15-28 backup, else deep.  RB: 1-10, 11-24, 25-40, else.
 *   WR: 1-12, 13-30, 31-50, else.  TE: 1-5, 6-12, 13-24, else.  K and DEF: 1-8, 9-20, 21-32, else.
 * Example magnitudes (elite tier) — keep tiers monotone (elite > starter > backup > deep) for every stat:
 *   QB elite: pass_att 34, pass_cmp 22, pass_yd 265, pass_td 1.9, pass_int 0.6, rush_att 6, rush_yd 30, rush_td 0.3, fum_lost 0.15
 *   RB elite: rush_att 18, rush_yd 85, rush_td 0.75, rec_tgt 4.5, rec 3.6, rec_yd 28, rec_td 0.15, fum_lost 0.08
 *   WR elite: rec_tgt 9.5, rec 6.4, rec_yd 88, rec_td 0.6, rush_yd 3
 *   TE elite: rec_tgt 7.5, rec 5.4, rec_yd 60, rec_td 0.45
 *   K  elite: fgm_20_29 0.5, fgm_30_39 0.6, fgm_40_49 0.6, fgm_50p 0.4, fgmiss 0.2, xpm 2.8, xpmiss 0.1
 *   DEF elite: sack 3.2, int 1.0, fum_rec 0.7, ff 0.8, def_td 0.15, safe 0.03  (pts_allow/yds_allow come from the game script)
 * Each lower tier: roughly 75% / 50% / 25% of elite volumes and TDs.
 */
const ELITE: Readonly<Record<Position, StatLine>> = {
  QB: { pass_att: 34, pass_cmp: 22, pass_yd: 265, pass_td: 1.9, pass_int: 0.6, rush_att: 6, rush_yd: 30, rush_td: 0.3, fum_lost: 0.15 },
  RB: { rush_att: 18, rush_yd: 85, rush_td: 0.75, rec_tgt: 4.5, rec: 3.6, rec_yd: 28, rec_td: 0.15, fum_lost: 0.08 },
  WR: { rec_tgt: 9.5, rec: 6.4, rec_yd: 88, rec_td: 0.6, rush_yd: 3 },
  TE: { rec_tgt: 7.5, rec: 5.4, rec_yd: 60, rec_td: 0.45 },
  K: { fgm_20_29: 0.5, fgm_30_39: 0.6, fgm_40_49: 0.6, fgm_50p: 0.4, fgmiss: 0.2, xpm: 2.8, xpmiss: 0.1 },
  DEF: { sack: 3.2, int: 1.0, fum_rec: 0.7, ff: 0.8, def_td: 0.15, safe: 0.03 },
};

/** Stats that describe bad outcomes or misses: held flat across tiers rather than scaled down. */
const FLAT_ACROSS_TIERS: ReadonlySet<string> = new Set(['pass_int', 'fum_lost', 'fgmiss', 'xpmiss']);

const TIER_SCALE = [1, 0.75, 0.5, 0.25] as const;

function buildTiers(elite: StatLine): StatLine[] {
  return TIER_SCALE.map((scale) => {
    const line: StatLine = {};
    for (const [key, value] of Object.entries(elite)) {
      line[key] = FLAT_ACROSS_TIERS.has(key) ? value : Math.round(value * scale * 1000) / 1000;
    }
    return line;
  });
}

export const TIER_TABLE: Readonly<Record<Position, readonly StatLine[]>> = {
  QB: buildTiers(ELITE.QB),
  RB: buildTiers(ELITE.RB),
  WR: buildTiers(ELITE.WR),
  TE: buildTiers(ELITE.TE),
  K: buildTiers(ELITE.K),
  DEF: buildTiers(ELITE.DEF),
};

/** Upper rank bounds (inclusive) of tiers 0, 1, 2 per position; anything above the last bound is tier 3. */
const TIER_BOUNDS: Readonly<Record<Position, readonly [number, number, number]>> = {
  QB: [6, 14, 28],
  RB: [10, 24, 40],
  WR: [12, 30, 50],
  TE: [5, 12, 24],
  K: [8, 20, 32],
  DEF: [8, 20, 32],
};

/** Positional tier index 0..3 for a 1-based positional rank. */
export function tierFor(position: Position, posRank: number): number {
  const [a, b, c] = TIER_BOUNDS[position];
  if (posRank <= a) return 0;
  if (posRank <= b) return 1;
  if (posRank <= c) return 2;
  return 3;
}

/**
 * Heuristic projections for the given player ids using the players map (from getPlayers). posRank = rank of
 * the player's search_rank among all players of the same position in the map (lower search_rank = better;
 * missing search_rank = deep tier). Players with no usable position -> omitted. source 'heuristic'.
 * Depth: depth_chart_order >= 3 for RB/WR/TE drops one tier.
 */
export function heuristicProjections(playerIds: string[], players: Record<string, SleeperPlayer>): Record<string, PlayerProjection> {
  // Rank search_rank within each position across the whole map (not just the requested ids).
  const ranked = new Map<string, Map<string, number>>();
  const byPosition: Record<string, { id: string; rank: number }[]> = {};
  for (const [id, p] of Object.entries(players)) {
    const pos = usablePosition(id, p);
    if (!pos || typeof p.search_rank !== 'number' || !Number.isFinite(p.search_rank)) continue;
    (byPosition[pos] ??= []).push({ id, rank: p.search_rank });
  }
  for (const [pos, list] of Object.entries(byPosition)) {
    list.sort((x, y) => x.rank - y.rank || (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
    const m = new Map<string, number>();
    list.forEach((entry, i) => m.set(entry.id, i + 1));
    ranked.set(pos, m);
  }

  const out: Record<string, PlayerProjection> = {};
  for (const id of playerIds) {
    if (out[id]) continue;
    const p = players[id];
    if (!p) continue;
    const pos = usablePosition(id, p);
    if (!pos) continue;
    const rank = ranked.get(pos)?.get(id);
    let tier = rank === undefined ? 3 : tierFor(pos, rank);
    if ((pos === 'RB' || pos === 'WR' || pos === 'TE') && typeof p.depth_chart_order === 'number' && p.depth_chart_order >= 3) {
      tier = Math.min(3, tier + 1);
    }
    const name = p.full_name || `${p.first_name ?? ''} ${p.last_name ?? ''}`.trim() || id;
    out[id] = {
      playerId: id,
      name,
      position: pos,
      team: p.team ?? '',
      opponent: null,
      gameId: null,
      injuryStatus: p.injury_status ?? null,
      mean: { ...TIER_TABLE[pos][tier] },
      source: 'heuristic',
    };
  }
  return out;
}

/** The player's position if it is one of POSITIONS, else null. DEF players are identified by position only. */
function usablePosition(_id: string, p: SleeperPlayer): Position | null {
  if (isPosition(p.position)) return p.position;
  const fromFantasy = p.fantasy_positions?.find((x) => isPosition(x));
  return isPosition(fromFantasy) ? fromFantasy : null;
}

/**
 * Assemble a WeekContext. projections = primary merged over fallback (primary wins per player).
 * modelVersion = `${MODEL_VERSION} (${sourceLabel})` where sourceLabel is 'sleeper-weekly' if any primary
 * projection was used, else 'heuristic', else 'demo'. MODEL_VERSION constant = 'fmm-sim-0.1' (duplicate the
 * string; do not import the engine). Teams on bye (in projections but not in games) keep their projections
 * — the engine treats unknown games as independent.
 */
export function buildWeekContext(input: {
  season: string; week: number; games: NflGame[];
  primary?: Record<string, PlayerProjection>; fallback?: Record<string, PlayerProjection>;
  live?: Record<string, PlayerLive>; asOf: string;
}): WeekContext {
  const projections: Record<string, PlayerProjection> = { ...(input.fallback ?? {}), ...(input.primary ?? {}) };
  const sources = new Set(Object.values(projections).map((p) => p.source));
  const sourceLabel = sources.has('sleeper-weekly') ? 'sleeper-weekly' : sources.has('heuristic') ? 'heuristic' : 'demo';
  const ctx: WeekContext = {
    season: input.season,
    week: input.week,
    games: input.games,
    projections,
    asOf: input.asOf,
    modelVersion: `${MODEL_VERSION} (${sourceLabel})`,
  };
  if (input.live) ctx.live = input.live;
  return ctx;
}
