/** WP-18 — "How good is the number": a live backtest of this season's completed weeks, run in a browser worker. */
import { useRef, useState } from 'react';
import { DEFAULT_PPR } from '@fmm/engine';
import type { BacktestResult, BacktestWeek, PlayerCalibration, ReliabilityBin } from '@fmm/engine';
import { loadSeasonWeeks } from './model/loadWeeks';
import type { BacktestMessage, BacktestRequest } from './model/backtest.worker';
import {
  count, headlineBin, orderedPlayers, percentBetterThanCoin, pct, rangeVerdict, signed, VERDICT_HELP, MIN_BIN_N,
  type Verdict,
} from './model/summary';
import './model/model.css';

const SIMS_PER_PLAYER = 2000;
const SIMS_PER_MATCHUP = 2000;
const LEAGUES_PER_WEEK = 8;
const SEED = 20261026;

type Phase =
  | { kind: 'idle' }
  | { kind: 'loading'; text: string }
  | { kind: 'simulating'; p: number }
  | { kind: 'done'; result: BacktestResult }
  | { kind: 'error'; message: string };

/** Survives leaving and returning to the page within one session; a fresh run replaces it. */
let lastResult: BacktestResult | null = null;

export function ModelPage() {
  const [phase, setPhase] = useState<Phase>(() => (lastResult ? { kind: 'done', result: lastResult } : { kind: 'idle' }));
  const busy = useRef(false);

  const run = async () => {
    if (busy.current) return;
    busy.current = true;
    setPhase({ kind: 'loading', text: 'Checking the season calendar…' });
    try {
      const weeks = await loadSeasonWeeks((text) => setPhase({ kind: 'loading', text }));
      setPhase({ kind: 'simulating', p: 0 });
      const result = await runInWorker(weeks, (p) => setPhase({ kind: 'simulating', p }));
      lastResult = result;
      setPhase({ kind: 'done', result });
    } catch (err) {
      setPhase({ kind: 'error', message: err instanceof Error ? err.message : String(err) });
    } finally {
      busy.current = false;
    }
  };

  const running = phase.kind === 'loading' || phase.kind === 'simulating';

  return (
    <div className="model">
      <header className="model-head">
        <h1 className="model-title">How good is the number</h1>
        <p className="model-intro">
          We replay this season&rsquo;s completed weeks with the same model that prices matchups, then check each
          percentage against what actually happened. If we said 70%, the team should win about 70% of the time.
        </p>
        <div className="model-meta">
          <span className="badge">Sleeper weekly projections (unofficial feed)</span>
          <span className="small muted">Runs in your browser. Takes 20 to 60 seconds.</span>
        </div>
      </header>

      {phase.kind === 'idle' && (
        <div className="model-action">
          <button type="button" className="btn primary" onClick={run}>Run the check</button>
        </div>
      )}

      {running && (
        <section className="model-progress-block" aria-live="polite">
          {phase.kind === 'loading' ? (
            <>
              <div className="model-progress skeleton" role="progressbar" aria-label="Loading weeks" />
              <p className="small">{phase.text}</p>
            </>
          ) : (
            <>
              <div className="model-progress" role="progressbar" aria-label="Simulation progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(phase.p * 100)}>
                <div style={{ width: `${Math.round(phase.p * 100)}%` }} />
              </div>
              <p className="small">Simulating… {Math.round(phase.p * 100)}%</p>
            </>
          )}
        </section>
      )}

      {phase.kind === 'error' && (
        <section className="empty" role="alert">
          <p className="error">{phase.message}</p>
          <button type="button" className="btn" onClick={run}>Try again</button>
        </section>
      )}

      {phase.kind === 'done' && (
        <>
          <div className="model-action">
            <span className="small muted">Checked weeks {phase.result.weeks.join(', ')}.</span>
            <button type="button" className="btn" onClick={run}>Run the check again</button>
          </div>
          <Results result={phase.result} />
        </>
      )}

      <Footnote result={phase.kind === 'done' ? phase.result : null} />
    </div>
  );
}

/** Runs the backtest in a module worker. Progress is throttled to 1% steps. */
function runInWorker(weeks: BacktestWeek[], onProgress: (p: number) => void): Promise<BacktestResult> {
  return new Promise<BacktestResult>((resolve, reject) => {
    let w: Worker;
    try {
      w = new Worker(new URL('./model/backtest.worker.ts', import.meta.url), { type: 'module' });
    } catch {
      reject(new Error('This browser cannot run the check in the background. Try a current version of Chrome, Edge, Firefox or Safari.'));
      return;
    }
    let lastReported = -1;
    w.onmessage = (e: MessageEvent<BacktestMessage>) => {
      const m = e.data;
      if (m.type === 'progress') {
        if (m.p - lastReported >= 0.01 || m.p >= 1) {
          lastReported = m.p;
          onProgress(m.p);
        }
        return;
      }
      w.terminate();
      if (m.type === 'done') resolve(m.result);
      else reject(new Error(`The check could not finish: ${m.message}`));
    };
    w.onerror = () => {
      w.terminate();
      reject(new Error('The check stopped unexpectedly. Try again.'));
    };
    const req: BacktestRequest = {
      weeks,
      scoring: DEFAULT_PPR,
      simsPerPlayer: SIMS_PER_PLAYER,
      simsPerMatchup: SIMS_PER_MATCHUP,
      leaguesPerWeek: LEAGUES_PER_WEEK,
      seed: SEED,
    };
    w.postMessage(req);
  });
}

function Results({ result }: { result: BacktestResult }) {
  const band = headlineBin(result.bins);
  const favorites = result.forecasts.filter((f) => f.pA !== 0.5).length;
  const better = percentBetterThanCoin(result.brier, result.baselineBrier);
  const brierWords =
    !Number.isFinite(better) ? '–' : better > 0 ? `${better}% better than a coin flip` : better < 0 ? `${-better}% worse than a coin flip` : 'as good as a coin flip';

  return (
    <div className="model-results">
      <section className="model-hero" aria-labelledby="model-headline">
        {band ? (
          <>
            <h2 id="model-headline" className="model-headline">
              When we gave a team {Math.round(band.lo * 100)}&ndash;{Math.round(band.hi * 100)}%, it won {pct(band.observed)} of the time.
            </h2>
            <p className="muted small">Based on {count(band.n)} matchups in that band.</p>
          </>
        ) : (
          <h2 id="model-headline" className="model-headline">
            Not enough matchups in any one band yet.
          </h2>
        )}
      </section>

      <section className="model-block" aria-labelledby="model-scores">
        <h2 id="model-scores" className="h2">Scores</h2>
        <div className="rows">
          <div className="row model-stat">
            <div className="model-stat-main">
              <span className="model-stat-label">Brier score</span>
              <span className="num model-stat-value">{result.brier.toFixed(3)}</span>
            </div>
            <p className="small muted">
              Our score {result.brier.toFixed(3)} vs {result.baselineBrier.toFixed(3)} for always saying 50%: {brierWords}.
              Lower is better.
            </p>
          </div>
          <div className="row model-stat">
            <div className="model-stat-main">
              <span className="model-stat-label">Favorites won</span>
              <span className="num model-stat-value">{pct(result.favoriteWinRate)}</span>
            </div>
            <p className="small muted">Out of {count(favorites)} matchups where we had a favorite.</p>
          </div>
        </div>
      </section>

      <section className="model-block" aria-labelledby="model-chart-title">
        <h2 id="model-chart-title" className="h2">Forecast against result</h2>
        <p className="small muted">
          Each dot is a band of forecasts. A dot on the dashed line means the band was right. The whiskers show the
          95% range for what happened.
        </p>
        <ReliabilityChart bins={result.bins} />
        <details className="model-details">
          <summary className="small">Band by band</summary>
          <table className="model-table">
            <caption className="visually-hidden">Matchups and win rate in each forecast band</caption>
            <thead>
              <tr><th scope="col">We said</th><th scope="col">Matchups</th><th scope="col">Won</th></tr>
            </thead>
            <tbody>
              {result.bins.filter((b) => b.n > 0).map((b) => (
                <tr key={b.lo}>
                  <th scope="row">{Math.round(b.lo * 100)}&ndash;{Math.round(b.hi * 100)}%</th>
                  <td>{count(b.n)}</td>
                  <td>{pct(b.observed)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </details>
      </section>

      <section className="model-block" aria-labelledby="model-positions">
        <h2 id="model-positions" className="h2">Player ranges by position</h2>
        <p className="small muted">
          Each player has a simulated range for the week. The target is that 80% of real results land inside it.
        </p>
        <PositionTable players={orderedPlayers(result)} />
        <p className="small muted model-legend">
          Bias is the average miss in points; positive means projections ran low. Avg miss is the typical distance
          between the projected average and the real result.
        </p>
        <PitGrid players={orderedPlayers(result)} />
      </section>
    </div>
  );
}

const CHART = { W: 320, H: 320, L: 46, R: 12, T: 12, B: 46 };

function ReliabilityChart({ bins }: { bins: ReliabilityBin[] }) {
  const { W, H, L, R, T, B } = CHART;
  const pw = W - L - R;
  const ph = H - T - B;
  const sx = (v: number) => L + v * pw;
  const sy = (v: number) => T + (1 - v) * ph;
  const shown = bins.filter((b) => b.n > 0 && Number.isFinite(b.observed));
  const maxN = Math.max(1, ...shown.map((b) => b.n));
  const ticks = [0, 0.25, 0.5, 0.75, 1];

  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="model-chart" role="img"
      aria-label={`Reliability chart with ${shown.length} forecast bands. Dots near the diagonal mean the forecasts were accurate.`}>
      {ticks.map((t) => (
        <g key={t}>
          <line x1={sx(t)} x2={sx(t)} y1={sy(0)} y2={sy(1)} className="model-grid" />
          <line x1={sx(0)} x2={sx(1)} y1={sy(t)} y2={sy(t)} className="model-grid" />
          <text x={sx(t)} y={sy(0) + 16} textAnchor="middle" className="model-tick">{Math.round(t * 100)}%</text>
          <text x={L - 8} y={sy(t) + 4} textAnchor="end" className="model-tick">{Math.round(t * 100)}%</text>
        </g>
      ))}
      <line x1={sx(0)} y1={sy(0)} x2={sx(1)} y2={sy(1)} className="model-diagonal" />
      {shown.map((b) => {
        const x = Number.isFinite(b.meanP) ? b.meanP : (b.lo + b.hi) / 2;
        const r = 5 + 12 * Math.sqrt(b.n / maxN);
        const solid = b.n >= MIN_BIN_N;
        const [c0, c1] = b.ci;
        const label = `${Math.round(b.lo * 100)}–${Math.round(b.hi * 100)}% band: ${count(b.n)} matchups, won ${pct(b.observed)}`;
        return (
          <g key={b.lo} opacity={solid ? 1 : 0.4}>
            {Number.isFinite(c0) && Number.isFinite(c1) && (
              <line x1={sx(x)} x2={sx(x)} y1={sy(c0)} y2={sy(c1)} className="model-whisker" />
            )}
            <circle cx={sx(x)} cy={sy(b.observed)} r={r} className="model-dot">
              <title>{label}</title>
            </circle>
          </g>
        );
      })}
      <text x={L + pw / 2} y={H - 8} textAnchor="middle" className="model-axis">Our forecast</text>
      <text transform={`translate(14 ${T + ph / 2}) rotate(-90)`} textAnchor="middle" className="model-axis">How often it happened</text>
    </svg>
  );
}

function PositionTable({ players }: { players: PlayerCalibration[] }) {
  return (
    <div className="model-table-wrap">
      <table className="model-table">
        <thead>
          <tr>
            <th scope="col">Position</th>
            <th scope="col">Players</th>
            <th scope="col">Bias</th>
            <th scope="col">In 80% range</th>
            <th scope="col">Avg miss</th>
            <th scope="col">Verdict</th>
          </tr>
        </thead>
        <tbody>
          {players.map((p) => {
            const v: Verdict = rangeVerdict(p);
            return (
              <tr key={p.position}>
                <th scope="row">{p.position === 'ALL' ? 'All' : p.position}</th>
                <td>{count(p.n)}</td>
                <td>{p.n ? `${signed(p.bias)} pts` : '–'}</td>
                <td>{p.n ? pct(p.coverage80) : '–'}</td>
                <td>{p.n ? `${p.mae.toFixed(1)} pts` : '–'}</td>
                <td title={VERDICT_HELP[v]} className={v === 'About right' || v === 'No data' ? '' : 'model-verdict-off'}>{v}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/** One small histogram per position. Flat = right width; piled at the ends = too narrow; a middle hump = too wide. */
function PitGrid({ players }: { players: PlayerCalibration[] }) {
  const withData = players.filter((p) => p.n > 0 && p.pit.length > 0);
  if (withData.length === 0) return null;
  return (
    <div className="model-pit">
      <h3 className="small model-pit-title">Where real results fell in each range</h3>
      <p className="small muted">
        Split each range into ten slices. A flat row of bars means results were spread evenly across the slices, which is
        what a well-sized range looks like. Bars piled at the ends mean the range is too narrow.
      </p>
      <div className="model-pit-grid">
        {withData.map((p) => (
          <figure key={p.position} className="model-pit-item">
            <figcaption className="small">{p.position === 'ALL' ? 'All' : p.position}</figcaption>
            <PitBars pit={p.pit} />
          </figure>
        ))}
      </div>
    </div>
  );
}

function PitBars({ pit }: { pit: number[] }) {
  const total = pit.reduce((a, b) => a + b, 0);
  const W = 160;
  const H = 56;
  if (total <= 0) return <p className="small muted">No data</p>;
  const shares = pit.map((c) => c / total);
  const yMax = Math.max(0.2, ...shares);
  const bw = W / shares.length;
  const yExp = H - (0.1 / yMax) * H;
  return (
    <svg viewBox={`0 0 ${W} ${H + 2}`} className="model-pit-svg" role="img"
      aria-label={`Histogram of where results fell: ${shares.map((s) => Math.round(s * 100)).join(', ')} percent per tenth`}>
      {shares.map((s, i) => {
        const h = (s / yMax) * H;
        return <rect key={i} x={i * bw + 1.5} y={H - h} width={bw - 3} height={Math.max(0, h)} className="model-pit-bar" />;
      })}
      <line x1={0} x2={W} y1={yExp} y2={yExp} className="model-pit-expected" />
    </svg>
  );
}

function Footnote({ result }: { result: BacktestResult | null }) {
  return (
    <footer className="model-footnote small muted">
      <p>
        <strong className="model-footnote-head">What we tested.</strong>{' '}
        {result
          ? `Completed weeks ${result.weeks.join(', ')} of this season. For each week, Sleeper's weekly projections were compared with Sleeper's actual stats. We simulated ${count(result.simsPerPlayer)} outcomes per player and ${count(result.simsPerMatchup)} per matchup, across ${LEAGUES_PER_WEEK} synthetic 12-team leagues per week.`
          : 'Each run uses this season’s completed weeks. Sleeper’s weekly projections are compared with Sleeper’s actual stats. Each matchup is simulated thousands of times.'}
      </p>
      <p>
        The projections come from Sleeper’s undocumented weekly feed. It is unofficial and not licensed for commercial
        use. The synthetic leagues are drafted from real players, so the matchups are realistic but are not real leagues.
        Games carry no betting lines in this test, so each team is treated on its own with default totals.
      </p>
    </footer>
  );
}
