/**
 * WP-9 (part) — Calibration metrics. "When we said 70%, teams won 69% of the time." Trust in the number is the brand.
 *
 * Owner: WP-9. Imports allowed: '@fmm/core'.
 */

export interface Forecast {
  /** Forecast probability of the event (e.g. team A wins), 0..1. */
  p: number;
  /** Outcome: 1 happened, 0 did not, 0.5 tie. */
  outcome: 0 | 0.5 | 1;
}

const Z_95 = 1.96;
const LOG_EPS = 1e-6;

function clampForLog(p: number): number {
  return Math.min(1 - LOG_EPS, Math.max(LOG_EPS, p));
}

/** 95% Wilson score interval. `successes` may be fractional (a tie counts as half a success). */
function wilsonInterval(successes: number, n: number, z = Z_95): [number, number] {
  if (n === 0) return [NaN, NaN];
  const phat = successes / n;
  const z2 = z * z;
  const denom = 1 + z2 / n;
  const centre = (phat + z2 / (2 * n)) / denom;
  const half = (z * Math.sqrt((phat * (1 - phat)) / n + z2 / (4 * n * n))) / denom;
  return [Math.max(0, centre - half), Math.min(1, centre + half)];
}

/** Bin index for p in [0,1) half-open bins; p === 1 goes to the last bin. Corrects float drift at edges. */
function binIndex(p: number, bins: number): number {
  let i = Math.min(bins - 1, Math.floor(p * bins));
  while (i > 0 && p < i / bins) i--;
  while (i < bins - 1 && p >= (i + 1) / bins) i++;
  return i;
}

/** Mean squared error of p vs outcome. Empty input -> NaN. */
export function brierScore(fs: Forecast[]): number {
  if (fs.length === 0) return NaN;
  let sum = 0;
  for (const f of fs) {
    const d = f.p - f.outcome;
    sum += d * d;
  }
  return sum / fs.length;
}

/** Mean negative log-likelihood (natural log). Clamp p to [1e-6, 1-1e-6]. Ties: 0.5*(ln p + ln(1-p)). Empty -> NaN. */
export function logLoss(fs: Forecast[]): number {
  if (fs.length === 0) return NaN;
  let sum = 0;
  for (const { p, outcome } of fs) {
    const q = clampForLog(p);
    // Negative log-likelihood of a (possibly half) outcome: -(o ln q + (1 - o) ln(1 - q)).
    sum -= outcome * Math.log(q) + (1 - outcome) * Math.log(1 - q);
  }
  return sum / fs.length;
}

export interface ReliabilityBin {
  lo: number; hi: number;
  /** Number of forecasts in [lo, hi) (last bin includes 1). */
  n: number;
  meanP: number;
  /** Observed frequency (mean outcome). NaN when n === 0. */
  observed: number;
  /** 95% Wilson interval of observed frequency; [NaN, NaN] when n === 0. */
  ci: [number, number];
}

/** Equal-width bins over [0,1]. bins default 10. */
export function reliabilityBins(fs: Forecast[], bins = 10): ReliabilityBin[] {
  if (!Number.isInteger(bins) || bins < 1) {
    throw new RangeError(`reliabilityBins: bins must be a positive integer, got ${bins}`);
  }
  const counts = new Array<number>(bins).fill(0);
  const sumP = new Array<number>(bins).fill(0);
  const sumO = new Array<number>(bins).fill(0);
  for (const f of fs) {
    if (!(f.p >= 0 && f.p <= 1)) throw new RangeError(`reliabilityBins: p must be in [0,1], got ${f.p}`);
    const i = binIndex(f.p, bins);
    counts[i]++;
    sumP[i] += f.p;
    sumO[i] += f.outcome;
  }
  const out: ReliabilityBin[] = [];
  for (let i = 0; i < bins; i++) {
    const lo = i / bins;
    const hi = (i + 1) / bins;
    const n = counts[i];
    if (n === 0) {
      out.push({ lo, hi, n: 0, meanP: NaN, observed: NaN, ci: [NaN, NaN] });
      continue;
    }
    out.push({
      lo,
      hi,
      n,
      meanP: sumP[i] / n,
      observed: sumO[i] / n,
      ci: wilsonInterval(sumO[i], n),
    });
  }
  return out;
}

/** Brier skill score vs a baseline forecast set of equal length: 1 - brier(fs)/brier(baseline). */
export function brierSkill(fs: Forecast[], baseline: Forecast[]): number {
  if (fs.length !== baseline.length) {
    throw new RangeError(`brierSkill: length mismatch (${fs.length} vs ${baseline.length})`);
  }
  const baseBrier = brierScore(baseline);
  // A perfect baseline leaves no room to measure skill, and empty input has no score.
  if (baseBrier === 0 || Number.isNaN(baseBrier)) return NaN;
  return 1 - brierScore(fs) / baseBrier;
}

/**
 * A user's "calibration score" for the Portfolio: null until at least `minCalls` (default 10) settled calls,
 * otherwise round(100 * (1 - brier / 0.25)) clamped to [0, 100] (0.25 = always saying 50%).
 */
export function calibrationScore(fs: Forecast[], minCalls = 10): number | null {
  if (fs.length < minCalls) return null;
  const brier = brierScore(fs);
  if (!Number.isFinite(brier)) return null;
  const score = Math.round(100 * (1 - brier / 0.25));
  return Math.min(100, Math.max(0, score));
}
