/** Tiny hash router. Routes: #/ (home), #/connect, #/m/<matchupId>, #/league, #/featured, #/portfolio. Owner: Commander. */
import { useSyncExternalStore } from 'react';

export type Route =
  | { name: 'home' }
  | { name: 'connect' }
  | { name: 'matchup'; matchupId: number }
  | { name: 'league' }
  | { name: 'featured' }
  | { name: 'portfolio' }
  | { name: 'model' };

export function parseHash(hash: string): Route {
  const h = hash.replace(/^#/, '') || '/';
  const parts = h.split('/').filter(Boolean);
  if (parts[0] === 'connect') return { name: 'connect' };
  if (parts[0] === 'm' && parts[1] && /^\d+$/.test(parts[1])) return { name: 'matchup', matchupId: Number(parts[1]) };
  if (parts[0] === 'league') return { name: 'league' };
  if (parts[0] === 'featured') return { name: 'featured' };
  if (parts[0] === 'portfolio') return { name: 'portfolio' };
  if (parts[0] === 'model') return { name: 'model' };
  return { name: 'home' };
}

export function href(r: Route): string {
  switch (r.name) {
    case 'home': return '#/';
    case 'connect': return '#/connect';
    case 'matchup': return `#/m/${r.matchupId}`;
    default: return `#/${r.name}`;
  }
}

export function navigate(r: Route): void { window.location.hash = href(r); }

function subscribe(cb: () => void) { window.addEventListener('hashchange', cb); return () => window.removeEventListener('hashchange', cb); }
export function useRoute(): Route {
  const hash = useSyncExternalStore(subscribe, () => window.location.hash, () => '');
  return parseHash(hash);
}
