/**
 * Connect a Sleeper league: find the account by username, pick a league, go home. Read-only: we never ask for a
 * password. Owner: WP-11 (wave 2 builder).
 */
import { useState, type FormEvent } from 'react';
import {
  useApp, getState, connectSleeper, openSleeperLeague, useSampleLeague, type LeagueSummary,
} from '../state/store';
import { navigate } from '../lib/router';
import './connect.css';

function statusText(status: string): string {
  const s = status.replace(/_/g, ' ').trim();
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : '';
}

export function ConnectPage() {
  const s = useApp();
  const [username, setUsername] = useState(s.sleeper?.username ?? '');
  const [opening, setOpening] = useState<string | null>(null);
  const [openError, setOpenError] = useState<string | null>(null);
  const [usingSample, setUsingSample] = useState(false);

  const busy = s.connectStatus === 'loading';
  const leagues = s.sleeper?.leagues ?? [];
  const showResults = !!s.sleeper && s.connectStatus !== 'error';

  function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (busy) return;
    setOpenError(null);
    void connectSleeper(username);
  }

  async function onOpen(l: LeagueSummary) {
    if (opening) return;
    setOpening(l.leagueId);
    setOpenError(null);
    await openSleeperLeague(l.leagueId);
    setOpening(null);
    const after = getState();
    if (after.status === 'error') {
      setOpenError(after.error ?? "Couldn't open that league. Try another one.");
      return;
    }
    navigate({ name: 'home' });
  }

  async function onSample() {
    setUsingSample(true);
    await useSampleLeague();
    setUsingSample(false);
    navigate({ name: 'home' });
  }

  return (
    <div className="connect-page">
      <header className="connect-head">
        <h1 className="connect-title">Connect your Sleeper league</h1>
        <p className="muted">Find your league by your Sleeper username. Your coins stay on this device.</p>
      </header>

      <form className="connect-form" onSubmit={onSubmit} noValidate>
        <label className="connect-label" htmlFor="sleeper-username">Sleeper username</label>
        <div className="connect-row">
          <input
            id="sleeper-username"
            className="field connect-input"
            type="text"
            inputMode="text"
            autoComplete="username"
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck={false}
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            aria-invalid={s.connectError ? true : undefined}
            aria-describedby={s.connectError ? 'connect-error' : 'connect-help'}
          />
          <button className="btn primary connect-submit" type="submit" disabled={busy}>
            {busy ? 'Looking…' : 'Find my leagues'}
          </button>
        </div>
        <p id="connect-help" className="small muted">Type your Sleeper username. Read-only, no password.</p>
        {s.connectError && <p id="connect-error" className="error connect-error" role="alert">{s.connectError}</p>}
      </form>

      {showResults && (
        <section className="connect-results" aria-labelledby="leagues-h" aria-live="polite">
          <div className="section-head">
            <h2 id="leagues-h" className="h2">Leagues for {s.sleeper!.displayName}</h2>
            <span className="small muted tnum">{leagues.length} {leagues.length === 1 ? 'league' : 'leagues'}</span>
          </div>
          {leagues.length === 0 ? (
            <p className="muted">No leagues found for this account this season.</p>
          ) : (
            <div className="rows">
              {leagues.map((l) => {
                const loading = opening === l.leagueId;
                return (
                  <button
                    key={l.leagueId}
                    className="row league-row"
                    type="button"
                    disabled={!!opening}
                    aria-busy={loading || undefined}
                    onClick={() => void onOpen(l)}
                  >
                    <span className="league-main">
                      <span className="league-name">{l.name}</span>
                      <span className="small muted tnum">{l.totalRosters} teams</span>
                    </span>
                    <span className="small muted league-status">{loading ? 'Opening…' : statusText(l.status)}</span>
                  </button>
                );
              })}
            </div>
          )}
          {openError && <p className="error" role="alert">{openError}</p>}
        </section>
      )}

      <section className="connect-notes" aria-labelledby="notes-h">
        <h2 id="notes-h" className="visually-hidden">About connecting</h2>
        <ul className="connect-list">
          <li>We only read your league (rosters, lineups, scoring). We never ask for a password.</li>
          <li>Yahoo and ESPN are coming next.</li>
          <li>Projections are an unofficial feed while we're in beta.</li>
        </ul>
      </section>

      <div className="connect-sample">
        <button className="btn" type="button" disabled={usingSample || !!opening} onClick={() => void onSample()}>
          {usingSample ? 'Loading the sample…' : 'Use the sample league instead'}
        </button>
      </div>
    </div>
  );
}
