/**
 * WP-15 — ESPN public scoreboard adapter: real NFL schedule, kickoff times, DraftKings game lines (spread, total,
 * moneyline), live score + clock, and bye weeks. No key. CORS allowed (verified 2026-10-26).
 * URL: https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard?week=<w>&seasontype=2&dates=<season>
 * Lines disappear once a game starts, so callers should cache the last pregame line per game (see mergeLines).
 * Shape: fixtures/espn-scoreboard.sample.json. Owner: WP-15. Imports allowed: '@fmm/core', './client' (FetchLike).
 */
import type { NflGame } from '@fmm/core';
import type { FetchLike } from './client';

export const ESPN_SCOREBOARD = 'https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard';

/** ESPN team abbreviation -> Sleeper abbreviation. Only Washington differs ("WSH" -> "WAS"); identity otherwise. */
export function espnToSleeperTeam(abbr: string): string {
  return abbr === 'WSH' ? 'WAS' : abbr;
}

/** American odds string ("-185", "+154", "EVEN") -> implied probability (with vig). null if unparseable. */
export function americanToProb(odds: string | number | null | undefined): number | null {
  let value: number;
  if (typeof odds === 'number') {
    if (!Number.isFinite(odds)) return null;
    value = odds;
  } else if (typeof odds === 'string') {
    const text = odds.trim().toUpperCase();
    if (text === 'EVEN' || text === 'EV') return 0.5;
    if (!/^[+-]?\d+$/.test(text)) return null;
    value = Number(text);
  } else {
    return null;
  }
  // American odds are never between -99 and +99 (and 0 is meaningless).
  if (value > -100 && value < 100) return null;
  return value > 0 ? 100 / (value + 100) : -value / (-value + 100);
}

/**
 * Share of a game left from ESPN status. state 'pre' -> 1; 'post' or completed -> 0; 'in':
 *  regulation (period 1-4): ((4 - period) * 900 + clockSeconds) / 3600; overtime (period >= 5): 0.02 (small);
 *  halftime (name STATUS_HALFTIME) -> 0.5. Clamp to [0, 1]. displayClock is "M:SS".
 */
export function espnFractionRemaining(status: { period?: number; displayClock?: string; type?: { state?: string; name?: string; completed?: boolean } }): number {
  const type = status?.type;
  if (type?.completed === true || type?.state === 'post') return 0;
  if (type?.name === 'STATUS_HALFTIME') return 0.5;
  if (type?.state !== 'in') return 1;

  const period = status.period;
  if (typeof period !== 'number' || !Number.isFinite(period) || period < 1) return 1;
  if (period >= 5) return clamp01(0.02);

  const clock = Math.min(900, Math.max(0, parseClockSeconds(status.displayClock)));
  return clamp01(((4 - Math.min(period, 4)) * 900 + clock) / 3600);
}

export interface EspnWeek {
  games: NflGame[];
  /** Sleeper-style abbreviations of teams on bye. */
  byes: string[];
  /** gameKey -> no-vig home win probability from moneylines when both present (for display/calibration). */
  homeWinProb: Record<string, number>;
}

/**
 * Parse a scoreboard JSON into games. For each event:
 *  gameId = `espn:${event.id}`; week = json.week.number (or the `week` arg); home/away via espnToSleeperTeam;
 *  kickoff = event.date; status: pre -> 'scheduled', in -> 'in_progress', post -> 'complete';
 *  homeScore/awayScore numbers (only when state !== 'pre'); fractionRemaining = espnFractionRemaining(status);
 *  impliedTotal = odds[0].overUnder; spread = -odds[0].spread (ESPN spread is home-view, negative = home favored;
 *  ours is expected home minus away). Missing odds -> fields undefined.
 *  homeWinProb[gameId] = pHome/(pHome+pAway) from moneyline.home.close.odds / away.close.odds when both parse.
 * byes from json.week.teamsOnBye[].abbreviation mapped to Sleeper style.
 */
export function parseEspnScoreboard(json: unknown, week: number): EspnWeek {
  const out: EspnWeek = { games: [], byes: [], homeWinProb: {} };
  const root = asRecord(json);
  if (!root) return out;

  const weekInfo = asRecord(root.week);
  const weekNumber = finiteNumber(weekInfo?.number) ?? week;

  for (const team of asArray(weekInfo?.teamsOnBye)) {
    const abbr = asString(asRecord(team)?.abbreviation);
    if (abbr) out.byes.push(espnToSleeperTeam(abbr));
  }

  for (const rawEvent of asArray(root.events)) {
    const event = asRecord(rawEvent);
    const eventId = asString(event?.id);
    if (!event || !eventId) continue;

    const competition = asRecord(asArray(event.competitions)[0]);
    if (!competition) continue;
    const competitors = asArray(competition.competitors).map(asRecord);
    const homeEntry = competitors.find((c) => c?.homeAway === 'home');
    const awayEntry = competitors.find((c) => c?.homeAway === 'away');
    const home = asString(asRecord(homeEntry?.team)?.abbreviation);
    const away = asString(asRecord(awayEntry?.team)?.abbreviation);
    if (!home || !away) continue;

    const gameId = `espn:${eventId}`;
    const statusInfo = asRecord(event.status) ?? {};
    const typeInfo = asRecord(statusInfo.type);
    const state = asString(typeInfo?.state);
    const status: NflGame['status'] =
      state === 'post' || typeInfo?.completed === true ? 'complete' : state === 'in' ? 'in_progress' : 'scheduled';

    const game: NflGame = {
      gameId,
      week: weekNumber,
      home: espnToSleeperTeam(home),
      away: espnToSleeperTeam(away),
      status,
      fractionRemaining: espnFractionRemaining({
        period: finiteNumber(statusInfo.period),
        displayClock: asString(statusInfo.displayClock),
        type: { state, name: asString(typeInfo?.name), completed: typeInfo?.completed === true },
      }),
    };

    const kickoff = asString(event.date);
    if (kickoff) game.kickoff = kickoff;

    if (status !== 'scheduled') {
      const homeScore = finiteNumber(homeEntry?.score);
      const awayScore = finiteNumber(awayEntry?.score);
      if (homeScore !== undefined) game.homeScore = homeScore;
      if (awayScore !== undefined) game.awayScore = awayScore;
    }

    const odds = asRecord(asArray(competition.odds)[0]);
    const overUnder = finiteNumber(odds?.overUnder);
    const spread = finiteNumber(odds?.spread);
    if (overUnder !== undefined) game.impliedTotal = overUnder;
    if (spread !== undefined) game.spread = 0 - spread;

    const moneyline = asRecord(odds?.moneyline);
    const pHome = americanToProb(oddsValue(asRecord(asRecord(moneyline?.home)?.close)?.odds));
    const pAway = americanToProb(oddsValue(asRecord(asRecord(moneyline?.away)?.close)?.odds));
    if (pHome !== null && pAway !== null) out.homeWinProb[gameId] = pHome / (pHome + pAway);

    out.games.push(game);
  }

  return out;
}

/** Fetch + parse. Errors -> throws Error with a short message. */
export async function fetchEspnWeek(season: string, week: number, fetchImpl?: FetchLike): Promise<EspnWeek> {
  if (!/^\d{4}$/.test(season)) throw new Error(`ESPN season must be a 4-digit year, got "${season}"`);
  if (!Number.isInteger(week) || week < 1 || week > 22) throw new Error(`ESPN week out of range: ${week}`);

  const fetchFn: FetchLike = fetchImpl ?? ((url) => globalThis.fetch(url));
  const url = `${ESPN_SCOREBOARD}?week=${week}&seasontype=2&dates=${encodeURIComponent(season)}`;

  let res: Awaited<ReturnType<FetchLike>>;
  try {
    res = await fetchFn(url);
  } catch {
    throw new Error('Network error calling ESPN scoreboard');
  }
  if (!res.ok) throw new Error(`ESPN scoreboard responded ${res.status}`);

  let body: unknown;
  try {
    body = await res.json();
  } catch {
    throw new Error('ESPN scoreboard returned invalid JSON');
  }
  return parseEspnScoreboard(body, week);
}

/**
 * Keep pregame lines after kickoff: for each game in `current` missing impliedTotal/spread, copy them from the game
 * with the same home+away in `cached`. Returns new array (pure).
 */
export function mergeLines(current: NflGame[], cached: NflGame[]): NflGame[] {
  return current.map((game) => {
    const needTotal = game.impliedTotal === undefined;
    const needSpread = game.spread === undefined;
    if (!needTotal && !needSpread) return { ...game };

    const match = cached.find((c) => c.home === game.home && c.away === game.away);
    if (!match) return { ...game };

    const merged: NflGame = { ...game };
    if (needTotal && match.impliedTotal !== undefined) merged.impliedTotal = match.impliedTotal;
    if (needSpread && match.spread !== undefined) merged.spread = match.spread;
    return merged;
  });
}

// ---- internals ----------------------------------------------------------------------------------------------

function clamp01(x: number): number {
  return Math.min(1, Math.max(0, x));
}

/** "M:SS" -> seconds. Also accepts "SS.t" (ESPN shows tenths under a minute). Unparseable -> 0. */
function parseClockSeconds(clock: string | undefined): number {
  if (typeof clock !== 'string') return 0;
  const text = clock.trim();
  const mmss = /^(\d{1,2}):([0-5]\d)$/.exec(text);
  if (mmss) return Number(mmss[1]) * 60 + Number(mmss[2]);
  if (/^\d+(\.\d+)?$/.test(text)) return Number(text);
  return 0;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return typeof value === 'object' && value !== null && !Array.isArray(value) ? (value as Record<string, unknown>) : null;
}

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function asString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
}

/** Number, or a numeric string such as ESPN's score "21" or spread "-3.5". */
function finiteNumber(value: unknown): number | undefined {
  if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
  if (typeof value === 'string' && /^[+-]?\d+(\.\d+)?$/.test(value.trim())) return Number(value.trim());
  return undefined;
}

function oddsValue(value: unknown): string | number | undefined {
  if (typeof value === 'number' || typeof value === 'string') return value;
  return undefined;
}
