/**
 * Loads this season's completed weeks for the backtest: Sleeper's undocumented weekly projections (what we would
 * have said) and Sleeper's actual stat lines (what happened). Browser only. Owner: Haiku squad #8 (WP-18).
 */
import { SleeperClient, SleeperError, projectionsFromSleeper } from '@fmm/sleeper';
import { cleanStatLine } from '@fmm/core';
import type { StatLine } from '@fmm/core';
import type { BacktestWeek } from '@fmm/engine';

const STATS_URL = (season: string, week: number) =>
  `https://api.sleeper.app/stats/nfl/${season}/${week}?season_type=regular&position[]=QB&position[]=RB&position[]=WR&position[]=TE&position[]=K&position[]=DEF`;

const MAX_WEEKS = 18;
const CONCURRENCY = 3;

let client: SleeperClient | null = null;
function sleeper(): SleeperClient {
  return (client ??= new SleeperClient());
}

/** The last week whose games are finished. Mid-season that is state.week - 1 (state.week is the week in play). */
function lastCompletedWeek(state: { week: number; season_type: string }): number {
  if (state.season_type === 'post') return MAX_WEEKS;
  if (state.season_type !== 'regular') return 0;
  return Math.max(0, Math.min(MAX_WEEKS, state.week - 1));
}

interface StatRow { player_id: string; stats?: Record<string, unknown> | null }

async function fetchActual(season: string, week: number): Promise<Record<string, StatLine>> {
  const res = await fetch(STATS_URL(season, week), { credentials: 'omit' });
  if (!res.ok) throw new Error(`Sleeper stats for week ${week} responded ${res.status}.`);
  const body: unknown = await res.json();
  const rows: StatRow[] = Array.isArray(body) ? (body as StatRow[]) : [];
  const actual: Record<string, StatLine> = {};
  for (const row of rows) {
    if (!row || !row.player_id) continue;
    const s = row.stats ?? {};
    // Only players who actually took the field. Snap-only or roster-only rows mean "did not play".
    const played = (typeof s.gms_active === 'number' && s.gms_active > 0) || (typeof s.gp === 'number' && s.gp > 0);
    if (!played) continue;
    actual[row.player_id] = cleanStatLine(s);
  }
  return actual;
}

async function fetchWeek(season: string, week: number): Promise<BacktestWeek | null> {
  let rows;
  try {
    rows = await sleeper().getProjections(season, week);
  } catch (err) {
    // Sleeper answers null for a week it has no projections for: that week is simply skipped.
    if (err instanceof SleeperError && err.code === 'NOT_FOUND') return null;
    throw err;
  }
  const projections = projectionsFromSleeper(rows);
  const actual = await fetchActual(season, week);
  if (Object.keys(projections).length === 0 || Object.keys(actual).length === 0) return null;
  // No historical lines in the feed: the engine treats each team independently with default totals.
  return { week, games: [], projections, actual };
}

let cache: { key: string; weeks: BacktestWeek[] } | null = null;

/**
 * All completed regular-season weeks of the current season, in order. Weeks with no projections or no results
 * are skipped. Fetches up to 3 weeks at a time. Cached in memory per season and last completed week.
 * onStatus receives a sentence for the page to show while loading.
 */
export async function loadSeasonWeeks(onStatus: (text: string) => void): Promise<BacktestWeek[]> {
  try {
    onStatus('Checking the season calendar…');
    const state = await sleeper().getState();
    const season = String(state.season);
    const last = lastCompletedWeek(state);
    if (last < 1) throw new Error('No games have finished this season yet. The check needs at least one completed week.');

    const key = `${season}:${last}`;
    if (cache && cache.key === key) return cache.weeks;

    const weekNumbers = Array.from({ length: last }, (_, i) => i + 1);
    const results: (BacktestWeek | null)[] = new Array(weekNumbers.length).fill(null);
    let next = 0;
    let finished = 0;
    const report = () => onStatus(`Loading week ${Math.min(finished + 1, last)} of ${last}…`);
    report();

    const lane = async () => {
      while (next < weekNumbers.length) {
        const i = next++;
        results[i] = await fetchWeek(season, weekNumbers[i]);
        finished++;
        report();
      }
    };
    await Promise.all(Array.from({ length: Math.min(CONCURRENCY, weekNumbers.length) }, lane));

    const weeks = results.filter((w): w is BacktestWeek => w !== null);
    if (weeks.length === 0) throw new Error('Sleeper has no projections and results for the completed weeks yet.');
    cache = { key, weeks };
    return weeks;
  } catch (err) {
    throw friendly(err);
  }
}

/** Turns network-level failures into a sentence the page can show with a retry button. */
function friendly(err: unknown): Error {
  if (err instanceof SleeperError && err.code === 'NETWORK') return new Error('Could not reach Sleeper. Check your connection, then try again.');
  if (err instanceof TypeError) return new Error('Could not reach Sleeper. Check your connection, then try again.');
  if (err instanceof SleeperError && err.code === 'HTTP') return new Error(`Sleeper is not answering right now (status ${err.status ?? 'unknown'}). Try again in a minute.`);
  return err instanceof Error ? err : new Error(String(err));
}
