/**
 * League board: every matchup at a glance, the call-it leaderboard, and a copy-paste odds post for the group chat.
 * Owner: WP-13 (Haiku squad #3). Exports small helpers that FeaturedPage reuses.
 */
import { useRef, useState } from 'react';
import type { FantasyTeam, League, Matchup, MatchupPrice, WeekContext } from '@fmm/core';
import { scoreStatLine } from '@fmm/engine';
import { useApp, joinLeague, positionFor, loadDemo, type AppState, type LeaderRow } from '../state/store';
import { href } from '../lib/router';
import { coins, pctPair } from '../lib/format';
import { TugBar } from '../components/TugBar';
import { SourceBadge, LiveBadge } from '../components/SourceBadge';
import './league.css';

type Sort = 'league' | 'closest';

/** The viewer's roster id: what they claimed, else the league's own guess. null = not playing. */
export function viewerRoster(s: Pick<AppState, 'me' | 'league'>): number | null {
  if (s.me !== undefined) return s.me.rosterId;
  return s.league?.myRosterId ?? null;
}

export function teamOf(league: League | undefined, rosterId: number): FantasyTeam | undefined {
  return league?.teams?.find((t) => t.rosterId === rosterId);
}

function nameOf(league: League | undefined, rosterId: number): string {
  return teamOf(league, rosterId)?.name ?? `Team ${rosterId}`;
}

/** Live points from the stat lines so far. null when there are no live stats. */
export function teamPointsNow(league: League, ctx: WeekContext | undefined, team: FantasyTeam | undefined): number | null {
  const live = ctx?.live;
  if (!ctx || !live || !team) return null;
  let sum = 0;
  for (const pid of team.starters) {
    if (!pid || pid === '0') continue;
    sum += scoreStatLine(live[pid]?.actual ?? {}, league.scoring, ctx.projections[pid]?.position ?? 'UNK');
  }
  return Math.round(sum * 10) / 10;
}

/** True once any starter's game has begun (fractionRemaining below 1). */
export function teamStarted(ctx: WeekContext | undefined, team: FantasyTeam | undefined): boolean {
  const live = ctx?.live;
  if (!live || !team) return false;
  return team.starters.some((pid) => !!pid && pid !== '0' && (live[pid]?.fractionRemaining ?? 1) < 1);
}

function sidePoints(league: League, ctx: WeekContext | undefined, team: FantasyTeam | undefined, official: number | undefined, projected: number | undefined): string {
  if (teamStarted(ctx, team)) {
    const pts = official ?? teamPointsNow(league, ctx, team);
    if (pts != null) return `${pts.toFixed(1)} pts`;
  }
  if (projected != null) return `Projected ${projected.toFixed(1)}`;
  return 'Projection pending';
}

function chatText(league: League, prices: MatchupPrice[] | undefined): string {
  const origin = typeof window !== 'undefined' ? window.location.href.split('#')[0] : '';
  const lines = [`${league.name}, week ${league.week} odds`];
  if (league.isSample) lines.push('Sample league, sample projections');
  for (const m of league.matchups ?? []) {
    const p = prices?.find((x) => x.matchupId === m.matchupId);
    if (!p) continue;
    const [a, b] = pctPair(p.pWinA);
    lines.push(`${nameOf(league, m.teamA)} ${a}% vs ${nameOf(league, m.teamB)} ${b}%`);
  }
  lines.push(`Call it: ${origin}#/league`);
  return lines.join('\n');
}

export function LeaguePage() {
  const s = useApp();
  const [sort, setSort] = useState<Sort>('league');
  const [copied, setCopied] = useState('');
  const textRef = useRef<HTMLTextAreaElement>(null);
  const { league, ctx, prices } = s;

  if (!league) {
    if (s.status === 'error') {
      return (
        <div className="empty">
          <h1 className="lb-title">League board</h1>
          <p className="error" role="alert">{s.error ?? "Couldn't load a league."}</p>
          <button className="btn primary" onClick={() => void loadDemo()}>Try the sample league again</button>
        </div>
      );
    }
    if (s.status === 'loading' || s.status === 'idle') {
      return (
        <div className="lb-page" aria-busy="true">
          <div className="skeleton" style={{ height: 36, width: 320 }} />
          <div className="rows">{[0, 1, 2, 3].map((i) => <div key={i} className="skeleton lb-skel" />)}</div>
        </div>
      );
    }
    return (
      <div className="empty">
        <h1 className="lb-title">League board</h1>
        <p className="muted">No league loaded yet. Connect a Sleeper league to see every matchup here.</p>
        <a className="btn primary" href={href({ name: 'connect' })}>Connect a league</a>
      </div>
    );
  }

  const myRoster = viewerRoster(s);
  const liveNow = !!ctx?.games.some((g) => g.status === 'in_progress');
  const priceOf = (m: Matchup) => prices?.find((p) => p.matchupId === m.matchupId);

  const matchups = league.matchups ?? [];
  const ordered = [...matchups];
  if (sort === 'closest') {
    ordered.sort((x, y) => {
      const px = priceOf(x), py = priceOf(y);
      if (!px && !py) return 0;
      if (!px) return 1;
      if (!py) return -1;
      return Math.abs(px.pWinA - 0.5) - Math.abs(py.pWinA - 0.5);
    });
  }

  const board = [...s.leaderboard].sort((x, y) => y.profitCc - x.profitCc);
  const hasPrices = !!prices && prices.length > 0;
  const text = chatText(league, prices);

  async function copyText() {
    try {
      await navigator.clipboard.writeText(text);
      setCopied('Copied');
    } catch {
      const el = textRef.current;
      if (el) {
        el.focus();
        el.select();
        let ok = false;
        try { ok = document.execCommand('copy'); } catch { ok = false; }
        setCopied(ok ? 'Copied' : 'Text selected. Press Ctrl+C or Cmd+C to copy it.');
      } else {
        setCopied("Couldn't copy. Select the text above and copy it.");
      }
    }
  }

  return (
    <div className="lb-page">
      <header className="lb-head">
        <div className="lb-head-text">
          <h1 className="lb-title">{league.name}, week {league.week}</h1>
          <p className="small muted">Every matchup in your league, priced live.</p>
        </div>
        <div className="lb-head-badges">
          {liveNow && <LiveBadge text="Live" />}
          <SourceBadge />
        </div>
      </header>

      {s.status === 'error' && (
        <p className="error small" role="alert">
          {s.error ?? "Couldn't refresh this league."} <button className="textlink" onClick={() => void loadDemo()}>Try the sample league again</button>
        </p>
      )}

      <section className="lb-section" aria-labelledby="lb-matchups">
        <div className="lb-section-head">
          <h2 id="lb-matchups" className="h2">Matchups</h2>
          <div className="lb-seg" role="group" aria-label="Sort matchups">
            <button type="button" aria-pressed={sort === 'league'} onClick={() => setSort('league')}>League order</button>
            <button type="button" aria-pressed={sort === 'closest'} onClick={() => setSort('closest')}>Closest first</button>
          </div>
        </div>
        {matchups.length === 0 && <p className="muted">No matchups this week.</p>}
        <div className="lb-rows">
          {ordered.map((m) => (
            <MatchupRow key={m.matchupId} league={league} ctx={ctx} m={m} price={priceOf(m)} myRoster={myRoster} />
          ))}
        </div>
      </section>

      <WhoAreYou key={league.leagueId} league={league} />

      <section className="lb-section" aria-labelledby="lb-board">
        <h2 id="lb-board" className="h2">Call-it leaderboard</h2>
        {board.length === 0 ? (
          <p className="muted small">No calls yet. Back a side on a matchup and it shows up here.</p>
        ) : (
          <table className="lb-table">
            <thead>
              <tr>
                <th scope="col">Rank</th>
                <th scope="col">Manager</th>
                <th scope="col" className="lb-num">Calls</th>
                <th scope="col" className="lb-num">Right</th>
                <th scope="col" className="lb-num">Profit</th>
              </tr>
            </thead>
            <tbody>
              {board.map((r, i) => <LeaderLine key={r.userId} row={r} rank={i + 1} />)}
            </tbody>
          </table>
        )}
        {s.socialMode === 'local' && (
          <p className="small muted">Join the board above to see your league-mates' calls next to yours.</p>
        )}
        {s.socialError && <p className="small error">{s.socialError}</p>}
      </section>

      <section className="lb-section" aria-labelledby="lb-feed">
        <h2 id="lb-feed" className="h2">Latest calls</h2>
        {s.activity.length === 0 ? (
          <p className="small muted">No calls from the league yet. Make the first one.</p>
        ) : (
          <div className="rows">
            {s.activity.slice(0, 15).map((a, i) => (
              <div className="row small" key={`${a.name}-${a.at}-${i}`}>
                <span style={{ flex: 1 }}>
                  <strong>{a.name}</strong> {a.action === 'sell' ? 'sold' : 'backed'} {a.side === 'YES' ? a.title.split(' beats ')[0] : (a.title.split(' beats ')[1] ?? 'the other side')}
                  {' '}<span className="muted">{a.shares} at {Math.round(a.avgPrice * 100)}¢</span>
                </span>
                <span className="muted tnum">{new Date(a.at).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })}</span>
              </div>
            ))}
          </div>
        )}
      </section>

      <section className="lb-section" aria-labelledby="lb-post">
        <h2 id="lb-post" className="h2">Post to your league chat</h2>
        <p className="small muted">Paste the odds and a link into your group chat. Everything here is free coins.</p>
        <textarea
          ref={textRef}
          className="lb-post"
          readOnly
          rows={Math.min(12, text.split('\n').length + 1)}
          value={text}
          aria-label="Text to paste into your league chat"
        />
        <div className="lb-post-actions">
          <button type="button" className="btn primary" onClick={() => void copyText()} disabled={!hasPrices}>
            Copy for group chat
          </button>
          <span className="small" aria-live="polite">{copied}</span>
        </div>
      </section>
    </div>
  );
}

function MatchupRow({ league, ctx, m, price, myRoster }: {
  league: League; ctx: WeekContext | undefined; m: Matchup; price: MatchupPrice | undefined; myRoster: number | null;
}) {
  const teamA = teamOf(league, m.teamA);
  const teamB = teamOf(league, m.teamB);
  const mine = myRoster != null && (myRoster === m.teamA || myRoster === m.teamB);
  const viewerIsB = mine && myRoster === m.teamB;
  const colorA = mine ? (viewerIsB ? 'rival' : 'you') : '';
  const colorB = mine ? (viewerIsB ? 'you' : 'rival') : '';
  const [pa, pb] = price ? pctPair(price.pWinA) : [null, null];
  const pos = positionFor(m.matchupId);
  const holds: string[] = [];
  if (pos?.yes) holds.push(`${pos.yes.toLocaleString('en-US')} shares of ${teamA?.name ?? `Team ${m.teamA}`} to win`);
  if (pos?.no) holds.push(`${pos.no.toLocaleString('en-US')} shares of ${teamB?.name ?? `Team ${m.teamB}`} to win`);
  const aPts = sidePoints(league, ctx, teamA, m.pointsA, price?.meanA);
  const bPts = sidePoints(league, ctx, teamB, m.pointsB, price?.meanB);

  return (
    <a className={`lb-row${mine ? ' mine' : ''}`} href={href({ name: 'matchup', matchupId: m.matchupId })}>
      <div className="lb-side lb-side-a">
        <span className={`lb-team ${colorA}`}>{teamA?.name ?? `Team ${m.teamA}`}</span>
        <span className="small muted">{teamA?.managerName ?? ''}</span>
        <span className="small muted tnum">{aPts}</span>
      </div>
      <div className="lb-side lb-side-b">
        <span className={`lb-team ${colorB}`}>{teamB?.name ?? `Team ${m.teamB}`}</span>
        <span className="small muted">{teamB?.managerName ?? ''}</span>
        <span className="small muted tnum">{bPts}</span>
      </div>
      <span className={`num lb-pct lb-pct-a ${colorA}`}>{pa == null ? '—' : `${pa}%`}</span>
      <span className={`num lb-pct lb-pct-b ${colorB}`}>{pb == null ? '—' : `${pb}%`}</span>
      <div className="lb-tug">
        {price
          ? <TugBar pA={price.pWinA} height={10} neutral={!mine} flip={viewerIsB} />
          : <div className="skeleton" style={{ height: 10 }} />}
      </div>
      {holds.length > 0 && <p className="small lb-hold">You hold {holds.join(' and ')}.</p>}
    </a>
  );
}

function LeaderLine({ row, rank }: { row: LeaderRow; rank: number }) {
  const cls = row.isMe ? 'you' : '';
  return (
    <tr className={row.isMe ? 'lb-me' : undefined}>
      <td className="tnum">{rank}</td>
      <td className={cls}>{row.name}{row.isMe && row.name !== 'You' ? ' (you)' : ''}</td>
      <td className="lb-num tnum">{row.calls}</td>
      <td className="lb-num tnum">{row.correct}</td>
      <td className="lb-num tnum">{coins(row.profitCc, { signed: true })}</td>
    </tr>
  );
}

function WhoAreYou({ league }: { league: League }) {
  const s = useApp();
  const [editing, setEditing] = useState(false);
  const [pick, setPick] = useState<string>(league.myRosterId != null ? String(league.myRosterId) : '');
  const defaultName = s.me?.name && s.me.name !== 'You' ? s.me.name : (s.sleeper?.displayName ?? '');
  const [name, setName] = useState<string>(defaultName);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const me = s.me;
  const team = me?.rosterId != null ? teamOf(league, me.rosterId) : undefined;
  const joined = s.socialMode === 'shared';

  if (me !== undefined && joined && !editing) {
    return (
      <section className="lb-block" aria-label="Who you are">
        <p className="small">
          On the board as <strong className="lb-who">{me.name}</strong>
          {team ? `, ${team.name}` : ''}.{' '}
          <button type="button" className="textlink" onClick={() => setEditing(true)}>Change</button>
        </p>
      </section>
    );
  }

  const chosen = pick === '' ? undefined : teamOf(league, Number(pick));

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true); setErr(null);
    const res = await joinLeague(name, chosen?.rosterId ?? null);
    setBusy(false);
    if (res) setErr(res); else setEditing(false);
  }

  return (
    <section className="lb-block" aria-labelledby="lb-who">
      <h2 id="lb-who" className="h2">Join the league board</h2>
      <p className="small muted">
        {league.isSample
          ? 'Everyone trying the sample league shares this board. Pick a name to show up on it.'
          : 'Your league-mates see your name, your calls and your profit. Coins stay free; it runs on the honor system.'}
      </p>
      <form className="lb-who-form" onSubmit={submit}>
        <label htmlFor="lb-who-name" className="small muted">Display name</label>
        <input id="lb-who-name" className="field" value={name} maxLength={40} onChange={(e) => setName(e.target.value)} placeholder="e.g. Dave" autoComplete="nickname" />
        <label htmlFor="lb-who-select" className="small muted">Your team (optional)</label>
        <select id="lb-who-select" className="field lb-select" value={pick} onChange={(e) => setPick(e.target.value)}>
          <option value="">Just watching</option>
          {(league.teams ?? []).map((t) => (
            <option key={t.rosterId} value={String(t.rosterId)}>I'm {t.name}</option>
          ))}
        </select>
        {err && <p className="small error" role="alert">{err}</p>}
        <div className="lb-who-actions">
          <button type="submit" className="btn primary" disabled={busy || !name.trim()}>{busy ? 'Joining…' : 'Join the board'}</button>
          {editing && <button type="button" className="textlink" onClick={() => setEditing(false)}>Cancel</button>}
        </div>
      </form>
    </section>
  );
}
