/**
 * WP-7 — Sleeper read-only client. Works in the browser (Sleeper allows cross-origin GETs; verified from
 * https://example.com on 2026-10-26) and in Node 18+ (global fetch). Never sends credentials.
 *
 * Owner: WP-7. Imports allowed: '@fmm/core', './raw'.
 */
import type {
  SleeperUser, SleeperLeague, SleeperRoster, SleeperLeagueUser, SleeperMatchupRow, SleeperState,
  SleeperPlayer, SleeperProjectionRow, SleeperScheduleRow,
} from './raw';

export interface FetchLikeResponse { ok: boolean; status: number; json(): Promise<unknown> }
export type FetchLike = (url: string) => Promise<FetchLikeResponse>;

export const SLEEPER_BASE = 'https://api.sleeper.app';

/** Live endpoints (matchups, state) are re-fetched once their cached copy is this old. */
const LIVE_TTL_MS = 30_000;
/** Sleeper allows < 1000 calls/minute; we keep well under that and far under any burst limit. */
const MAX_IN_FLIGHT = 10;

const PROJECTION_POSITIONS = ['QB', 'RB', 'WR', 'TE', 'K', 'DEF'] as const;

export class SleeperError extends Error {
  constructor(public code: 'NOT_FOUND' | 'HTTP' | 'NETWORK' | 'BAD_INPUT', msg: string, public status?: number) { super(msg); this.name = 'SleeperError'; }
}

/** Default transport: the platform fetch, called as a plain function, with cookies never sent. */
const defaultFetch: FetchLike = (url) => globalThis.fetch(url, { credentials: 'omit' });

interface CacheEntry { promise: Promise<unknown>; at: number; live: boolean }

/**
 * All methods GET `${base}${path}` and parse JSON.
 *  - Non-2xx -> SleeperError('HTTP', ..., status). fetch rejection -> SleeperError('NETWORK').
 *  - A 200 with body `null` (Sleeper's answer for an unknown user/league) -> SleeperError('NOT_FOUND').
 *  - Usernames are trimmed and lowercased and URL-encoded; empty -> SleeperError('BAD_INPUT').
 *  - Simple in-memory cache per URL for the client's lifetime, except getMatchups/getStats/getState (live data),
 *    which are cached for 30 s. getPlayers is ~5 MB: cache it and call at most once per client.
 *  - Throttle: never more than 10 requests in flight (queue the rest). Sleeper allows < 1000 calls/minute.
 */
export class SleeperClient {
  private readonly fetchImpl: FetchLike;
  private readonly base: string;
  private readonly now: () => number;
  private readonly cache = new Map<string, CacheEntry>();
  private inFlight = 0;
  private readonly waiting: Array<() => void> = [];

  constructor(fetchImpl?: FetchLike, base: string = SLEEPER_BASE, now: () => number = () => Date.now()) {
    this.fetchImpl = fetchImpl ?? defaultFetch;
    this.base = base;
    this.now = now;
  }

  async getUser(usernameOrId: string): Promise<SleeperUser> {
    return this.call(`/v1/user/${this.username(usernameOrId)}`);
  }

  /** /v1/user/<user_id>/leagues/nfl/<season> */
  async getLeagues(userId: string, season: string): Promise<SleeperLeague[]> {
    return this.call(`/v1/user/${this.id(userId, 'userId')}/leagues/nfl/${this.id(season, 'season')}`);
  }

  async getLeague(leagueId: string): Promise<SleeperLeague> {
    return this.call(`/v1/league/${this.id(leagueId, 'leagueId')}`);
  }

  async getRosters(leagueId: string): Promise<SleeperRoster[]> {
    return this.call(`/v1/league/${this.id(leagueId, 'leagueId')}/rosters`);
  }

  async getLeagueUsers(leagueId: string): Promise<SleeperLeagueUser[]> {
    return this.call(`/v1/league/${this.id(leagueId, 'leagueId')}/users`);
  }

  async getMatchups(leagueId: string, week: number): Promise<SleeperMatchupRow[]> {
    return this.call(`/v1/league/${this.id(leagueId, 'leagueId')}/matchups/${this.id(String(week), 'week')}`, true);
  }

  async getState(): Promise<SleeperState> {
    return this.call('/v1/state/nfl', true);
  }

  async getPlayers(): Promise<Record<string, SleeperPlayer>> {
    return this.call('/v1/players/nfl');
  }

  /** UNDOCUMENTED: /projections/nfl/<season>/<week>?season_type=regular&position[]=QB&position[]=RB&position[]=WR&position[]=TE&position[]=K&position[]=DEF */
  async getProjections(season: string, week: number): Promise<SleeperProjectionRow[]> {
    const positions = PROJECTION_POSITIONS.map((p) => `position[]=${p}`).join('&');
    return this.call(`/projections/nfl/${this.id(season, 'season')}/${this.id(String(week), 'week')}?season_type=regular&${positions}`);
  }

  /** UNDOCUMENTED: /schedule/nfl/regular/<season> */
  async getSchedule(season: string): Promise<SleeperScheduleRow[]> {
    return this.call(`/schedule/nfl/regular/${this.id(season, 'season')}`);
  }

  // ---- internals -------------------------------------------------------------------------------------------

  private username(raw: string): string {
    return encodeURIComponent(this.trimmed(raw, 'username').toLowerCase());
  }

  private id(raw: string, what: string): string {
    return encodeURIComponent(this.trimmed(raw, what));
  }

  private trimmed(raw: string, what: string): string {
    const v = typeof raw === 'string' ? raw.trim() : '';
    if (v === '') throw new SleeperError('BAD_INPUT', `Sleeper ${what} is empty`);
    return v;
  }

  /**
   * Cached GET. Concurrent identical calls share one promise; failures are not cached. Live entries older than
   * LIVE_TTL_MS are refetched. Every request, including the cache-miss path, goes through the throttle.
   */
  private call<T>(path: string, live = false): Promise<T> {
    const url = `${this.base}${path}`;
    const t = this.now();
    const hit = this.cache.get(url);
    if (hit && (!hit.live || t - hit.at < LIVE_TTL_MS)) return hit.promise as Promise<T>;

    const promise = this.throttled(() => this.fetchJson<T>(url));
    const entry: CacheEntry = { promise, at: t, live };
    this.cache.set(url, entry);
    promise.catch(() => {
      if (this.cache.get(url) === entry) this.cache.delete(url);
    });
    return promise;
  }

  private async fetchJson<T>(url: string): Promise<T> {
    let res: FetchLikeResponse;
    try {
      res = await this.fetchImpl(url);
    } catch (err) {
      throw new SleeperError('NETWORK', `Network error calling Sleeper: ${url} (${errorText(err)})`);
    }
    if (!res.ok) throw new SleeperError('HTTP', `Sleeper responded ${res.status} for ${url}`, res.status);

    let body: unknown;
    try {
      body = await res.json();
    } catch (err) {
      throw new SleeperError('HTTP', `Sleeper returned invalid JSON for ${url} (${errorText(err)})`, res.status);
    }
    if (body === null || body === undefined) throw new SleeperError('NOT_FOUND', `Sleeper has no data for ${url}`);
    return body as T;
  }

  /** Semaphore with direct slot hand-off: a finishing request passes its slot to the next waiter. */
  private async throttled<T>(task: () => Promise<T>): Promise<T> {
    await this.acquire();
    try {
      return await task();
    } finally {
      this.release();
    }
  }

  private acquire(): Promise<void> {
    if (this.inFlight < MAX_IN_FLIGHT) {
      this.inFlight++;
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => this.waiting.push(resolve));
  }

  private release(): void {
    const next = this.waiting.shift();
    if (next) next();
    else this.inFlight--;
  }
}

function errorText(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}
