/**
 * App state for League Mode. Owner: Commander. Pages READ via useApp() and call the exported actions.
 *
 * - One league is loaded at a time: the built-in demo league (default, offline) or a Sleeper league.
 * - Prices come from the engine in a worker. The probability on screen IS the number the house prices from.
 * - Coins: an in-browser double-entry ledger (integer centicoins) + MarketBook, persisted to localStorage.
 *   League Mode coins live on this device until accounts exist.
 * - House market per matchup: LMSR opened at the model price. When the model moves, the house re-centres the
 *   market on the new model price (user flow skew is kept), so a stale price can never be farmed.
 */
import { useSyncExternalStore } from 'react';
import type { League, WeekContext, MatchupPrice, Side, StatLine } from '@fmm/core';
import { STARTING_COINS, CC_PER_COIN } from '@fmm/core';
import { Ledger, MarketBook, type Fill, type Position, type MarketInfo } from '@fmm/market';
import { scoreStatLine } from '@fmm/engine';
import {
  DEMO_LEAGUE, demoWeekContext, demoLiveAt, SleeperClient, findLeagues, loadLeague,
  projectionsFromSleeper, scheduleFromSleeper, heuristicProjections, buildWeekContext,
  fetchEspnWeek, mergeLines, fetchLive, withLive,
} from '@fmm/sleeper';
import * as social from './social';
import { priceInBackground } from './pricer';

export const USER_ID = 'me';
export const SIMS = 10000;
export const LIVE_SIMS = 4000;
export const HOUSE_LOSS_BUDGET_COINS = 1000;
const STORAGE_KEY = 'fmm.v1';

export interface ProbPoint { /** x: demo t (0..1) or epoch ms */ x: number; pA: number; label?: string }
export interface LeagueSummary { leagueId: string; name: string; totalRosters: number; status: string; season: string }

export interface AppState {
  status: 'idle' | 'loading' | 'ready' | 'error';
  error?: string;
  league?: League;
  ctx?: WeekContext;
  prices?: MatchupPrice[];
  pricing: boolean;
  /** Source label shown next to every price. */
  source?: 'demo' | 'sleeper-weekly' | 'heuristic';
  /** Demo replay position: null = pregame, 0..1 = Sunday progress. */
  demoT: number | null;
  demoPlaying: boolean;
  /** Probability history per matchupId (team A's chance). */
  history: Record<number, ProbPoint[]>;
  sleeper?: { username: string; userId: string; displayName: string; leagues: LeagueSummary[] };
  connectStatus: 'idle' | 'loading' | 'error';
  connectError?: string;
  /** Bumps whenever coins/positions change, so components re-read the book. */
  bookVersion: number;
  /** Final points per matchup once settled. */
  finals: Record<number, { pointsA: number; pointsB: number }>;
  /** Who the viewer is in this league (claimed team). Persisted per league. */
  me?: { name: string; rosterId: number | null };
  /** League leaderboard of calls. Local-only (just you) until shared leagues are connected. */
  leaderboard: LeaderRow[];
  /** 'local' = coins on this device only; 'shared' = synced with league-mates. */
  socialMode: 'local' | 'shared';
  /** When live stats/scores were last refreshed (epoch ms), for "updated 20s ago". */
  liveUpdatedAt?: number;
  /** No-vig home win probability per gameId from sportsbook moneylines (for display). */
  bookHomeWin?: Record<string, number>;
  /** League-mates' recent calls (shared leagues). */
  activity: social.ActivityRow[];
  /** Problem talking to the shared league service (shown on the League board). */
  socialError?: string;
}

export interface LeaderRow { userId: string; name: string; rosterId: number | null; profitCc: number; calls: number; correct: number; isMe: boolean }

let state: AppState = {
  status: 'idle', pricing: false, demoT: null, demoPlaying: false, history: {}, connectStatus: 'idle', bookVersion: 0, finals: {}, leaderboard: [], socialMode: 'local', activity: [],
};
const listeners = new Set<() => void>();
function set(patch: Partial<AppState>) { state = { ...state, ...patch }; listeners.forEach((l) => l()); }
export function getState(): AppState { return state; }
export function useApp(): AppState {
  return useSyncExternalStore((cb) => { listeners.add(cb); return () => listeners.delete(cb); }, () => state, () => state);
}

// ---------------------------------------------------------------- persistence (ledger + book + last league)
let ledger = new Ledger();
let book = new MarketBook(ledger);
const marketFair = new Map<string, number>(); // marketId -> model price the market is currently centred on
/** Every fill on this device, for per-league stats and for sharing with league-mates. */
export interface TradeLogRow { id: string; leagueKey: string; marketId: string; week: number; matchupId: number; title: string; side: Side; action: 'buy' | 'sell'; shares: number; amountCc: number; avgPrice: number; at: string; reported?: boolean }
let tradeLog: TradeLogRow[] = [];

function nowIso() { return new Date().toISOString(); }
function save() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      ledger: ledger.toJSON(), book: book.toJSON(), fair: [...marketFair.entries()], trades: tradeLog.slice(-2000),
      last: state.league?.platform === 'sleeper' ? { leagueId: state.league.leagueId, username: state.sleeper?.username } : null,
    }));
  } catch { /* storage unavailable: coins last for this tab only */ }
}
function restore() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    ledger = Ledger.fromJSON(data.ledger);
    book = MarketBook.fromJSON(data.book, ledger);
    for (const [k, v] of data.fair ?? []) marketFair.set(k, v);
    tradeLog = Array.isArray(data.trades) ? data.trades : [];
    return data.last as { leagueId: string; username?: string } | null;
  } catch {
    ledger = new Ledger(); book = new MarketBook(ledger); marketFair.clear(); tradeLog = [];
    return null;
  }
}
function ensureStartingCoins() {
  book.grant(USER_ID, STARTING_COINS * CC_PER_COIN, 'welcome', nowIso());
}

// ---------------------------------------------------------------- markets
export function marketIdFor(league: League, matchupId: number): string {
  return `${league.platform}:${league.leagueId}:w${league.week}:m${matchupId}`;
}
export function getBook(): MarketBook { return book; }
export function balanceCc(): number { return ledger.balance(`user:${USER_ID}`); }
export function positionFor(matchupId: number): Position | null {
  const l = state.league; if (!l) return null;
  const id = marketIdFor(l, matchupId);
  return book.get(id) ? book.position(USER_ID, id) : null;
}
export function marketFor(matchupId: number): MarketInfo | undefined {
  const l = state.league; if (!l) return undefined;
  return book.get(marketIdFor(l, matchupId));
}
/** Current YES (team A wins) price, or the model price if the market isn't open yet. */
export function marketPrice(matchupId: number): number | null {
  const l = state.league; if (!l) return null;
  const id = marketIdFor(l, matchupId);
  if (book.get(id)) return book.price(id);
  const p = state.prices?.find((x) => x.matchupId === matchupId);
  return p ? p.pWinA : null;
}

function teamName(league: League, rosterId: number) {
  return league.teams.find((t) => t.rosterId === rosterId)?.name ?? `Team ${rosterId}`;
}

/** Open (or re-centre) house markets on the latest model prices. */
function syncMarkets() {
  const { league, prices } = state; if (!league || !prices) return;
  for (const p of prices) {
    const id = marketIdFor(league, p.matchupId);
    const fair = Math.min(0.99, Math.max(0.01, p.pWinA));
    const info = book.get(id);
    if (!info) {
      book.open(id, `${teamName(league, p.teamA)} beats ${teamName(league, p.teamB)}`, fair, HOUSE_LOSS_BUDGET_COINS, nowIso());
      marketFair.set(id, fair);
    } else if (info.status === 'open' || info.status === 'halted') {
      const prev = marketFair.get(id) ?? info.fairAtOpen;
      if (Math.abs(prev - fair) > 1e-6) {
        recentre(info, prev, fair);
        marketFair.set(id, fair);
      }
    }
  }
  save();
}

/** Shift the LMSR state by b*(logit(new) - logit(old)): the house moves the price to the model, keeping flow skew. */
function recentre(info: MarketInfo, oldFair: number, newFair: number) {
  const logit = (p: number) => Math.log(p / (1 - p));
  const shift = info.state.b * (logit(newFair) - logit(oldFair));
  book.recentre(info.marketId, shift);
}

export interface TradeResult { ok: true; fill: Fill }
export interface TradeError { ok: false; error: string }

export function quote(matchupId: number, side: Side, shares: number) {
  const l = state.league; if (!l) return null;
  const id = marketIdFor(l, matchupId);
  if (!book.get(id) || shares <= 0 || !Number.isInteger(shares)) return null;
  try { return book.quote(id, side, shares); } catch { return null; }
}

export function buy(matchupId: number, side: Side, shares: number): TradeResult | TradeError {
  return trade('buy', matchupId, side, shares);
}
export function sell(matchupId: number, side: Side, shares: number): TradeResult | TradeError {
  return trade('sell', matchupId, side, shares);
}
function trade(kind: 'buy' | 'sell', matchupId: number, side: Side, shares: number): TradeResult | TradeError {
  const l = state.league; if (!l) return { ok: false, error: 'No league loaded.' };
  const id = marketIdFor(l, matchupId);
  try {
    const req = { marketId: id, userId: USER_ID, side, shares, clientOrderId: `${Date.now()}-${Math.random().toString(36).slice(2)}`, ts: nowIso() };
    const fill = kind === 'buy' ? book.buy(req) : book.sell(req);
    if (!fill.replayed) {
      tradeLog.push({
        id: req.clientOrderId, leagueKey: leagueKeyOf(l), marketId: id, week: l.week, matchupId,
        title: book.get(id)?.title ?? '', side, action: kind, shares, amountCc: fill.amountCc, avgPrice: Math.min(1, Math.max(0, fill.avgPrice)), at: req.ts,
      });
    }
    save();
    scheduleReport();
    set({ bookVersion: state.bookVersion + 1 });
    return { ok: true, fill };
  } catch (e) {
    const code = (e as { code?: string }).code;
    const msg: Record<string, string> = {
      INSUFFICIENT_FUNDS: 'Not enough coins for that many shares.',
      INSUFFICIENT_SHARES: "You don't hold that many shares.",
      NOT_OPEN: 'This market is closed to new calls.',
      BAD_SHARES: 'Pick a whole number of shares.',
    };
    return { ok: false, error: (code && msg[code]) || (e as Error).message };
  }
}

// ---------------------------------------------------------------- pricing
let priceSeq = 0;
async function reprice(sims = SIMS) {
  const { league, ctx } = state; if (!league || !ctx) return;
  const seq = ++priceSeq;
  set({ pricing: true });
  try {
    const prices = await priceInBackground(league, ctx, sims);
    if (seq !== priceSeq) return;
    const x = state.demoT ?? Date.now();
    const history = { ...state.history };
    for (const p of prices) {
      const h = (history[p.matchupId] ?? []).filter((pt) => pt.x !== x);
      h.push({ x, pA: p.pWinA });
      h.sort((a, b) => a.x - b.x);
      history[p.matchupId] = h.slice(-400);
    }
    set({ prices, pricing: false, status: 'ready', history });
    syncMarkets();
    settleIfFinal();
  } catch (e) {
    if (seq === priceSeq) set({ pricing: false, status: 'error', error: (e as Error).message });
  }
}

// ---------------------------------------------------------------- settlement
function finalPointsFromLive(league: League, ctx: WeekContext): Record<number, number> {
  const out: Record<number, number> = {};
  for (const t of league.teams) {
    let sum = 0;
    for (const pid of t.starters) {
      if (!pid || pid === '0') continue;
      const actual: StatLine = ctx.live?.[pid]?.actual ?? {};
      sum += scoreStatLine(actual, league.scoring, ctx.projections[pid]?.position ?? 'UNK');
    }
    out[t.rosterId] = Math.round(sum * 100) / 100;
  }
  return out;
}

function settleIfFinal() {
  const { league, ctx } = state; if (!league || !ctx) return;
  const allFinal = ctx.games.length > 0 && ctx.games.every((g) => g.status === 'complete');
  if (!allFinal) return;
  const finals = { ...state.finals };
  const demoPts = league.platform === 'demo' ? finalPointsFromLive(league, ctx) : null;
  for (const m of league.matchups) {
    const a = demoPts ? demoPts[m.teamA] : m.pointsA;
    const b = demoPts ? demoPts[m.teamB] : m.pointsB;
    if (a == null || b == null) continue;
    finals[m.matchupId] = { pointsA: a, pointsB: b };
    const id = marketIdFor(league, m.matchupId);
    const info = book.get(id);
    if (info && info.status !== 'settled') {
      try { book.settle(id, a > b ? 'YES' : a < b ? 'NO' : 'TIE', nowIso()); } catch { /* already settled differently: leave */ }
    }
  }
  save();
  set({ finals, bookVersion: state.bookVersion + 1 });
}

// ---------------------------------------------------------------- demo league
export async function loadDemo() {
  set({ status: 'loading', error: undefined, league: DEMO_LEAGUE, source: 'demo', demoT: null, demoPlaying: false, history: {}, prices: undefined, finals: {} });
  set({ ctx: demoWeekContext() });
  onLeagueLoaded();
  await reprice();
}

function demoCtxAt(t: number | null): WeekContext {
  const base = demoWeekContext();
  if (t === null) return base;
  const { games, live } = demoLiveAt(t);
  return { ...base, games, live, asOf: `${base.asOf}#t=${t.toFixed(3)}` };
}

/** Scrub the demo Sunday to t in [0,1]. */
export async function setDemoT(t: number | null) {
  if (state.league?.platform !== 'demo') return;
  const tt = t === null ? null : Math.min(1, Math.max(0, t));
  // Pregame points use clock time and replay points use 0..1: never mix them in one line.
  const modeChanged = (state.demoT === null) !== (tt === null);
  set({ demoT: tt, ctx: demoCtxAt(tt), ...(modeChanged ? { history: {} } : {}) });
  await reprice(tt === null ? SIMS : LIVE_SIMS);
}

let playTimer: ReturnType<typeof setTimeout> | null = null;
/** Play the demo Sunday from the current point; ~24 steps. */
export function playDemo() {
  if (state.league?.platform !== 'demo') return;
  stopDemo();
  set({ demoPlaying: true });
  const step = async () => {
    const t = state.demoT === null ? 0 : state.demoT + 1 / 24;
    await setDemoT(Math.min(1, t));
    if (state.demoPlaying && (state.demoT ?? 0) < 1) playTimer = setTimeout(step, 450);
    else set({ demoPlaying: false });
  };
  void step();
}
export function stopDemo() { if (playTimer) clearTimeout(playTimer); playTimer = null; if (state.demoPlaying) set({ demoPlaying: false }); }

// ---------------------------------------------------------------- Sleeper
const client = new SleeperClient();

export async function connectSleeper(username: string) {
  set({ connectStatus: 'loading', connectError: undefined });
  try {
    const found = await findLeagues(client, username);
    set({ connectStatus: 'idle', sleeper: { username: username.trim().toLowerCase(), userId: found.userId, displayName: found.displayName, leagues: found.leagues } });
    return found.leagues;
  } catch (e) {
    const code = (e as { code?: string }).code;
    set({ connectStatus: 'error', connectError: code === 'NOT_FOUND' ? `No Sleeper user called "${username.trim()}".` : code === 'BAD_INPUT' ? 'Type your Sleeper username.' : "Couldn't reach Sleeper. Check your connection and try again." });
    return [];
  }
}

export async function openSleeperLeague(leagueId: string) {
  stopDemo();
  set({ status: 'loading', error: undefined, demoT: null, history: {}, prices: undefined, finals: {} });
  try {
    const st = await client.getState();
    const week = st.display_week || st.week;
    const league = await loadLeague(client, leagueId, week, state.sleeper?.userId ?? null);
    const starters = [...new Set(league.teams.flatMap((t) => t.players))];
    let primary: WeekContext['projections'] | undefined;
    let games: WeekContext['games'] = [];
    try {
      const [rows, sched] = await Promise.all([client.getProjections(league.season, week), client.getSchedule(league.season)]);
      primary = projectionsFromSleeper(rows);
      games = scheduleFromSleeper(sched, week);
    } catch { /* undocumented endpoints unavailable: heuristic only */ }
    let fallback: WeekContext['projections'] | undefined;
    const missing = starters.filter((id) => !primary?.[id]);
    if (missing.length) {
      try { fallback = heuristicProjections(missing, await client.getPlayers()); } catch { /* none */ }
    }
    let bookHomeWin: Record<string, number> | undefined;
    try {
      const espn = await fetchEspnWeek(league.season, week);
      if (espn.games.length) {
        games = mergeLines(espn.games, loadLines(league.season, week));
        saveLines(league.season, week, games);
        bookHomeWin = espn.homeWinProb;
      }
    } catch { /* ESPN unavailable: Sleeper schedule, default lines */ }
    let ctx = buildWeekContext({ season: league.season, week, games, primary, fallback, asOf: nowIso() });
    if (games.some((g) => g.status !== 'scheduled')) {
      try { ctx = withLive(ctx, games, await fetchLive(league.season, week, games), Date.now()); } catch { /* keep pregame */ }
    }
    set({ league, ctx, bookHomeWin, liveUpdatedAt: Date.now(), source: primary && Object.keys(primary).length ? 'sleeper-weekly' : 'heuristic' });
    onLeagueLoaded();
    await reprice();
    save();
    startLivePolling();
  } catch (e) {
    set({ status: 'error', error: (e as Error).message || 'Could not load that league.' });
  }
}

// ---------------------------------------------------------------- boot
let booted = false;
export async function boot() {
  if (booted) return; booted = true;
  const last = restore();
  ensureStartingCoins();
  save();
  if (last?.leagueId) {
    if (last.username) { void connectSleeper(last.username); }
    await openSleeperLeague(last.leagueId);
    if (state.status === 'error') await loadDemo();
  } else {
    await loadDemo();
  }
}

/** Forget the Sleeper league and go back to the sample league (coins are kept). */
export async function useSampleLeague() { await loadDemo(); save(); }

export function teamByRoster(rosterId: number) { return state.league?.teams.find((t) => t.rosterId === rosterId); }
export function priceFor(matchupId: number) { return state.prices?.find((p) => p.matchupId === matchupId); }
/** The viewer's matchup, if they have a team in this league. */
export function myMatchup() {
  const l = state.league; if (!l || l.myRosterId == null) return undefined;
  return l.matchups.find((m) => m.teamA === l.myRosterId || m.teamB === l.myRosterId);
}

// ---------------------------------------------------------------- identity + leaderboard (local until shared leagues)
/** Claim your team in this league (honor system; free coins only). */
export function setMe(name: string, rosterId: number | null) {
  set({ me: { name: name.trim().slice(0, 40) || 'You', rosterId } });
  try { localStorage.setItem(`fmm.me.${state.league?.leagueId ?? 'none'}`, JSON.stringify(state.me)); } catch { /* ignore */ }
  refreshLeaderboard();
}

/** Profit = coins now + open positions at market value - coins granted. Calls = markets traded. */
export function myStats(): { profitCc: number; calls: number; correct: number } {
  const granted = STARTING_COINS * CC_PER_COIN;
  let open = 0, calls = 0, correct = 0;
  for (const pos of book.positions(USER_ID)) {
    if (pos.yes === 0 && pos.no === 0 && pos.costBasisCc === 0) continue;
    calls++;
    const info = book.get(pos.marketId);
    if (info?.status === 'settled') {
      if ((info.outcome === 'YES' && pos.yes > pos.no) || (info.outcome === 'NO' && pos.no > pos.yes)) correct++;
    } else {
      open += book.markValueCc(USER_ID, pos.marketId);
    }
  }
  return { profitCc: balanceCc() + open - granted, calls, correct };
}

export function refreshLeaderboard() { refreshLeaderboardLocal(); }

// ---------------------------------------------------------------- live updates for real leagues
function loadLines(season: string, week: number): WeekContext['games'] {
  try { return JSON.parse(localStorage.getItem(`fmm.lines.${season}.${week}`) || '[]'); } catch { return []; }
}
function saveLines(season: string, week: number, games: WeekContext['games']) {
  try {
    const keep = games.filter((g) => g.impliedTotal != null || g.spread != null).map((g) => ({ ...g }));
    if (keep.length) localStorage.setItem(`fmm.lines.${season}.${week}`, JSON.stringify(keep));
  } catch { /* ignore */ }
}

let liveTimer: ReturnType<typeof setInterval> | null = null;
function startLivePolling() {
  if (liveTimer) clearInterval(liveTimer);
  liveTimer = setInterval(() => { void refreshLive(); }, 60_000);
}

/** Pull fresh scores, clocks and player stats, then reprice. Only while games are on. */
export async function refreshLive() {
  const { league, ctx } = state;
  if (!league || !ctx || league.platform !== 'sleeper') return;
  if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
  const anyLive = ctx.games.some((g) => g.status === 'in_progress') ||
    ctx.games.some((g) => g.status === 'scheduled' && g.kickoff && Date.parse(g.kickoff) <= Date.now());
  if (!anyLive) return;
  try {
    const espn = await fetchEspnWeek(league.season, league.week);
    const games = mergeLines(espn.games, ctx.games);
    const live = await fetchLive(league.season, league.week, games);
    // An empty map during live games means a failed read: keep the last good one.
    const next = Object.keys(live).length ? withLive(ctx, games, live, Date.now()) : { ...ctx, games };
    let fresh = league;
    try { fresh = await loadLeague(client, league.leagueId, league.week, state.sleeper?.userId ?? null); } catch { /* keep */ }
    set({ ctx: next, league: { ...fresh, myRosterId: fresh.myRosterId ?? league.myRosterId }, liveUpdatedAt: Date.now() });
    await reprice(LIVE_SIMS);
  } catch { /* try again next tick */ }
}

// ---------------------------------------------------------------- per-league stats + shared leagues
export function leagueKeyOf(l: League): string { return `${l.platform}:${l.leagueId}:${l.season}`; }

/** Stats for the loaded league only: profit = sells + payouts + open value - buys. */
export function leagueStats(): { profitCc: number; calls: number; correct: number; settled: number } {
  const l = state.league; if (!l) return { profitCc: 0, calls: 0, correct: 0, settled: 0 };
  const prefix = `${l.platform}:${l.leagueId}:`;
  let flow = 0;
  for (const t of tradeLog) if (t.marketId.startsWith(prefix)) flow += t.action === 'buy' ? -t.amountCc : Math.abs(t.amountCc);
  let value = 0, calls = 0, correct = 0, settled = 0;
  for (const pos of book.positions(USER_ID)) {
    if (!pos.marketId.startsWith(prefix)) continue;
    const info = book.get(pos.marketId);
    const traded = tradeLog.some((t) => t.marketId === pos.marketId);
    if (!traded && pos.yes === 0 && pos.no === 0) continue;
    calls++;
    if (info?.status === 'settled') {
      settled++;
      const o = info.outcome;
      value += o === 'YES' ? pos.yes * 100 : o === 'NO' ? pos.no * 100 : o === 'TIE' ? (pos.yes + pos.no) * 50 : pos.costBasisCc;
      if ((o === 'YES' && pos.yes > pos.no) || (o === 'NO' && pos.no > pos.yes)) correct++;
    } else {
      value += book.markValueCc(USER_ID, pos.marketId);
    }
  }
  return { profitCc: flow + value, calls, correct, settled };
}

function localRow(): LeaderRow {
  const s = leagueStats();
  return { userId: USER_ID, name: state.me?.name ?? 'You', rosterId: state.me?.rosterId ?? state.league?.myRosterId ?? null, profitCc: s.profitCc, calls: s.calls, correct: s.correct, isMe: true };
}

function onLeagueLoaded() {
  const l = state.league; if (!l) return;
  let me: AppState['me'];
  try { const raw = localStorage.getItem(`fmm.me.${l.leagueId}`); me = raw ? JSON.parse(raw) : undefined; } catch { me = undefined; }
  const joined = social.identityFor(leagueKeyOf(l));
  set({ me, socialMode: joined ? 'shared' : 'local', activity: [], socialError: undefined, leaderboard: [localRow()] });
  void syncSocial();
}

let reportTimer: ReturnType<typeof setTimeout> | null = null;
function scheduleReport() {
  if (reportTimer) clearTimeout(reportTimer);
  reportTimer = setTimeout(() => { void syncSocial(); }, 1500);
  refreshLeaderboardLocal();
}

function refreshLeaderboardLocal() {
  const rows = state.leaderboard.filter((r) => !r.isMe);
  set({ leaderboard: [...rows, localRow()].sort((a, b) => b.profitCc - a.profitCc) });
}

/** Report my calls and stats for this league (if joined), then fetch the shared leaderboard + feed. */
export async function syncSocial() {
  const l = state.league; if (!l) return;
  const key = leagueKeyOf(l);
  const id = social.identityFor(key);
  try {
    if (id) {
      const pending = tradeLog.filter((t) => t.leagueKey === key && !t.reported).slice(0, 50);
      const s = leagueStats();
      const res = await social.report(id, { profitCc: s.profitCc, calls: s.calls, correct: s.correct }, pending);
      if (res === 'unauthorized') { social.forget(key); set({ socialMode: 'local' }); }
      else { for (const t of pending) t.reported = true; save(); }
    }
    const board = await social.fetchLeague(key);
    const myId = social.identityFor(key)?.playerId;
    const rows: LeaderRow[] = board.players.filter((p) => p.playerId !== myId).map((p) => ({ userId: p.playerId, name: p.name, rosterId: p.rosterId, profitCc: p.profitCc, calls: p.calls, correct: p.correct, isMe: false }));
    rows.push(localRow());
    set({ leaderboard: rows.sort((a, b) => b.profitCc - a.profitCc), activity: board.activity, socialError: undefined, socialMode: myId ? 'shared' : 'local' });
  } catch {
    set({ socialError: "Couldn't reach the league board. Your coins are safe on this device." });
  }
}

/** Join this league's shared board under a display name. Returns an error message or null. */
export async function joinLeague(name: string, rosterId: number | null): Promise<string | null> {
  const l = state.league; if (!l) return 'No league loaded.';
  const clean = name.trim().slice(0, 40);
  if (!clean) return 'Pick a display name.';
  const res = await social.join(leagueKeyOf(l), clean, rosterId);
  if (typeof res === 'string') return res;
  setMe(res.name, rosterId);
  set({ socialMode: 'shared' });
  await syncSocial();
  return null;
}

let socialTimer: ReturnType<typeof setInterval> | null = null;
if (typeof window !== 'undefined') {
  socialTimer = setInterval(() => { if (document.visibilityState !== 'hidden') void syncSocial(); }, 90_000);
}
export function _stopTimers() { if (socialTimer) clearInterval(socialTimer); if (liveTimer) clearInterval(liveTimer); }
export function getTradeLog(): readonly TradeLogRow[] { return tradeLog; }
