/** "Call it": pick a side, pick shares, back it with coins. Then your position. Owner: WP-12. */
import { useState, type CSSProperties } from 'react';
import type { MarketStatus } from '@fmm/market';
import { PAYOUT_CC_PER_SHARE, TIE_PAYOUT_CC_PER_SHARE, type Side } from '@fmm/core';
import {
  balanceCc, buy, getBook, marketFor, marketIdFor, marketPrice, positionFor, quote, sell, USER_ID,
} from '../../state/store';
import { cents, coins, pct, pts } from '../../lib/format';
import { shortName, toneOf, type Slot, type View } from './model';

const PRESETS = [10, 50, 100, 250];
const sideOf = (slot: Slot): Side => (slot === 'A' ? 'YES' : 'NO');
type Msg = { ok: boolean; text: string } | null;

export function Ticket({ v }: { v: View }) {
  const id = v.matchup.matchupId;
  const league = v.league;
  const market = marketFor(id);
  const status: MarketStatus | undefined = market?.status;
  const settled = status === 'settled';

  const [slot, setSlot] = useState<Slot>(v.viewer ?? 'A');
  const [sharesText, setSharesText] = useState('100');
  const [msg, setMsg] = useState<Msg>(null);

  // YES = team A wins. The NO share is priced at 1 minus YES.
  const yes = marketPrice(id) ?? v.price?.pWinA ?? null;
  const priceOf = (sl: Slot): number | null => (yes == null ? null : sl === 'A' ? yes : 1 - yes);
  const sidePx = priceOf(slot);
  const name = shortName(v.teams[slot], slot);
  const tone = toneOf(v, slot);

  const shares = /^\d+$/.test(sharesText) ? Number(sharesText) : NaN;
  const sharesOk = Number.isSafeInteger(shares) && shares >= 1;
  const q = sharesOk ? quote(id, sideOf(slot), shares) : null;
  const bal = balanceCc();
  const canBuy = !!q && status === 'open' && yes != null && bal >= q.costCc;
  const hint = tradeHint(status, yes, sharesOk, q?.costCc ?? null, bal);

  const modelP = v.price ? (slot === 'A' ? v.price.pWinA : v.price.pWinB) : null;
  const explain: string[] = [];
  if (modelP != null && sidePx != null) {
    explain.push(`The model gives ${name} a ${pct(modelP)} chance, so a share starts at ${cents(sidePx)}.`);
  }
  if (q && sharesOk) explain.push(`Buying ${shares} moves it to ${cents(q.priceAfter)}, about ${cents(q.avgPrice)} each.`);
  explain.push(`Settles on ${league.platform === 'sleeper' ? "Sleeper's" : "the sample league's"} final score.`);
  explain.push(`A tie pays ${TIE_PAYOUT_CC_PER_SHARE}¢ a share.`);

  function onBuy() {
    if (!q || !sharesOk) return;
    const r = buy(id, sideOf(slot), shares);
    setMsg(r.ok
      ? { ok: true, text: `Done: ${r.fill.shares} shares of ${name} at ${cents(r.fill.avgPrice)}.` }
      : { ok: false, text: r.error });
  }

  return (
    <div className="mx-ticket-panel">
      <h2 className="h2" id="mx-call-h">Call it</h2>

      {settled ? (
        <SettledBlock v={v} id={id} outcome={market?.outcome} />
      ) : (
        <>
          <div className="mx-tiles">
            {(['A', 'B'] as Slot[]).map((sl) => {
              const t = toneOf(v, sl);
              const px = priceOf(sl);
              return (
                <button
                  key={sl}
                  type="button"
                  className="mx-tile"
                  aria-pressed={slot === sl}
                  onClick={() => { setSlot(sl); setMsg(null); }}
                  style={{ '--tone': t.color, '--wash': t.wash } as CSSProperties}
                >
                  <span className="small">{shortName(v.teams[sl], sl)} wins</span>
                  <span className="num mx-tile-px" style={{ color: t.color }}>{px == null ? '—' : cents(px)}</span>
                </button>
              );
            })}
          </div>

          <div className="mx-shares">
            <label htmlFor="mx-shares-in" className="muted">Shares</label>
            <input
              id="mx-shares-in"
              className="mx-shares-input num"
              type="number"
              inputMode="numeric"
              min={1}
              step={1}
              value={sharesText}
              onChange={(e) => { setSharesText(e.target.value); setMsg(null); }}
            />
          </div>
          <div className="mx-chips" role="group" aria-label="Quick share amounts">
            {PRESETS.map((n) => (
              <button
                key={n}
                type="button"
                className="mx-chip"
                aria-pressed={sharesOk && shares === n}
                onClick={() => { setSharesText(String(n)); setMsg(null); }}
              >
                {n}
              </button>
            ))}
          </div>

          <div className="rows mx-rows">
            <div className="row">
              <span className="muted">Cost</span>
              <span className="tnum mx-amt">{q ? `${coins(q.costCc)} coins` : '—'}</span>
            </div>
            <div className="row">
              <span className="muted">Pays if {name} wins</span>
              <span className="tnum mx-amt" style={{ color: tone.color }}>
                {sharesOk ? `${coins(shares * PAYOUT_CC_PER_SHARE)} coins` : '—'}
              </span>
            </div>
          </div>

          <p className="small muted mx-explain">{explain.join(' ')}</p>

          <button
            type="button"
            className={`btn mx-cta ${tone.cls === 'you' ? 'mx-cta-you' : 'mx-cta-rival'}`}
            disabled={!canBuy}
            onClick={onBuy}
          >
            {q ? `Back ${name} for ${coins(q.costCc)} coins` : `Back ${name}`}
          </button>
          {hint && <p className="small muted">{hint}</p>}
        </>
      )}

      <p className={`small mx-msg${msg && !msg.ok ? ' error' : ''}`} role="status" aria-live="polite">
        {msg?.text ?? ''}
      </p>

      <PositionBlock v={v} id={id} status={status} onMsg={setMsg} />
    </div>
  );
}

function tradeHint(
  status: MarketStatus | undefined,
  yes: number | null,
  sharesOk: boolean,
  costCc: number | null,
  bal: number,
): string | null {
  if (status === 'settled') return null;
  if (yes == null) return 'Pricing this matchup. One moment.';
  if (status === undefined) return "The house hasn't opened this market yet.";
  if (status === 'halted') return 'Calls are paused for this matchup.';
  if (status === 'closed') return 'Calls are closed. Lineups are locked for this matchup.';
  if (!sharesOk) return 'Pick a whole number of shares, 1 or more.';
  if (costCc == null) return "Can't price that many shares right now.";
  if (bal < costCc) return `That costs ${coins(costCc)} coins. You have ${coins(bal)}.`;
  return null;
}

function SettledBlock({ v, id, outcome }: { v: View; id: number; outcome: string | undefined }) {
  const f = v.final;
  let headline = 'This matchup is settled.';
  if (f) {
    if (f.pointsA === f.pointsB) {
      headline = `Final: tie at ${pts(f.pointsA)}`;
    } else {
      const w: Slot = f.pointsA > f.pointsB ? 'A' : 'B';
      const hi = Math.max(f.pointsA, f.pointsB);
      const lo = Math.min(f.pointsA, f.pointsB);
      headline = `Final: ${shortName(v.teams[w], w)} won ${pts(hi)} to ${pts(lo)}`;
    }
  }
  const pos = positionFor(id);
  let payout = 0;
  if (pos && outcome === 'YES') payout = pos.yes * PAYOUT_CC_PER_SHARE;
  else if (pos && outcome === 'NO') payout = pos.no * PAYOUT_CC_PER_SHARE;
  else if (pos && outcome === 'TIE') payout = (pos.yes + pos.no) * TIE_PAYOUT_CC_PER_SHARE;
  else if (pos && outcome === 'VOID') payout = pos.costBasisCc;
  const held = pos ? pos.yes + pos.no : 0;
  const payLine = held === 0
    ? "You didn't hold shares here."
    : payout > 0
      ? `Your shares paid ${coins(payout)} coins.`
      : 'Your shares paid nothing.';
  return (
    <div className="mx-settled">
      <p className="h2">{headline}</p>
      <p className="small muted">{payLine}</p>
    </div>
  );
}

function PositionBlock({ v, id, status, onMsg }: { v: View; id: number; status: MarketStatus | undefined; onMsg: (m: Msg) => void }) {
  const pos = positionFor(id);
  const [sellSide, setSellSide] = useState<Slot | null>(null);
  const [sellText, setSellText] = useState<string | null>(null);

  const held = pos ? pos.yes + pos.no : 0;
  if (!pos || held === 0) {
    return (
      <div className="mx-position">
        <h3 className="small muted mx-pos-h">Your position</h3>
        <p className="small muted">No calls on this matchup yet.</p>
      </div>
    );
  }

  const heldSlots = (['A', 'B'] as Slot[]).filter((sl) => (sl === 'A' ? pos.yes : pos.no) > 0);
  const activeSlot: Slot = sellSide && heldSlots.includes(sellSide) ? sellSide : heldSlots[0];
  const heldOfSide = activeSlot === 'A' ? pos.yes : pos.no;
  const sellRaw = sellText ?? String(heldOfSide);
  const sellN = /^\d+$/.test(sellRaw) ? Number(sellRaw) : NaN;
  const sellOk = Number.isSafeInteger(sellN) && sellN >= 1 && sellN <= heldOfSide;
  const avgCents = cents(pos.costBasisCc / held / 100);

  let worth: number | null = null;
  try { worth = getBook().markValueCc(USER_ID, marketIdFor(v.league, id)); } catch { worth = null; }
  const up = worth == null ? 0 : worth - pos.costBasisCc;
  const settled = status === 'settled';

  function onSell() {
    if (!sellOk) return;
    const r = sell(id, sideOf(activeSlot), sellN);
    if (r.ok) {
      setSellText(null);
      onMsg({
        ok: true,
        text: `Sold ${sellN} shares of ${shortName(v.teams[activeSlot], activeSlot)} at ${cents(r.fill.avgPrice)} for ${coins(-r.fill.amountCc)} coins.`,
      });
    } else {
      onMsg({ ok: false, text: r.error });
    }
  }

  return (
    <div className="mx-position">
      <h3 className="small muted mx-pos-h">Your position</h3>
      {heldSlots.map((sl) => (
        <p key={sl} className="mx-pos-line">
          {sl === 'A' ? pos.yes : pos.no} shares of {shortName(v.teams[sl], sl)}
        </p>
      ))}
      <p className="small muted">Average cost {avgCents}</p>
      {!settled && worth != null && (
        <p className={`mx-worth ${up >= 0 ? 'you' : 'rival'}`}>
          Worth {coins(worth)} coins now, {up >= 0 ? 'up' : 'down'} {coins(Math.abs(up))}
        </p>
      )}

      {status === 'open' && (
        <div className="mx-sell">
          {heldSlots.length > 1 && (
            <div className="mx-chips" role="group" aria-label="Which side to sell">
              {heldSlots.map((sl) => (
                <button
                  key={sl}
                  type="button"
                  className="mx-chip"
                  aria-pressed={sl === activeSlot}
                  onClick={() => { setSellSide(sl); setSellText(null); }}
                >
                  {shortName(v.teams[sl], sl)}
                </button>
              ))}
            </div>
          )}
          <div className="mx-shares">
            <label htmlFor="mx-sell-in" className="muted">Shares to sell</label>
            <input
              id="mx-sell-in"
              className="mx-shares-input mx-shares-input-sm num"
              type="number"
              inputMode="numeric"
              min={1}
              max={heldOfSide}
              step={1}
              value={sellRaw}
              onChange={(e) => setSellText(e.target.value)}
            />
          </div>
          <button type="button" className="btn mx-sell-btn" disabled={!sellOk} onClick={onSell}>
            {sellOk ? `Sell ${sellN} shares` : 'Sell shares'}
          </button>
        </div>
      )}
    </div>
  );
}
