/** Cyan (you / team A) vs pink (rival / team B) split bar. Neutral mode = white vs gray for other people's games. Owner: Commander. */
export function TugBar({ pA, height = 10, neutral = false, flip = false }: { pA: number; height?: number; neutral?: boolean; flip?: boolean }) {
  const a = Math.min(99, Math.max(1, Math.round(pA * 100)));
  const left = neutral ? (a >= 50 ? 'var(--color-text)' : 'var(--color-rule)') : (flip ? 'var(--color-rival)' : 'var(--color-you)');
  const right = neutral ? (a >= 50 ? 'var(--color-rule)' : 'var(--color-text)') : (flip ? 'var(--color-you)' : 'var(--color-rival)');
  return (
    <div className="tug" role="img" aria-label={`${a}% to ${100 - a}%`} style={{ height }}>
      <div style={{ width: `${a}%`, height, background: left }} />
      <div style={{ flex: 1, height, background: right }} />
    </div>
  );
}
