/**
 * Win-probability line for team A (the viewer's side when they're in the game). White line, dashed 50% guide,
 * pink marker at the low point, cyan pulse at the latest point. Pure SVG, responsive width. Owner: Commander.
 */
import type { ProbPoint } from '../state/store';

export function ProbabilityLine({ points, height = 200, xDomain }: { points: ProbPoint[]; height?: number; xDomain?: [number, number] }) {
  const W = 1000, H = height, pad = 10;
  if (points.length === 0) return <div className="skeleton" style={{ height }} />;
  const xs = points.map((p) => p.x);
  const [x0, x1] = xDomain ?? [Math.min(...xs), Math.max(...xs) === Math.min(...xs) ? Math.min(...xs) + 1 : Math.max(...xs)];
  const sx = (x: number) => ((x - x0) / (x1 - x0 || 1)) * (W - 2 * pad) + pad;
  const sy = (p: number) => (1 - p) * (H - 2 * pad) + pad;
  const d = points.map((p, i) => `${i ? 'L' : 'M'}${sx(p.x).toFixed(1)} ${sy(p.pA).toFixed(1)}`).join(' ');
  const last = points[points.length - 1];
  const low = points.reduce((m, p) => (p.pA < m.pA ? p : m), points[0]);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} preserveAspectRatio="none" role="img"
      aria-label={`Win chance now ${Math.round(last.pA * 100)}%, low ${Math.round(low.pA * 100)}%`}>
      <line x1={0} x2={W} y1={sy(0.5)} y2={sy(0.5)} stroke="var(--color-rule)" strokeDasharray="4 6" vectorEffect="non-scaling-stroke" />
      <path d={d} fill="none" stroke="var(--color-text)" strokeWidth={2.5} strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
      {points.length > 2 && low !== last && <circle cx={sx(low.x)} cy={sy(low.pA)} r={4} fill="var(--color-rival)" />}
      <circle cx={sx(last.x)} cy={sy(last.pA)} r={11} fill="var(--color-you)" opacity={0.2} />
      <circle cx={sx(last.x)} cy={sy(last.pA)} r={5} fill="var(--color-you)" />
    </svg>
  );
}
