/**
 * Coins are integers in CENTICOINS (1 coin = 100 cc) everywhere money moves. Never store floats in a ledger.
 * One winning share pays exactly 1 coin = 100 cc. A tie pays 50 cc per share on both sides (League Mode rule).
 * Owner: Commander.
 */
export const CC_PER_COIN = 100;
export const PAYOUT_CC_PER_SHARE = 100;
export const TIE_PAYOUT_CC_PER_SHARE = 50;
export const STARTING_COINS = 1000;

/** Charge a buyer: round a float coin cost UP to whole centicoins (house never loses to rounding). */
export function chargeCc(coins: number): number {
  if (!Number.isFinite(coins)) throw new Error(`chargeCc: non-finite ${coins}`);
  return Math.ceil(coins * CC_PER_COIN - 1e-9);
}

/** Pay a seller: round a float coin amount DOWN to whole centicoins. */
export function payCc(coins: number): number {
  if (!Number.isFinite(coins)) throw new Error(`payCc: non-finite ${coins}`);
  return Math.floor(coins * CC_PER_COIN + 1e-9);
}

/** 12345 cc -> "123.45". */
export function ccToCoins(cc: number): number {
  return cc / CC_PER_COIN;
}

/** Display a price 0..1 as whole cents clamped to 1..99, e.g. 0.623 -> 62. */
export function priceCents(p: number): number {
  return Math.min(99, Math.max(1, Math.round(p * 100)));
}
