/**
 * WP-16 — Live player stats from Sleeper's UNDOCUMENTED stats endpoint
 * (https://api.sleeper.app/stats/nfl/<season>/<week>?season_type=regular&position[]=QB&...&position[]=DEF),
 * which updates during games (verified live on MNF 2026-10-26). Combined with ESPN game clocks this conditions
 * the simulation on what has already happened.
 * Shape: fixtures/sleeper-stats-week7.sample.json. Owner: WP-16. Imports allowed: '@fmm/core', './raw', './client'.
 */
import type { NflGame, PlayerLive, WeekContext } from '@fmm/core';
import { cleanStatLine } from '@fmm/core';
import { SLEEPER_BASE, SleeperError, type FetchLike, type FetchLikeResponse } from './client';

export interface SleeperStatRow {
  player_id: string;
  team: string | null;
  opponent?: string | null;
  game_id?: string | null;
  stats: Record<string, number>;
  updated_at?: number;
  player?: { position?: string; first_name?: string; last_name?: string; team?: string | null };
  [k: string]: unknown;
}

const STATS_POSITIONS = ['QB', 'RB', 'WR', 'TE', 'K', 'DEF'] as const;

/** URL builder for the stats endpoint with all six positions. */
export function statsUrl(season: string, week: number): string {
  const positions = STATS_POSITIONS.map((p) => `position[]=${p}`).join('&');
  return `${SLEEPER_BASE}/stats/nfl/${encodeURIComponent(season)}/${String(week)}?season_type=regular&${positions}`;
}

/**
 * Build PlayerLive for every row whose team plays in `games`:
 *  actual = cleanStatLine(row.stats) from @fmm/core (drops pts_*, snaps, gp);
 *  fractionRemaining = the fractionRemaining of the game containing row.team (home or away), via game.fractionRemaining
 *    if set else status (scheduled 1, in_progress 0.5, complete 0). A team with no game this week (bye) -> 0 (final, 0 pts).
 *  Rows for teams in a 'scheduled' game are skipped (not started; stats would be empty anyway).
 *  DEF rows: Sleeper reports defense stats under player_id = team abbr; keep them (pts_allow etc. are dropped by
 *  cleanStatLine except pts_allow/yds_allow, which ARE catalog keys — keep them only when the game is complete).
 */
export function liveFromSleeperStats(rows: SleeperStatRow[], games: NflGame[]): Record<string, PlayerLive> {
  const byTeam = gamesByTeam(games);
  const out = new Map<string, PlayerLive>();
  for (const row of Array.isArray(rows) ? rows : []) {
    if (!isObject(row)) continue;
    const playerId = idOf(row.player_id);
    if (playerId === null || out.has(playerId)) continue;
    const team = teamOf(row, playerId);
    if (team === null) continue;

    const game = byTeam.get(team);
    if (game?.status === 'scheduled') continue;
    // A team with no game this week is a bye: final, so it contributes nothing more.
    const fractionRemaining = game ? fractionOf(game) : 0;
    const complete = game?.status === 'complete';

    const actual = cleanStatLine(isObject(row.stats) ? row.stats : {});
    if (!complete) {
      delete actual.pts_allow;
      delete actual.yds_allow;
    }
    out.set(playerId, { playerId, actual, fractionRemaining });
  }
  return Object.fromEntries(out);
}

/** Fetch rows (via fetchImpl or global fetch) and build the live map. */
export async function fetchLive(season: string, week: number, games: NflGame[], fetchImpl?: FetchLike): Promise<Record<string, PlayerLive>> {
  const fetchFn: FetchLike = fetchImpl ?? ((url) => globalThis.fetch(url, { credentials: 'omit' }));
  const url = statsUrl(season, week);

  let res: FetchLikeResponse;
  try {
    res = await fetchFn(url);
  } catch (err) {
    // Callers must keep their last good live map on failure: an empty map reads as "not started".
    throw new SleeperError('NETWORK', `Network error calling Sleeper: ${url} (${errorText(err)})`);
  }
  if (!res.ok) throw new SleeperError('HTTP', `Sleeper responded ${res.status} for ${url}`, res.status);

  let body: unknown;
  try {
    body = await res.json();
  } catch {
    return {};
  }
  if (!Array.isArray(body)) return {};
  return liveFromSleeperStats(body as SleeperStatRow[], games);
}

/** Return a copy of ctx with `games` replaced and `live` set, asOf = new Date(nowMs).toISOString(). Pure. */
export function withLive(ctx: WeekContext, games: NflGame[], live: Record<string, PlayerLive>, nowMs: number): WeekContext {
  return { ...ctx, games: [...games], live: { ...live }, asOf: new Date(nowMs).toISOString() };
}

// ---- internals -----------------------------------------------------------------------------------------------

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null;
}

function idOf(raw: unknown): string | null {
  if (typeof raw === 'string' && raw.trim() !== '') return raw.trim();
  if (typeof raw === 'number' && Number.isFinite(raw)) return String(raw);
  return null;
}

function abbr(raw: unknown): string | null {
  return typeof raw === 'string' && raw.trim() !== '' ? raw.trim().toUpperCase() : null;
}

/** Team of a stats row; DEF rows fall back to their player_id, which is the team abbreviation. */
function teamOf(row: Record<string, unknown>, playerId: string): string | null {
  const player = isObject(row.player) ? row.player : undefined;
  const direct = abbr(row.team) ?? abbr(player?.team);
  if (direct !== null) return direct;
  return player?.position === 'DEF' ? abbr(playerId) : null;
}

/** Team abbreviation -> the first game of this week that team plays in. */
function gamesByTeam(games: NflGame[]): Map<string, NflGame> {
  const map = new Map<string, NflGame>();
  for (const game of Array.isArray(games) ? games : []) {
    if (!isObject(game)) continue;
    for (const team of [abbr(game.home), abbr(game.away)]) {
      if (team !== null && !map.has(team)) map.set(team, game);
    }
  }
  return map;
}

/** Share of the game still to play: explicit fractionRemaining, else derived from status. */
function fractionOf(game: NflGame): number {
  if (typeof game.fractionRemaining === 'number' && Number.isFinite(game.fractionRemaining)) {
    return Math.min(1, Math.max(0, game.fractionRemaining));
  }
  switch (game.status) {
    case 'in_progress': return 0.5;
    case 'complete': return 0;
    default: return 1;
  }
}

function errorText(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}
