const GAME_LEN = 0.25;

const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
function opponentOf(team: string): { opp: string; gameId: string } | null {
  const g = DEMO_GAMES.find((x) => x.home === team || x.away === team);
  return g ? { opp: g.home === team ? g.away : g.home, gameId: g.gameId } : null;
}

function buildProjections(): Record<string, PlayerProjection> {
  const out: Record<string, PlayerProjection> = {};
  const add = (id: string, name: string, position: Position, team: string, tier: number) => {
    const rng = createRng(seedFrom(`demo-proj|${id}`));
    const variety = 0.9 + 0.2 * rng.next();
    const base = TIER_TABLE[position][Math.min(3, Math.max(0, tier))];
    const mean: StatLine = {};
    for (const [k, v] of Object.entries(base)) mean[k] = Math.round(v * variety * 100) / 100;
    const o = opponentOf(team);
    out[id] = { playerId: id, name, position, team, opponent: o?.opp ?? null, gameId: o?.gameId ?? null, injuryStatus: null, mean, source: 'demo' };
  };
  for (const [team, pos, name, tier] of POOL) add(`demo-${slug(name)}`, name, pos, team, tier);
  for (const [team, tier] of KD_TEAMS) {
    add(`demo-k-${team.toLowerCase()}`, `${NICK[team][1]}`, 'K', team, tier);
    add(team, `${NICK[team][0]} ${NICK[team][1]}`, 'DEF', team, tier);
  }
  // A touch of realism: one questionable star.
  if (out['demo-tyreek-hill']) out['demo-tyreek-hill'].injuryStatus = 'Questionable';
  return out;
}

const PROJECTIONS = buildProjections();

function projPts(p: PlayerProjection): number {
  let s = 0;
  for (const [k, v] of Object.entries(p.mean)) s += (PPR[k] ?? 0) * v;
  if (p.position === 'DEF') s += 1; // typical points-allowed bucket
  return s;
}

const SLOTS: (Position | 'FLEX')[] = ['QB', 'RB', 'RB', 'WR', 'WR', 'TE', 'FLEX', 'K', 'DEF'];
const BENCH = 2;
const N_TEAMS = 12;

function draft(): { starters: string[]; bench: string[] }[] {
  const pool = Object.values(PROJECTIONS).sort((a, b) => projPts(b) - projPts(a) || a.playerId.localeCompare(b.playerId));
  const taken = new Set<string>();
  const teams = Array.from({ length: N_TEAMS }, () => ({ starters: new Array<string>(SLOTS.length).fill(''), bench: [] as string[] }));
  const rounds = SLOTS.length + BENCH;
  // Value-based: delay K/DEF to the last starter rounds by penalizing them.
  const value = (p: PlayerProjection) => projPts(p) - (p.position === 'K' || p.position === 'DEF' ? 12 : 0) - (p.position === 'QB' ? 6 : 0);
  const rng = createRng(seedFrom('demo-draft-v2'));
  for (let r = 0; r < rounds; r++) {
    const order = r % 2 === 0 ? [...teams.keys()] : [...teams.keys()].reverse();
    for (const ti of order) {
      const t = teams[ti];
      const open = SLOTS.map((s, i) => (t.starters[i] ? null : s)).filter(Boolean) as (Position | 'FLEX')[];
      const fits = (p: PlayerProjection) => open.some((s) => s === p.position || (s === 'FLEX' && ['RB', 'WR', 'TE'].includes(p.position)));
      const benchOk = (p: PlayerProjection) => p.position !== 'K' && p.position !== 'DEF' && p.position !== 'QB';
      const cands = pool.filter((p) => !taken.has(p.playerId) && (open.length ? fits(p) : benchOk(p)));
      if (!cands.length) continue;
      cands.sort((a, b) => value(b) - value(a) || a.playerId.localeCompare(b.playerId));
      // Managers aren't perfect: pick among the top 4 (biased to the best) so teams end up uneven.
      const u = rng.next();
      const pick = cands[Math.min(cands.length - 1, u < 0.45 ? 0 : u < 0.7 ? 1 : u < 0.88 ? 2 : 3)];
      taken.add(pick.playerId);
      if (open.length) {
        let idx = SLOTS.findIndex((s, i) => !t.starters[i] && s === pick.position);
        if (idx < 0) idx = SLOTS.findIndex((s, i) => !t.starters[i] && s === 'FLEX');
        t.starters[idx] = pick.playerId;
      } else {
        t.bench.push(pick.playerId);
      }
    }
  }
  return teams;
}

const TEAM_NAMES: [string, string][] = [
  ["Mike's Mob", 'Mike'], ['Josh Allen Fan Club', 'Josh'], ['Bye Week Heroes', 'Priya'], ['Waiver Wire Wizards', 'Marcus'],
  ["CMC's Hamstring", 'Tasha'], ['Tank Commander', 'Leo'], ['Fourth and Long', 'Nina'], ['Kelce Grammar', 'Chris'],
  ['Return of the Mac', 'Sam'], ['Bench Mob', 'Omar'],
];

function buildLeague(): League {
  const drafted = draft();
  const totals = drafted.map((t) => t.starters.reduce((s, id) => s + (id ? projPts(PROJECTIONS[id]) : 0), 0));
  // Matchup 1: pick the pair whose projected gap is closest to ~9 points (≈ a 60-65% favorite).
  let best: [number, number] = [0, 1], bestErr = Infinity;
  for (let i = 0; i < N_TEAMS; i++) for (let j = 0; j < N_TEAMS; j++) {
    if (i === j) continue;
    const gap = totals[i] - totals[j];
    if (gap <= 0) continue;
    const err = Math.abs(gap - 9);
    if (err < bestErr) { bestErr = err; best = [i, j]; }
  }
  const rest = [...drafted.keys()].filter((k) => k !== best[0] && k !== best[1]).sort((a, b) => totals[b] - totals[a]);
  // Mix the other pairings: a big favorite, a coin flip, a moderate edge...
  const mix = [rest[0], rest[9], rest[1], rest[2], rest[3], rest[7], rest[4], rest[5], rest[6], rest[8]].filter((x) => x !== undefined);
  const order = [best[0], best[1], ...mix];
  const teams: FantasyTeam[] = order.map((di, idx) => {
    const rosterId = idx + 1;
    const [name, manager] = rosterId === 1 ? ["Shain's Squad", 'You'] : rosterId === 2 ? ["Dave's Dynasty", 'Dave'] : TEAM_NAMES[idx - 2];
    const d = drafted[di];
    return {
      rosterId, ownerId: `demo-u${rosterId}`, name, managerName: manager, avatar: null,
      starters: [...d.starters], players: [...d.starters.filter(Boolean), ...d.bench],
      record: { wins: (rosterId * 5) % 8, losses: 7 - ((rosterId * 5) % 8), ties: 0 },
    };
  });
  const matchups: Matchup[] = [];
  for (let m = 0; m < N_TEAMS / 2; m++) matchups.push({ matchupId: m + 1, week: 8, teamA: 2 * m + 1, teamB: 2 * m + 2 });
  return {
    platform: 'demo', leagueId: 'demo-dynasty-degenerates', name: 'Dynasty Degenerates', season: '2026', week: 8,
    scoring: { ...PPR }, rosterPositions: [...SLOTS, ...Array.from({ length: BENCH }, () => 'BN')],
    teams, matchups, myRosterId: 1, isSample: true,
  };
}

export const DEMO_LEAGUE: League = buildLeague();

