// ---------------------------------------------------------------- live replay
interface FinalGame { home: number; away: number }
interface FinalPlayer { volume: Record<string, number>; events: Record<string, number[]> }

// Seed chosen so the sample Sunday is a sweat: You dip to ~34% mid-afternoon, then come back and win.
export let FINAL_TAG = 'demo-final-18';
let FINALS = buildFinals();
/** Testing hook: rebuild the replay with another seed tag. */
export function _setFinalTag(tag: string) { FINAL_TAG = tag; FINALS = buildFinals(); }
function buildFinals() { return (() => {
  const games: Record<string, FinalGame> = {};
  const teamFactor: Record<string, number> = {};
  for (const g of DEMO_GAMES) {
    const rng = createRng(seedFrom(`${FINAL_TAG}|${g.gameId}`));
    const total = Math.max(17, (g.impliedTotal ?? 44) + 10 * rng.normal());
    const spread = (g.spread ?? 0) + 13 * rng.normal();
    const home = Math.max(0, Math.round((total + spread) / 2)), away = Math.max(0, Math.round((total - spread) / 2));
    games[g.gameId] = { home, away };
    const expH = ((g.impliedTotal ?? 44) + (g.spread ?? 0)) / 2, expA = ((g.impliedTotal ?? 44) - (g.spread ?? 0)) / 2;
    teamFactor[g.home] = Math.min(2.5, Math.max(0.2, home / Math.max(1, expH)));
    teamFactor[g.away] = Math.min(2.5, Math.max(0.2, away / Math.max(1, expA)));
  }
  const players: Record<string, FinalPlayer> = {};
  for (const p of Object.values(PROJECTIONS)) {
    const rng = createRng(seedFrom(`${FINAL_TAG}|${p.playerId}`));
    const f = teamFactor[p.team] ?? 1;
    const fp: FinalPlayer = { volume: {}, events: {} };
    for (const def of STAT_CATALOG) {
      const mu = p.mean[def.key];
      if (!mu || def.kind === 'script') continue;
      const m = def.driver === 'none' ? mu : mu * f;
      if (def.kind === 'volume') fp.volume[def.key] = Math.round(rng.gammaMeanCv(m, def.cv ?? 0.5));
      else {
        const n = rng.poisson(def.kind === 'td' ? mu * Math.pow(f, 1.4) : m);
        fp.events[def.key] = Array.from({ length: n }, () => rng.next()).sort((a, b) => a - b);
      }
    }
    if (fp.events.rec && fp.events.rec_tgt && fp.events.rec.length > fp.events.rec_tgt.length) fp.events.rec = fp.events.rec.slice(0, fp.events.rec_tgt.length);
    players[p.playerId] = fp;
  }
  return { games, players };
})(); }

/** Share of the game played at demo time t, 0..1. */
function progressAt(gameId: string, t: number): number {
  const s = WAVE_START[gameId] ?? 0;
  return Math.min(1, Math.max(0, (t - s) / GAME_LEN));
}

/**
 * Deterministic live replay for the "sweat it" view. t in [0, 1] = share of the Sunday elapsed. Three kickoff waves
 * (t 0.00, 0.40, 0.75), each game lasting 0.25 of t. Same t -> identical output.
 */
export function demoLiveAt(t: number): { games: NflGame[]; live: Record<string, PlayerLive> } {
  const tt = Math.min(1, Math.max(0, Number.isFinite(t) ? t : 0));
  const games: NflGame[] = DEMO_GAMES.map((g) => {
    const prog = progressAt(g.gameId, tt);
    const fin = FINALS.games[g.gameId];
    const status = prog <= 0 ? 'scheduled' : prog >= 1 ? 'complete' : 'in_progress';
    const out: NflGame = { ...g, status, fractionRemaining: 1 - prog };
    if (status !== 'scheduled') {
      out.homeScore = Math.round(fin.home * prog);
      out.awayScore = Math.round(fin.away * prog);
    }
    return out;
  });
  const live: Record<string, PlayerLive> = {};
  for (const p of Object.values(PROJECTIONS)) {
    const g = games.find((x) => x.home === p.team || x.away === p.team);
    if (!g || g.status === 'scheduled') continue;
    const prog = 1 - (g.fractionRemaining ?? 1);
    const fp = FINALS.players[p.playerId];
    const actual: StatLine = {};
    for (const [k, v] of Object.entries(fp.volume)) { const x = Math.round(v * prog); if (x > 0) actual[k] = x; }
    for (const [k, times] of Object.entries(fp.events)) { const n = times.filter((u) => u <= prog).length; if (n > 0) actual[k] = n; }
    if (p.position === 'DEF' && g.status === 'complete') {
      const fin = FINALS.games[g.gameId];
      actual.pts_allow = g.home === p.team ? fin.away : fin.home;
      actual.yds_allow = Math.round(actual.pts_allow * 15.2 + 120);
    }
    live[p.playerId] = { playerId: p.playerId, actual, fractionRemaining: g.fractionRemaining ?? 0 };
  }
  return { games, live };
}
