/** Win-chance line for the viewer (or team A), with the sample-Sunday controls above it. Owner: WP-12. */
import { useApp, playDemo, setDemoT, stopDemo, type ProbPoint } from '../../state/store';
import { ProbabilityLine } from '../../components/ProbabilityLine';
import { clock, pct } from '../../lib/format';
import { teamName, type View } from './model';

/** Epoch-ms x values are wall-clock points; demo replay x values are 0..1. */
const EPOCH_LIKE = 1e11;

export function Chart({ v }: { v: View }) {
  const s = useApp();
  const id = v.matchup.matchupId;
  const demo = v.league.platform === 'demo';
  const pregame = s.demoT === null;
  const raw = s.history[id] ?? [];
  // Keep one x domain per mode so pregame clock points and replay points never share an axis.
  const sameDomain = raw.filter((p) => (p.x > EPOCH_LIKE) === pregame);
  const base = sameDomain.length ? sameDomain : raw;
  const flip = v.viewer === 'B';
  const series: ProbPoint[] = base.map((p) => ({ ...p, pA: flip ? 1 - p.pA : p.pA }));
  const low = series.reduce<ProbPoint | null>((m, p) => (!m || p.pA < m.pA ? p : m), null);

  const title = v.viewer ? 'Your win chance since kickoff' : `${teamName(v.teams.A, 'A')} win chance`;
  const t = Math.round((s.demoT ?? 0) * 100);

  return (
    <div className="mx-chart-body">
      {demo && (
        <div className="mx-demo">
          <button type="button" className="btn mx-demo-btn" onClick={() => (s.demoPlaying ? stopDemo() : playDemo())}>
            {s.demoPlaying ? 'Pause' : 'Play'}
          </button>
          <label className="visually-hidden" htmlFor="mx-scrub">Scrub the sample Sunday</label>
          <input
            id="mx-scrub"
            className="mx-range"
            type="range"
            min={0}
            max={1}
            step={0.01}
            value={s.demoT ?? 0}
            aria-valuetext={pregame ? 'Pregame' : `${t}% through Sunday`}
            onChange={(e) => { void setDemoT(Number(e.target.value)); }}
          />
          <span className="small muted tnum mx-demo-read">{pregame ? 'Pregame' : `${t}% through`}</span>
          {!pregame && (
            <button type="button" className="btn mx-demo-btn" onClick={() => { void setDemoT(null); }}>Pregame</button>
          )}
        </div>
      )}
      <div className="mx-chart-head">
        <h2 className="h2">{title}</h2>
        {low && series.length >= 3 && (
          <span className="small muted tnum">
            Low {pct(low.pA)}{low.x > EPOCH_LIKE ? ` at ${clock(low.x)}` : ''}
          </span>
        )}
      </div>
      <ProbabilityLine points={series} height={200} xDomain={pregame ? undefined : [0, 1]} />
      {series.length < 2 && (
        <p className="small muted">{demo ? 'The line starts moving at kickoff. Press Play to watch a sample Sunday.' : 'The line starts moving at kickoff and updates every minute while games are on.'}</p>
      )}
    </div>
  );
}
