/** "What moves this": the players who swing the matchup most, and how each is doing. Owner: WP-12. */
import { swing } from '../../lib/format';
import { driverStatus, ownerText, toneOf, type View } from './model';

export function Drivers({ v }: { v: View }) {
  if (!v.price) return <div className="skeleton" style={{ height: 120 }} />;
  const drivers = v.price.drivers ?? [];
  return (
    <div>
      <h2 className="h2">What moves this</h2>
      {drivers.length === 0 ? (
        <p className="small muted mx-empty-line">Nothing in this matchup swings the result much yet.</p>
      ) : (
        <div className="rows mx-drv-list">
          {drivers.map((d) => {
            const tone = toneOf(v, d.side);
            const pos = d.position !== 'UNK' ? d.position : null;
            const who = [pos, ownerText(v, d.side)].filter(Boolean).join(', ');
            return (
              <div className="row mx-drv" key={d.playerId}>
                <span className="mx-drv-name">
                  <span>{d.name}</span> <span className="muted">{who}</span>
                </span>
                <span className="muted small mx-drv-status">{driverStatus(v, d)}</span>
                <span className="mx-drv-swing tnum" style={{ color: tone.color }}>{swing(d.swingPts)}</span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
