/** Promise wrapper around the pricing worker, with a main-thread fallback. Owner: Commander. */
import type { League, WeekContext, MatchupPrice } from '@fmm/core';
import { priceLeague } from '@fmm/engine';
import type { PriceResponse } from './pricing.worker';

let worker: Worker | null = null;
let nextId = 1;
const pending = new Map<number, { resolve: (p: MatchupPrice[]) => void; reject: (e: Error) => void }>();

function getWorker(): Worker | null {
  if (worker) return worker;
  try {
    worker = new Worker(new URL('./pricing.worker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = (e: MessageEvent<PriceResponse>) => {
      const p = pending.get(e.data.id);
      if (!p) return;
      pending.delete(e.data.id);
      if (e.data.error || !e.data.prices) p.reject(new Error(e.data.error ?? 'pricing failed'));
      else p.resolve(e.data.prices);
    };
    worker.onerror = () => { worker = null; };
    return worker;
  } catch {
    return null;
  }
}

export function priceInBackground(league: League, ctx: WeekContext, sims: number, seed?: number): Promise<MatchupPrice[]> {
  const w = getWorker();
  if (!w) return Promise.resolve(priceLeague(league, ctx, { sims, seed }));
  const id = nextId++;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    w.postMessage({ id, league, ctx, sims, seed });
  });
}
