/** App shell: desktop rail / mobile tab bar + routed page. Owner: Commander. */
import { useEffect } from 'react';
import { useRoute, href, type Route } from './lib/router';
import { useApp, boot, balanceCc } from './state/store';
import { coins } from './lib/format';
import { HomePage } from './pages/HomePage';
import { ConnectPage } from './pages/ConnectPage';
import { MatchupPage } from './pages/MatchupPage';
import { LeaguePage } from './pages/LeaguePage';
import { FeaturedPage } from './pages/FeaturedPage';
import { PortfolioPage } from './pages/PortfolioPage';
import { ModelPage } from './pages/ModelPage';

const NAV: { label: string; route: Route }[] = [
  { label: 'Home', route: { name: 'home' } },
  { label: 'League board', route: { name: 'league' } },
  { label: 'Featured', route: { name: 'featured' } },
  { label: 'Portfolio', route: { name: 'portfolio' } },
  { label: 'How good is the number', route: { name: 'model' } },
];

function Wordmark() {
  return <a className="wordmark" href={href({ name: 'home' })} aria-label="Matchup Market home"><span>MATCHUP</span><span>MARKET</span></a>;
}

export function App() {
  const route = useRoute();
  const s = useApp();
  useEffect(() => { void boot(); }, []);
  const bal = balanceCc();
  const active = (r: Route) => (r.name === route.name || (r.name === 'home' && route.name === 'matchup') ? 'page' : undefined);
  return (
    <div className="shell">
      <aside className="rail">
        <div>
          <Wordmark />
          <nav className="nav" aria-label="Main">
            {NAV.map((n) => <a key={n.label} href={href(n.route)} aria-current={active(n.route)}>{n.label}</a>)}
            <a href={href({ name: 'connect' })} aria-current={route.name === 'connect' ? 'page' : undefined}>Connect a league</a>
          </nav>
        </div>
        <div className="balance">
          <span className="small muted">League Mode coins</span>
          <span className="num" data-version={s.bookVersion}>{coins(bal)}</span>
        </div>
      </aside>
      <main className="main">
        <div className="mobile-top">
          <Wordmark />
          <span className="small muted tnum">{coins(bal)} coins</span>
        </div>
        {route.name === 'home' && <HomePage />}
        {route.name === 'connect' && <ConnectPage />}
        {route.name === 'matchup' && <MatchupPage matchupId={route.matchupId} />}
        {route.name === 'league' && <LeaguePage />}
        {route.name === 'featured' && <FeaturedPage />}
        {route.name === 'portfolio' && <PortfolioPage />}
        {route.name === 'model' && <ModelPage />}
      </main>
      <nav className="tabbar" aria-label="Main">
        {NAV.map((n) => <a key={n.label} href={href(n.route)} aria-current={active(n.route)}>{n.label === 'League board' ? 'League' : n.label === 'How good is the number' ? 'Model' : n.label}</a>)}
      </nav>
    </div>
  );
}
