/**
 * Matchup page: scoreboard, win-chance line, what moves it, most likely, both lineups, and the ticket ("Call it").
 * Desktop: main column + 360px ticket on the right. Phone: stacked, ticket straight after the scoreboard.
 * Owner: WP-12.
 */
import { useApp, loadDemo } from '../state/store';
import { href } from '../lib/router';
import { SourceBadge, LiveBadge } from '../components/SourceBadge';
import { buildView } from './matchup/model';
import { Scoreboard, Likely } from './matchup/Scoreboard';
import { Chart } from './matchup/Chart';
import { Drivers } from './matchup/Drivers';
import { Lineups } from './matchup/Lineups';
import { Ticket } from './matchup/Ticket';
import './matchup.css';

export function MatchupPage({ matchupId }: { matchupId: number }) {
  const s = useApp();
  const league = s.league;

  if (!league || !Array.isArray(league.matchups)) {
    if (s.status === 'error') return <LoadError message={s.error} />;
    if (s.status === 'ready') {
      return (
        <Empty
          title="No league loaded"
          body="Connect a Sleeper league to see its matchups, or go back to the sample league."
          link={{ href: href({ name: 'connect' }), label: 'Connect a league' }}
        />
      );
    }
    return <Loading />;
  }

  const matchup = league.matchups.find((m) => m.matchupId === matchupId);
  if (!matchup) {
    return (
      <Empty
        title={`No matchup ${matchupId} in this league.`}
        body="It may belong to another week or league."
        link={{ href: href({ name: 'home' }), label: 'Back to home' }}
      />
    );
  }

  const v = buildView(
    league,
    s.ctx,
    matchup,
    s.prices?.find((p) => p.matchupId === matchupId),
    s.finals[matchupId] as { pointsA: number; pointsB: number } | undefined,
  );

  return (
    <>
      <a className="small muted mx-back" href={href({ name: 'home' })}>Back to home</a>
      {s.status === 'error' && <LoadError message={s.error} />}
      <div className="mx">
        <header className="mx-ctx">
          <span className="small muted">{league.name}, week {league.week}</span>
          <span className="mx-ctx-badges">
            <SourceBadge />
            {v.live && (
              <LiveBadge text={`Live, ${v.liveGames} ${v.liveGames === 1 ? 'game' : 'games'} in progress`} />
            )}
          </span>
        </header>

        <section className="mx-board" aria-label="Scoreboard">
          <Scoreboard v={v} />
        </section>

        <section className="mx-ticket" aria-labelledby="mx-call-h">
          <Ticket v={v} />
        </section>

        <section className="mx-chart" aria-label="Win chance">
          <Chart v={v} />
        </section>

        <section className="mx-drivers" aria-label="What moves this">
          <Drivers v={v} />
        </section>

        <section className="mx-likely" aria-label="Most likely result">
          <Likely v={v} />
        </section>

        <section className="mx-lineups" aria-label="Lineups">
          <Lineups v={v} />
        </section>
      </div>
    </>
  );
}

function Loading() {
  return (
    <div className="mx-loading" aria-busy="true" aria-label="Loading matchup">
      <div className="skeleton" style={{ height: 14, width: 220 }} />
      <div className="skeleton" style={{ height: 150, width: '100%' }} />
      <div className="skeleton" style={{ height: 200, width: '100%' }} />
    </div>
  );
}

function LoadError({ message }: { message?: string }) {
  return (
    <div className="panel mx-error">
      <p className="error">Couldn't load prices for this league.{message ? ` ${message}` : ''}</p>
      <button type="button" className="btn" onClick={() => { void loadDemo(); }}>Try again</button>
    </div>
  );
}

function Empty({ title, body, link }: { title: string; body: string; link: { href: string; label: string } }) {
  return (
    <div className="empty">
      <h1 className="h2">{title}</h1>
      <p className="muted">{body}</p>
      <a className="btn" href={link.href}>{link.label}</a>
    </div>
  );
}
